window.__FEED__ = {"last_updated":"2026-10-30T13:01:56+08:00","total":420,"items":[{"title":"FDA says it plans to propose new rules related to infant formula","summary":"美国食品药品监督管理局（FDA）计划提出与婴幼儿奶粉相关的新规则。此举旨在加强婴幼儿奶粉的监管，确保产品质量和安全性。对跨境电商和母婴行业的从业者而言，这意味着需要密切关注政策变化，及时调整产品策略以符合新的法规要求。这类监管更新通常反映了市场对产品安全性和营养性的更高关注，从业者需确保产品符合标准，以维护市场信誉和消费者信任。","source_id":"gnews_en_reg","source_name":"www.foodsafetynews.com","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://news.google.com/rss/articles/CBMipwFBVV95cUxQd2RVWHdfRldXZWdtX1pKZlhuajl5QzV1eGgzNkUxMVZRYzlVT21lQU5aeW9UZWt2SzVxNk1PeTlPbW1kTURCTXJDcDNTSEJNT2Vkal9ocld2aEhxMXR4WTdwQVZzTU5mcHpRRmtUUzhEdktJN3B2ZE1vQVZzUUZlamptcFVsX3dHV3h6cElBbUZoNVM1WnI0YUhSeUZzemlSMHdDdVpQOA","published_at":"2026-10-30T12:06:40+08:00","published_guessed":false,"fetched_at":"2026-10-30T13:03:03+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"2dc1284b95c0cb99","title_zh":"FDA 计划提出与婴幼儿奶粉相关的新规则","summary_source":"llm","summary_kind":"brief","points":["FDA 计划提出新规则","加强婴幼儿奶粉监管","确保产品质量和安全性","要求从业者关注政策变化"],"points_source":"llm","translated":true},{"title":"Trump Administration Proposes New Baby Formula Rules","summary":"特朗普政府提议推出新的婴儿奶粉规则，具体内容未详细披露。这一举动可能对婴幼儿奶粉行业的监管政策产生影响，对跨境母婴行业从业者意味着需密切关注政策变化，评估潜在影响并调整业务策略。","source_id":"gnews_en_reg","source_name":"Newsmax","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.newsmax.com/health/health-news/hhs-fda-rfk-jr/2026/10/29/id/1274529/","published_at":"2026-10-30T10:29:02+08:00","published_guessed":false,"fetched_at":"2026-10-30T11:04:36+08:00","language":"en","author":"","tags":["政策法规"],"priority":"P0","score":8.0,"matched":["baby formula"],"id":"79e5f572abf88638","title_zh":"特朗普政府拟推出新婴儿奶粉规则","summary_source":"llm","summary_kind":"brief","points":["特朗普政府提议新规则","可能影响奶粉行业监管"],"points_source":"llm","translated":true,"link_resolved":true},{"title":"深度捆绑蜜雪冰城，君乐宝要在新茶饮下一盘大棋！","summary":"君乐宝乳业集团与蜜雪集团在河北石家庄签署全面深度战略合作协议，双方将在供应链共建、品牌联动、海外拓展等方面展开合作。君乐宝旗下高端鲜奶悦鲜活将成为蜜雪集团鲜奶品类核心供应商，共同推动供应覆盖扩大，优先保障蜜雪体系门店的鲜奶供给。双方将聚焦高蛋白乳品、冰淇淋原料等品类开展联合创新，统一奶源管控、品质检测、冷链运输、食品安全标准。以东南亚等区域为重点，共同探索乳品原料的海外供应、本地化研发与冷链协同。","source_id":"foodaily","source_name":"Foodaily 每日食品","source_url":"https://www.foodaily.com/","original_url":"https://www.foodaily.com/articles/42529","published_at":"","published_guessed":true,"fetched_at":"2026-10-30T09:20:54+08:00","language":"zh","author":"","tags":["品牌动态","供应链","跨境电商"],"priority":"P1","score":4.8,"matched":["君乐宝"],"id":"b65108c8fb37d6c6","image":"https://cdn.img.foodaily.com/images/articles/2026/10/30/1793322508_SO2456WmwnkpMB4O.jpeg","body":"10月27日，君乐宝乳业集团与蜜雪集团在河北石家庄签署了全面深度战略合作协议，双方将在供应链共建、品牌联动、海外拓展等方面展开深度合作。 供应链层面，君乐宝旗下高端鲜奶悦鲜活将成为蜜雪集团鲜奶品类核心供应商，双方共同推动供应覆盖的扩大，优先保障蜜雪体系门店的鲜奶供给与货源稳定。研发层面，双方将聚焦高蛋白乳品、冰淇淋原料、风味乳、奶盖、酸奶原料等品类开展联合创新，统一奶源管控、品质检测、冷链运输、食品安全标准，深化上游奶源基地共建，推进产品全链路溯源体系建设。海外业务布局层面，双方将以东南亚等区域为重点，共同探索乳品原料的海外供应、本地化研发与冷链协同。 双方合作的基础源于产业能力的高度互补。君乐宝已搭建起完整奶业全产业链体系，截至2026年6月，拥有33座自营牧场、20座生产工厂，奶牛存栏19.8万头，奶源自给率约63%，实现全链路自主可控。蜜雪集团凭借规模庞大的门店网络，直面数亿消费者，庞大市场催生对高品质乳制品的持续规模化需求，同时可将终端消费需求反馈至上游，形成供需双向联动的基础。 蜜雪集团方面表示，鲜奶升级是蜜雪集团围绕“真鲜纯”产品理念、系统性推进全品类原料升级的组成部分，预计2028年实现全国门店鲜奶覆盖。目前，蜜雪冰城和幸运咖已有约1.5万家门店引入低温鲜奶，覆盖现磨咖啡、奶茶等产品，消费者在蜜雪冰城小程序花8元左右购买一杯黑糖珍珠鲜牛乳，其中便加入了约200mL悦鲜活冷链鲜奶。 公开资料显示，悦鲜活是君乐宝旗下高端鲜奶品牌，通过中国优质乳工程特优级生乳原料认证，创新采用INF0.09秒超瞬时杀菌技术，率先使用医药级无菌冷灌装，并构建了全产业链一体化锁鲜体系，产品已进入中国香港、新加坡市场。据君乐宝港股IPO招股书中的数据，2025年上半年，悦鲜活营收10.60亿元，全年营收26.17亿元；2026年上半年营收17.72亿元，同比大涨67%。 事实上，早在2024年年底，君乐宝就与蜜雪集团达成了战略合作，在河南新乡合资建设君乐宝×蜜雪冰城“雪王牧场”。“按当时披露的计划，该牧场面积约800亩，计划引入8000头荷斯坦高产奶牛，借助科学的饲养方式和全程质量追溯等手段，确保产品质量的可控性。牧场预计年产奶量可达到4.2万吨，主要用于满足蜜雪冰城的原料奶需求，预计2025年6月正式投产。 本次签约是双方合作关系的进一步升级。蜜雪集团方面表示，未来将与悦鲜活在奶源建设、产品研发、质量品控、品牌协同、供应链及海外业务等领域持续探索，共同推动现制饮品进入鲜奶时代，为消费者提供更高品质、更高性价比的产品。 新乳业注意到，除了君乐宝与蜜雪集团的合作，还有很多乳企也在嵌入新茶饮的供应链条。有的是像悦鲜活一样供应鲜牛奶，也有的将牛奶中的乳脂、蛋白、风味拆开重组，开发出厚乳、冰博克、稀奶油、非氢化基底乳、奶盖浆等深加工产品，在新茶饮赛道展开了新的竞争。 伊利以“索非蜜斯”和“伊利专业乳品”双线切入，牵手奈雪、沪上阿姨等品牌，2026年上半年，其面向餐饮客户的奶酪、乳脂业务实现营收双位数增长；蒙牛2021年推出“蒙牛专业乳品”，产品已铺到蜜雪冰城等头部客户；新希望乳业旗下朝日唯品打进Manner、Seesaw、M Stand的精品咖啡圈层后，又进入到了喜茶、阿嬷手作等品牌门店，2025年机构客户业务收入18.3亿元，两年复合增速18.4%；皇氏集团靠水牛奶的品类差异切进霸王茶姬、古茗、茶百道和乐乐茶等；认养一头牛则以低温奶、淡奶油和冰淇淋球打入古茗与奈雪，覆盖门店超10000家，古茗新近爆款“椰椰冰淇淋拿铁”顶上的冰淇淋球，就来自认养一头牛…… 除了作为供应商，也有一些乳企亲自端起了奶茶杯。比如君乐宝，战略入股茉酸奶，持股比例达到42.86%，从奶源方变成了品牌合伙人；三元股份在重启“北京市牛奶公司”做现打鲜奶的同时，出资收购了必如食品42%股权，后者正是“冰博克”的开创者，客户覆盖茶颜悦色、CoCo、茶百道和奈雪等；皇氏集团继续发挥水牛奶的优势，打造了“在桂里”品牌，从供应商变成了主理人…… 在新乳业看来，乳企跨界新茶饮的背后，一方面是原奶过剩让基础白奶的利润越来越薄，而奶酪、乳脂、蛋白浓缩物等深加工产品能显著提升毛利空间；另一方面，新茶饮的升级换代趋势下，真奶、0反式脂肪酸、可追溯奶源成为了品牌们的新卖点，乳企恰好能满足它们的需求。 同时也可以看出，乳企与新茶饮的深度融合，正从单一原料供应向全链路共创演进。这场“双向奔赴”不仅为乳业开辟了新增长曲线，也推动着新茶饮迈入了“鲜奶时代”。","points":["君乐宝与蜜雪集团战略合作","悦鲜活成蜜雪鲜奶核心供应商","聚焦高蛋白乳品等品类联合创新","共同探索东南亚乳品海外供应"],"points_source":"llm","summary_source":"llm","title_zh":"深度捆绑蜜雪冰城，君乐宝要在新茶饮下一盘大棋！","translated":true},{"title":"金华老板卖纸尿裤，9个月进账30亿","summary":"浙江金华一位企业家通过销售纸尿裤，9个月内实现30亿元销售额。这一业绩凸显了纸尿裤市场的巨大潜力，尤其在中西部地区。对母婴行业从业者而言，该案例表明深耕区域市场、优化供应链管理、提升品牌影响力是获取市场份额的关键，值得借鉴。","source_id":"gnews_cn_baby_category","source_name":"21财经","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.21jingji.com/article/20261030/herald/749247c6a715d3b23ae310daa5944652.html","published_at":"2026-10-30T07:59:00+08:00","published_guessed":false,"fetched_at":"2026-10-30T11:04:06+08:00","language":"zh","author":"","tags":["市场数据","供应链","品牌动态"],"priority":"P1","score":4.8,"matched":["纸尿裤"],"id":"6e1790ddcb085ac0","title_zh":"金华老板卖纸尿裤，9个月进账30亿","summary_source":"llm","summary_kind":"brief","points":["金华纸尿裤销售9个月达30亿","深耕区域市场重要性","优化供应链管理必要性"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月27日，李氏实控的豪悦护理，交出成绩单。1-9月，营收接近30亿元，同比增长8%；净利润微降至2亿元。 “客户有Babycare、宝洁等品牌。”豪悦投关工作人员向《21CBR》记者介绍。 李志彪，浙江金华人，现年59岁。眼下，他带领公司打造自有品牌，试图从幕后走向台前，由国内走向亚非拉。 截至9月，李志彪和配偶朱威莉、女儿李诗源三人，合计持股约66%，为共同实控人。《2025年胡润百富榜》上，李志彪家族以51亿元身家，排名第1365位。 成人卫生用品收入5.31亿元，占比接近三成，毛利率36%；“其他产品”收入3.07亿元，占比15.66%，毛利率高达56.14%。 “为了支持客户终端市场品牌竞争，ODM业务降价让利，影响盈利水平。”管理层解释。 从2020年起，他便开启一场转型，要成为多品牌运营商，慢慢构建起一个“代工+并购+自有”三轨并行的业务体系。 首先，推出“答菲”品牌，以“原生木浆+EDI纯水”配方切入湿厕纸赛道，并增加厨房湿巾、纯水湿巾、棉柔洗脸巾等家护产品，主打性价比。 1-6月，湿厕纸、湿巾等品类在内的“其他产品”，入账3亿元，同比大增六成，是豪悦增速最快的业务板块。 去年初，李志彪斥资3.6亿元，收购丝宝护理100%股权，拿下女性护理品牌“洁婷”，由此全年成人卫生用品收入大增1.3倍。 1-6月入账5.3亿元，同比下降16.8%。被寄予厚望的丝宝护理，亏损约1921万元，拖累业绩。 “现在有很多新厂家或平台加入，卫生巾市场竞争激烈。”投关工作人员向《21CBR》记者解释。 对于洁婷，李志彪锚定“专研+安心”产品路线，依托自研专利芯体，打造“吸隐力”等产品，以提升产品单价，跳出低价竞争泥潭。 线下，豪悦夯实湖北、河南、河北、山东核心市场，积极开拓广东、浙江等潜力区域，还切入即时零售和O2O渠道。","image":"https://ocmsmedia.sfccn.com/vod-4310da/image/default/1155F94B4DFF4C8FAB751C649812EB6A-6-2.png"},{"title":"FDA Proposes Changes to Infant Formula Nutrition Standards","summary":"美国食品药品监督管理局（FDA）提出婴儿配方奶粉营养标准修订草案，这是自1998年以来的首次全面审查。新标准旨在反映当前科学研究成果，涉及碘、锰、维生素A和D等营养素要求。草案公开征求意见至2027年2月26日，对行业合规和产品配方设计有直接影响。从业者需关注标准变化，及时调整产品以满足新要求。","source_id":"gnews_en_reg","source_name":"Dailyfly News","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.dailyfly.com/2026/10/29/fda-proposes-changes-to-infant-formula-nutrition-standards/","published_at":"2026-10-30T07:06:16+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:54+08:00","language":"en","author":"","tags":["政策法规","质量安全"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"5e06c7b0db5daac0","title_zh":"FDA拟修改婴幼儿奶粉营养标准","summary_source":"llm","summary_kind":"brief","points":["FDA提议修改婴幼儿奶粉营养标准"],"points_source":"llm","translated":true,"link_resolved":true,"body":"WASHINGTON, D.C. — The U.S. Food and Drug Administration (FDA) announced Thursday, October 29, proposed changes to infant formula nutrient requirements as part of its first comprehensive review of the standards since 1998. The proposal is the first of three planned phases aimed at updating nutritional requirements for infant formula sold in the United States. The changes are intended to reflect current scientific research on infant growth and development. The initial proposal would update requirements for iodine, manganese, vitamin A and vitamin D, while maintaining existing requirements for chloride, potassium, selenium and sodium. The FDA is also seeking public input on additional nutrients commonly included in infant formula, including ingredients associated with brain and nervous system development. Future phases of the review will examine additional nutrients, potential new requirements and carbohydrate sources. The FDA plans to combine the changes into a single final rule. Alongside the proposal, the FDA released new chemical contaminant testing results for infant formula products. According to the agency, most samples tested contained low or undetectable levels of chemical contaminants, consistent with findings released earlier this year. The FDA also introduced an online dashboard allowing the public to review infant formula contaminant testing results. The agency said it will continue monitoring contaminants and working toward establishing action levels for certain substances. The proposed nutrient changes are not yet final. Parents, healthcare professionals, researchers and manufacturers are invited to submit public comments through February 26, 2027 . Comments can be submitted through Regulations.gov using docket number FDA-2026-56789 . The announcement is part of a broader federal initiative to review infant formula safety and nutritional standards.","image":"https://dehayf5mhw1h7.cloudfront.net/wp-content/uploads/sites/2472/2026/10/29155122/chatgpt-image-oct-29-2026-03_50_47-pm-1024x576.jpg"},{"title":"FDA Proposes Rule to Update Infant Formula Nutrient Requirements","summary":"美国食品药品监督管理局提出新规，旨在更新婴幼儿配方奶粉的营养成分要求。这一监管动作将直接影响配方奶粉的原料配方标准，对全球婴幼儿配方奶粉行业的技术标准和生产规范具有参考意义。对行业从业者而言，需密切关注新规内容，及时调整产品配方和生产流程以符合新标准，确保产品符合法规要求，维护市场竞争力。","source_id":"gnews_en_reg","source_name":"The National Law Review","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://natlawreview.com/article/fda-proposes-rule-update-infant-formula-nutrient-requirements","published_at":"2026-10-30T06:52:13+08:00","published_guessed":false,"fetched_at":"2026-10-30T06:57:28+08:00","language":"en","author":"","tags":["政策法规","质量安全"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"b32264b21545dd06","summary_source":"llm","summary_kind":"brief","points":["FDA提出更新配方奶粉营养要求","新规将影响行业技术标准","涉及婴幼儿配方奶粉原料规范"],"points_source":"llm","translated":true,"title_zh":"美国食品药品监督管理局提出更新婴幼儿配方奶粉营养要求新规","link_resolved":true,"image":"https://natlawreview.com/sites/default/files/styles/article_image/public/2026-10/Baby%20Formula%20Child%20Childcare%20Bottle%20Powder%20Food%20Milk.jpg.webp?itok=9zTwlrZy"},{"title":"美FDA大修嬰兒配方奶粉營養標準 近30年首次","summary":"美国食品药品监督管理局（FDA）首次近30年大修婴幼儿配方奶粉营养标准，此举旨在提升婴幼儿配方奶粉的营养质量和安全性，更好地保护婴幼儿健康。新标准可能涉及蛋白质、脂肪、维生素、矿物质等关键营养素的含量要求，以及过敏原、添加剂等方面的限制。这一政策调整将对全球婴幼儿奶粉市场产生深远影响，尤其对跨境婴幼儿奶粉行业的从业者而言，需要密切关注并及时调整产品配方和生产标准以符合新规。","source_id":"gnews_zh_formula","source_name":"大紀元","source_url":"https://news.google.com/rss/search?q=%E5%A9%B4%E5%84%BF%E9%85%8D%E6%96%B9%E5%A5%B6%E7%B2%89%20OR%20%E5%A9%B4%E5%B9%BC%E5%84%BF%E5%A5%B6%E7%B2%89%20OR%20%E9%85%8D%E6%96%B9%E6%B3%A8%E5%86%8C&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.epochtimes.com/gb/26/10/29/n14879484.htm","published_at":"2026-10-30T06:49:42+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:01+08:00","language":"zh","author":"","tags":["政策法规","质量安全","海外动态"],"priority":"P0","score":16.0,"matched":["奶粉","配方奶粉"],"id":"6a4237b0e28460a1","title_zh":"美FDA大修婴幼儿配方奶粉营养标准 近30年首次","summary_source":"llm","summary_kind":"brief","points":["美FDA大修婴幼儿配方奶粉营养标准","近30年首次重大调整","提升婴幼儿配方奶粉营养质量"],"points_source":"llm","translated":true,"link_resolved":true,"body":"【大纪元2026年10月30日讯】（大纪元记者李言综合报导）美国食品药品监督管理局（FDA）于周四（10月29日）宣布，正提议一项新规则，拟全面更新婴儿配方奶粉的营养需求标准。主管FDA的美国卫生与公共服务部（HHS）指出，这是近30年来针对婴儿配方奶粉标准进行的最重大的一次修订。 HHS部长小肯尼迪（Robert F. Kennedy, Jr.）在发布的声明中强调：“父母们喂给宝宝的每一瓶奶都值得获得信任。我们将让婴儿配方奶粉制造商遵循严格的科学标准，并把婴儿的健康放在首位。” 根据FDA及HHS发布的官方资讯，本次拟议规则（Notice of Proposed Rulemaking）关键亮点包含调整特定维生素与矿物质。 具体来说，法规将更新对维生素A、维生素D、碘和锰的需求规范，并重申现行对氯化物、钾、硒和钠的要求。 FDA营养科学报告显示，维生素A与D对婴儿的免疫功能、骨骼发育及视力健全至关重要，调整至适当剂量，可防止摄取不足导致发育迟缓，或过量累积造成毒性风险。 而碘是甲状腺荷尔蒙合成的核心原料，直接影响婴儿脑部与神经系统的发育；锰则参与骨骼形成与新陈代谢，制定明确上限可避免微量元素失衡。 同时，重申氯化物、钾、硒和钠的标准，则有助于维持婴儿体内电解质平衡与器官正常运作。 对于目前法规未强制要求、但部分厂商会添加的成分，包括花生四烯酸（ARA）、二十二碳六烯酸（DHA）及左旋肉碱（L-carnitine），FDA表示将公开征求公众及专家意见。 本次修订为“鹳鸟速度行动”（Operation Stork Speed）倡议的一环。后续阶段将进一步审视其余必需营养素、潜在的新营养需求以及碳水化合物来源（如种子油的去留讨论），并最终整合为一项最终规则。 此外，FDA同步公布最新婴儿配方奶粉化学污染物检测数据，结果显示市场上绝大多数抽检样品的“化学污染物含量，均处于极低或未检出的安全水平”。","image":"https://i.epochtimes.com/assets/uploads/2023/10/id14100686-shutterstock_1300509832-700x359.jpg"},{"title":"FDA Considering Changes to Infant Formula Requirements","summary":"FDA发布了一项提案，计划更新或重申婴儿配方奶粉中八种营养素的规格。该提案是FDA对婴儿配方奶粉营养素要求的三个阶段审查的第一阶段，其余22种营养素将在后续审查中考虑。FDA的提案涉及氯、碘、锰、钾、硒、钠、维生素A和维生素D等营养素规格的调整。这一提案对跨境奶粉品牌意味着需要关注营养素规格的调整，以符合FDA的新要求。","source_id":"gnews_en_reg","source_name":"Food Processing","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.foodprocessing.com/food-safety/regulatory-compliance/news/55415496/fda-considering-changes-to-infant-formula-requirements","published_at":"2026-10-30T06:35:15+08:00","published_guessed":false,"fetched_at":"2026-10-30T06:57:28+08:00","language":"en","author":"","tags":["政策法规","质量安全","海外动态"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"fdff486f457435a3","summary_source":"llm","summary_kind":"brief","points":["FDA正在考虑修改配方奶粉要求","行业需关注后续具体条款","可能影响产品合规成本"],"points_source":"llm","translated":true,"title_zh":"FDA考虑修改婴儿配方奶粉要求","link_resolved":true,"body":"FDA published a proposed rule today (Oct. 29) that, if finalized, would update or reaffirm specifications for eight of the 30 nutrients required in infant formula. As part of the process, the agency also is asking for input on potential requirements for nutrients not currently required in infant formula but commonly added by manufacturers. This proposed rule represents the first phase of a three-part review of the nutrients required in infant formula, with the other 22 apparently being considered in subsequent reviews. Chloride: Retain the current minimum (55 mg/100 kcal) and maximum (150 mg/100 kcal) chloride levels. Iodine: Increase the minimum level from 5 µg/100 kcal to 15 µg/100 kcal and decrease the maximum level of iodine from 75 µg/100 kcal to 50 µg/100 kcal. Manganese: Decrease the minimum level of manganese from 5 µ g/100 kcal to 1 µ g/100 kcal and establish a maximum level for manganese of 50 µ g/100 kcal. Potassium: Retain the current minimum (80 mg/100 kcal) and maximum (200 mg/100 kcal) potassium levels. Selenium: Retain the current minimum (2 µg/100 kcal) and maximum (7 µg/100 kcal) selenium levels. Sodium: Retain the current minimum (20 mg/100 kcal) and maximum (60 mg/100 kcal) sodium levels. Vitamin A: Change the unit of measure for vitamin A from International Units (IU) to microgram retinol activity equivalents ( µ g RAE). Decrease the minimum level of vitamin A from 250 IU (75 µ g RAE)/100 kcal to 70 µ g RAE/100 kcal and decrease the maximum level from 750 IU (225 µ g RAE)/100 kcal to 120 µ g RAE/100 kcal. And limit permitted forms of vitamin A to preformed vitamin A only. Vitamin D: Change the unit of measure for vitamin D from IU to micrograms ( µ g). Increase the minimum level of vitamin D from 40 IU (1 µ g)/100 kcal to 2 µ g/100 kcal (80 IU/100 kcal) and increase the maximum level from 100 IU (2.5 µ g)/100 kcal to 3 µ g/100 kcal (120 IU/100 kcal). The agency also is looking for input on nutrients not currently required in infant formula but commonly added by manufacturers, including arachidonic acid (ARA), docosahexaenoic acid (DHA) and L-carnitine. “There is evidence to support that these nutrients contribute to neurodevelopmental health in infancy,” the agency said. Subsequent phases will assess the remaining required nutrients, potential new nutrient requirements and carbohydrate sources.","image":"https://img.foodprocessing.com/files/base/ebm/foodprocessing/image/2026/10/6ae3c6c77775fe7d88799060-babydreamstime_s_92478576_edited.png?auto=format,compress&fit=fill&fill=blur&w=1200&h=630"},{"title":"RFK Jr. announces latest plans to update infant formula standards","summary":"美国卫生官员RFK Jr.宣布将更新婴儿配方奶粉标准，旨在提升配方奶粉的营养安全性和质量。这一举措涉及婴幼儿配方奶粉这一核心品类，对行业监管和产品配方设计产生直接影响。作为行业从业者，需密切关注标准变化带来的合规要求调整。","source_id":"gnews_en_reg","source_name":"The Washington Post","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.washingtonpost.com/health/2026/10/29/rfk-jr-announces-latest-plans-update-infant-formula-standards/","published_at":"2026-10-30T06:34:27+08:00","published_guessed":false,"fetched_at":"2026-10-30T06:57:28+08:00","language":"en","author":"","tags":["政策法规","质量安全"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"de5ab5c9fdb221f4","title_zh":"RFK Jr.宣布更新婴儿配方奶粉标准的最新计划","summary_source":"llm","summary_kind":"brief","points":["RFK Jr.宣布更新婴儿配方奶粉标准","涉及婴幼儿配方奶粉品类","对行业监管和产品配方设计产生影响"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Trump administration released a plan Thursday to update requirements for certain nutrients in infant formula. Last year, Health Secretary Robert F. Kennedy Jr. announced an initiative dubbed “ Operation Stork Speed, ” including the first review of infant formula ingredients and nutrition in nearly 30 years. The effort is part of his Make America Healthy Again agenda, as Kennedy and his supporters seek to crack down on artificial dyes and other ingredients used in the nation’s food supply.","image":"https://www.washingtonpost.com/wp-apps/imrs.php?src=https://cloudfront-us-east-1.images.arcpublishing.com/wapo/LVBE472YIWCBTGOHZIUMVMAZUY.jpg&w=1440"},{"title":"FDA plans to update nutritional rules for infant formula","summary":"美国食品药品监督管理局（FDA）计划更新婴幼儿奶粉的营养规则。这一更新是近30年来首次对婴幼儿奶粉营养要求进行重大调整，旨在提升产品的营养价值和安全性。对跨境电商和母婴行业的从业者来说，这意味着需要重新评估产品配方，确保其符合新的营养标准。及时了解并适应这些变化，有助于企业保持市场竞争力，满足消费者对健康产品的需求。","source_id":"gnews_en_reg","source_name":"NBC New York","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://news.google.","published_at":"2026-10-30T05:30:31+08:00","published_guessed":false,"fetched_at":"2026-10-30T13:03:03+08:00","language":"en","author":"","tags":["政策法规","质量安全","市场数据"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"bf410f147a425813","title_zh":"FDA 计划更新婴幼儿奶粉营养规则","summary_source":"llm","summary_kind":"brief","points":["FDA 计划更新营养规则","近30年来首次重大调整","提升营养价值和安全性","要求从业者重新评估产品配方"],"points_source":"llm","translated":true},{"title":"Stronger milk powder demand lifts Fonterra payout forecast","summary":"新西兰乳企恒天然因全球奶粉需求强劲，上调了分红预测。报告显示东南亚、中东、非洲及中国市场需求持续增长，推动全脂和脱脂奶粉价格上涨。这一趋势对跨境乳品供应链有直接影响，从业者需关注原料供应变化和价格波动，提前规划库存和渠道策略。","source_id":"gnews_en_nz_dairy","source_name":"Farmers Weekly","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.farmersweekly.co.nz/markets/dairy-markets/stronger-milk-powder-demand-lifts-fonterra-payout-forecast/","published_at":"2026-10-30T05:23:12+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:56+08:00","language":"en","author":"","tags":["市场数据","供应链"],"priority":"P0","score":16.0,"matched":["milk powder","payout","fonterra"],"id":"d46239dfeac49e12","title_zh":"牛奶粉需求增强提振丰塔拉支付预期","summary_source":"llm","summary_kind":"brief","points":["全球牛奶粉需求增长","丰塔拉上调收益预期","乳制品行业市场可能增长","需关注供应链调整和跨境销售"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Improved demand for whole and skim milk powders has led to Fonterra lifting its forecast midpoint by 25 cents to $9.75/kg MS. It has also lifted and narrowed the forecast range from $8.50-$10.50/kg MS to $9-$10.50/kg MS. CEO Richard Allen said over the last two GDT events, WMP and SMP pricing had increased by about 5% and 7% respectively. “This is driven by sustained demand from across southeast Asia, Middle East, Africa and China. “We have also had a good start to the season, which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. “There’s plenty more to do, and we are continuing to monitor factors that could affect global supply and demand for dairy.” Fonterra has also increased its organic milk price, with the midpoint lifting from $14.30/kg MS to $15.25/kg MS and the range moving from $13.30-$15.30/kg MS to $14.50-$16/kg MS. “Our teams will leverage our scale and flexibility to adapt and make sure we’re capturing the most value for our farmers’ milk,” Allen said.","image":"https://www.farmersweekly.co.nz/wp-content/uploads/2026/10/Fonterra-tanker-.jpg"},{"title":"Stronger milk powder demand lifts Fonterra payout forecast","summary":"恒天然集团表示，强劲的奶粉需求提振了其分红预测。这一积极信号反映了全球乳业市场的回暖趋势，特别是奶粉品类的需求表现强劲。对于跨境渠道从业者而言，这意味着上游原料供应可能趋紧，且乳企盈利能力的提升可能传导至终端价格，需提前布局供应链与库存。","source_id":"farmersweekly_nz","source_name":"Farmers Weekly NZ·乳业","source_url":"https://www.farmersweekly.co.nz/tag/dairy/feed/","original_url":"https://www.farmersweekly.co.nz/markets/dairy-markets/stronger-milk-powder-demand-lifts-fonterra-payout-forecast","published_at":"2026-10-30T05:21:09+08:00","published_guessed":false,"fetched_at":"2026-10-30T06:57:18+08:00","language":"en","author":"Farmers Weekly","tags":["市场数据","供应链"],"priority":"P0","score":16.0,"matched":["milk powder","payout","fonterra"],"id":"8a5b0b92f502fe42","summary_source":"llm","summary_kind":"brief","points":["恒天然上调股息预测","奶粉需求改善推动增长"],"points_source":"llm","translated":true,"title_zh":"强劲需求提振恒天然分红预测","body":"Improved demand for whole and skim milk powders has led to Fonterra lifting its forecast midpoint by 25 cents to $9.75/kg MS. It has also lifted and narrowed the forecast range from $8.50-$10.50/kg MS to $9-$10.50/kg MS. CEO Richard Allen said over the last two GDT events, WMP and SMP pricing had increased by about 5% and 7% respectively. “This is driven by sustained demand from across southeast Asia, Middle East, Africa and China. “We have also had a good start to the season, which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. “There’s plenty more to do, and we are continuing to monitor factors that could affect global supply and demand for dairy.” Fonterra has also increased its organic milk price, with the midpoint lifting from $14.30/kg MS to $15.25/kg MS and the range moving from $13.30-$15.30/kg MS to $14.50-$16/kg MS. “Our teams will leverage our scale and flexibility to adapt and make sure we’re capturing the most value for our farmers’ milk,” Allen said.","image":"https://www.farmersweekly.co.nz/wp-content/uploads/2026/10/Fonterra-tanker-.jpg"},{"title":"FDA proposes rule updating nutrient requirements for infant formula","summary":"美国食品药品监督管理局（FDA）提议更新婴儿奶粉的营养要求。此举旨在提升婴幼儿奶粉的营养标准，保障婴幼儿健康。对跨境母婴行业从业者而言，这意味着需密切关注美国市场法规变化，及时调整产品配方以满足新要求，确保产品符合进口标准，从而维护市场竞争力。","source_id":"gnews_en_recall","source_name":"ABC News - Breaking News, Latest News and Videos","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20(recall%20OR%20RASFF%20OR%20FSANZ%20OR%20withdrawal%20OR%20alert)&hl=en-US&gl=US&ceid=US:en","original_url":"https://abcnews.com/Health/fda-proposes-rule-updating-nutrient-requirements-infant-formula/story?id=137680100","published_at":"2026-10-30T05:19:04+08:00","published_guessed":false,"fetched_at":"2026-10-30T11:04:01+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P1","score":12.8,"matched":["infant formula","infant"],"id":"54c365285a9e446d","summary_source":"llm","summary_kind":"brief","points":["FDA提议更新婴儿奶粉营养要求","提升婴幼儿奶粉营养标准","需关注美国市场法规变化","确保产品符合进口标准"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Food and Drug Administration (FDA) announced on Thursday it is proposing a new rule that will update the nutrient requirements for infant formula. The Department of Health and Human Services (HHS), which oversees the FDA, said in a press release that it would be the first major update to infant formula standards in nearly 30 years. Related Abbott launches new infant formula made with whole milk: What parents need to know The proposed rule would update requirements for vitamin A, vitamin D, iodine and manganese as well as reaffirm existing requirements for chloride, potassium, selenium and sodium, the agencies said. It would also change the units of measure for two nutrients and request public input on possible requirements for ingredients not currently required in infant formula but sometimes added by manufacturers, they noted. The ingredients not currently required include arachidonic acid (ARA), docosahexaenoic acid (DHA), and L-carnitine. Some studies have suggested they contribute greatly to infant growth, brain development and health. In this Oct. 14, 2015, file photo, the U.S. Food and Drug Administration campus is shown in Silver Spring, Md. Andrew Harnik/AP Photo, FILE","image":"https://i.abcnewsfe.com/a/bfc02812-414c-4d98-8b2f-665141e9f7e4/baby-formula-gty-jef-261029_1793289705351_hpMain_16x9.jpg?w=1600"},{"title":"Fonterra raises farmgate milk price forecast midpoint by 25 cents to $9.75/kgMS","summary":"恒天然将本季农场门口牛奶价格预测中点上调25美分至每公斤9.75美元，并将预测区间从每公斤8.50-10.50美元收窄至9.00-10.50美元。公司首席执行官艾伦表示，由于东南亚、中东、非洲和中国的持续需求，恒天然在全球乳制品贸易中的全脂奶粉和脱脂奶粉价格在过去两个事件中分别上涨了约5%和7%。本季销售开局良好，尽管牛奶收集量创下纪录，但销售预订已良好完成，这使恒天然有信心提高预测并缩小范围。","source_id":"gnews_en_nz_dairy","source_name":"Dairynews.today","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://dairynews.today/news/fonterra_raises_farmgate_milk_price_forecast_midpoint_by_25_cents_to_9_75_kgms_6822536.html","published_at":"2026-10-30T04:53:57+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:47+08:00","language":"en","author":"","tags":["市场数据","供应链","质量安全"],"priority":"P0","score":17.6,"matched":["farmgate","milk price","fonterra"],"id":"ed687a06bf3772ff","title_zh":"恒天然上调农场交奶价格预测中值25美分至9.75新西兰元/公斤乳固体","summary_source":"llm","summary_kind":"brief","points":["恒天然上调农场交奶价格预测中值25美分","预测中值达到每公斤乳固体9.75新西兰元","主要受奶粉需求强劲驱动","涉及乳业原料供应链与成本预期"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The co-operative also tightened its forecast band, raising the lower limit to $9/kgMS from $8.50/kgMS while retaining the upper limit of $10.50/kgMS. Allen said Fonterra ’s whole milk powder prices on Global Dairy Trade had gained about 5% across the two most recent events. Its skim milk powder prices rose by approximately 7% over the same period. He attributed those gains to continued demand in Southeast Asia, the Middle East, Africa and China . Allen said the season had started well and that sales were well contracted for this point in the year, even with milk collections at record levels. He said this gave Fonterra confidence to increase its forecast and reduce the width of the range. For organic milk, Fonterra raised its forecast midpoint to $15.25/kgMS from $14.30/kgMS. The revised range is $14.50–$16/kgMS, compared with $13.30–$15.30/kgMS previously. Join the 2nd MENA Dairy Congress on January 24–25 in Al Ain, UAE — a key meeting point for dairy industry leaders, producers, investors, experts, and technology providers from across the MENA region and beyond. Discover new market opportunities, exchange expertise, build valuable business connections, and discuss the future of the dairy industry in one of the region’s most dynamic markets. Register here: https://menadc.dairynews.today Allen said Fonterra continued to track factors that could influence worldwide dairy supply and demand. He added that its teams would use the co-operative’s scale and flexibility to adapt and maximise the value of farmers’ milk."},{"title":"FDA proposes rule updating nutrient requirements for infant formula","summary":"美国食品药品监督管理局（FDA）提出了一项新规则，旨在更新婴幼儿配方奶粉的营养素要求。这是近30年来首次对相关标准进行重大调整，涉及维生素、矿物质等关键成分的添加量规定。该政策将直接影响配方奶粉的生产配方与标签标识，对跨境乳品供应链及合规性提出新挑战。","source_id":"gnews_en_reg","source_name":"Sandhills Express","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://sandhillsexpress.com/abc_health/fda-proposes-rule-updating-nutrient-requirements-for-infant-formula-abcidcbd4750f/","published_at":"2026-10-30T04:41:57+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:45+08:00","language":"en","author":"","tags":["政策法规","质量安全","市场数据"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"f662ea4532e1a4af","summary_source":"llm","summary_kind":"brief","points":["FDA提出更新婴幼儿配方奶粉营养素要求","近30年来首次调整相关标准","涉及维生素和矿物质添加量规定","影响配方奶粉生产配方与合规性"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Food and Drug Administration (FDA) announced on Thursday it is proposing a new rule that will update the nutrient requirements for infant formula. The Department of Health and Human Services (HHS), which oversees the FDA, said in a press release that it would be the first major update to infant formula standards in nearly 30 years. The proposed rule would update requirements for vitamin A, vitamin D, iodine and manganese as well as reaffirm existing requirements for chloride, potassium, selenium and sodium, the agencies said. It would also change the units of measure for two nutrients and request public input on possible requirements for ingredients not currently required in infant formula but sometimes added by manufacturers, they noted. The ingredients not currently required include arachidonic acid (ARA), docosahexaenoic acid (DHA), and L-carnitine. Some studies have suggested they contribute greatly to infant growth, brain development and health. The agency said there will be additional phases looking at the remaining required nutrients, potential new nutrient requirements and carbohydrate sources. The FDA said it will welcome public comment during its phases and, in the future, will issue one final rule to cover all the proposed changes. The FDA also released new data on chemical contaminant testing for infant formula and found that most samples tested had “low or non-detectable levels of chemical contaminants.” “Parents deserve confidence in every bottle they feed their baby,” HHS Secretary Robert F. Kennedy, Jr. said in a statement, in part. “We will hold infant formula manufacturers to rigorous scientific standards and put babies’ health first.” Last year, the HHS and FDA announced they would review the nutrition quality of infant formula in the U.S. The FDA said the review — part of its “Operation Stork Speed” initiative — would look at whether current nutrient requirements need to be updated, including whether additional nutrients need to be considered. Under current law, the HHS secretary reviews the table of required nutrients every four years as appropriate. The FDA currently specifies 30 nutrients that must be included in infant formulas. There are minimum amounts for all 30 nutrients and maximum amounts for 10 nutrients, according to the agency.","image":"https://s3.amazonaws.com/syndication.abcaudio.com/files/2026-10-29/baby-formula-gty-jef-261029_1793289705351_hpMain_16x9.jpg","title_zh":"美国食品药品监督管理局提出规则更新婴幼儿奶粉营养要求"},{"title":"Fonterra lifts farmgate milk price forecast on stronger milk powder demand","summary":"恒天然将本季农场门口牛奶价格预测中点上调至每公斤9.75美元，较之前的9.50美元高出25美分。公司同时收窄了预测区间，从8.50-10.50美元调整为9.00-10.50美元。这一调整主要受全脂奶粉和脱脂奶粉需求改善的推动。首席执行官艾伦指出，过去两个事件中，恒天然在全球乳制品贸易中的全脂奶粉和脱脂奶粉价格分别上涨了约5%和7%，这得益于东南亚、中东、非洲和中国的持续需求。","source_id":"gnews_en_nz_dairy","source_name":"RNZ","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.rnz.co.nz/news/business/2233787/fonterra-lifts-farmgate-milk-price-forecast-on-stronger-milk-powder-demand","published_at":"2026-10-30T04:36:27+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:47+08:00","language":"en","author":"","tags":["市场数据","供应链","质量安全"],"priority":"P0","score":24.0,"matched":["milk powder","farmgate","milk price","fonterra"],"id":"297f44e354021c53","title_zh":"恒天然因奶粉需求强劲上调农场交奶价格预测","summary_source":"llm","summary_kind":"brief","points":["恒天然上调农场交奶价格预测","主要受奶粉需求强劲驱动","涉及乳业原料供应链与成本预期","影响下游乳制品加工企业定价策略"],"points_source":"llm","translated":true,"link_resolved":true,"body":"30 October 2026, 9:36am Fonterra lifts farmgate milk price forecast on stronger milk powder demand Photo credit: RNZ / Rebekah Parsons-King Fonterra has lifted its forecast farmgate milk price for the current season to a midpoint of $9.75 per kgMS. The previous midpoint was $9.50 ahead of the 25 cents lift, announced Friday morning. The dairy co-operative has also upped and narrowed the forecast range from $8.50 - $10.50 per kgMS to $9.00 - $10.50 per kgMS. Chief executive Richard Allen said the increase for the current season is driven by improving demand for whole milk powder and skim milk powder. \"Over the last two events, our WMP and SMP pricing on Global Dairy Trade has increased by about 5 percent and 7 percent respectively. This is driven by sustained demand from across Southeast Asia, Middle East, Africa and China,\" Allen said. \"We have also had a good start to the season which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. \"There's plenty more to do, and we are continuing to monitor factors that could affect global supply and demand for dairy.\" In a letter to farmer suppliers, Fonterra said it's increasing its regular advance payments to reflect the higher forecast milk price. The advance rate for October milk, paid November, will rise 20 cents to $7.55 per kgMS. Prices are also rising for Fonterra's organic farmers. The Co-operative has also today increased the Organic Milk Price, with the midpoint lifting from $14.30 per kgMS to $15.25 per kgMS, and the range moving from $13.30 - $15.30 per kgMS to $14.50 - $16.00 per kgMS.","image":"https://media.rnztools.nz/rnz/image/upload/s--CvJuloob--/t_tohu-badge-facebook/f_auto/q_auto/4OLWPRY_1M1A0620_13077"},{"title":"Fonterra lifts farmgate milk price forecast on stronger milk powder demand","summary":"新西兰农场的农场门价牛奶价格预测上调，因奶粉需求增强。作为全球主要奶粉供应商，新西兰农场的价格变动对国际乳制品市场有显著影响。跨境母婴行业从业者需关注国际原料供应链变化，特别是主要奶源地价格波动，以规避潜在风险并优化采购策略。","source_id":"gnews_en_dairy","source_name":"RNZ","source_url":"https://news.google.com/rss/search?q=(%22infant%20formula%22%20OR%20%22dairy%20industry%22%20OR%20%22milk%20powder%22)%20(price%20OR%20export%20OR%20regulation%20OR%20plant)&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.rnz.co.nz/news/business/2233787/fonterra-lifts-farmgate-milk-price-forecast-on-stronger-milk-powder-demand","published_at":"2026-10-30T04:36:27+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:33+08:00","language":"en","author":"","tags":["市场数据","供应链","跨境电商"],"priority":"P1","score":24.0,"matched":["milk powder","farmgate","milk price","fonterra"],"id":"2817d671153e3f9e","summary_source":"llm","summary_kind":"brief","points":["新西兰农场的农场门价牛奶价格预测上调","对国际乳制品市场有显著影响","需关注国际原料供应链变化"],"points_source":"llm","translated":true,"link_resolved":true,"body":"30 October 2026, 9:36am Fonterra lifts farmgate milk price forecast on stronger milk powder demand Photo credit: RNZ / Rebekah Parsons-King Fonterra has lifted its forecast farmgate milk price for the current season to a midpoint of $9.75 per kgMS. The previous midpoint was $9.50 ahead of the 25 cents lift, announced Friday morning. The dairy co-operative has also upped and narrowed the forecast range from $8.50 - $10.50 per kgMS to $9.00 - $10.50 per kgMS. Chief executive Richard Allen said the increase for the current season is driven by improving demand for whole milk powder and skim milk powder. \"Over the last two events, our WMP and SMP pricing on Global Dairy Trade has increased by about 5 percent and 7 percent respectively. This is driven by sustained demand from across Southeast Asia, Middle East, Africa and China,\" Allen said. \"We have also had a good start to the season which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. \"There's plenty more to do, and we are continuing to monitor factors that could affect global supply and demand for dairy.\" In a letter to farmer suppliers, Fonterra said it's increasing its regular advance payments to reflect the higher forecast milk price. The advance rate for October milk, paid November, will rise 20 cents to $7.55 per kgMS. Prices are also rising for Fonterra's organic farmers. The Co-operative has also today increased the Organic Milk Price, with the midpoint lifting from $14.30 per kgMS to $15.25 per kgMS, and the range moving from $13.30 - $15.30 per kgMS to $14.50 - $16.00 per kgMS.","image":"https://media.rnztools.nz/rnz/image/upload/s--CvJuloob--/t_tohu-badge-facebook/f_auto/q_auto/4OLWPRY_1M1A0620_13077"},{"title":"Fonterra lifts forecast 2026/27 Farmgate Milk Price","summary":"丰塔拉乳业宣布将2026/27年度场门牛奶价预期上调。这一消息对婴幼儿奶粉行业意味着原料成本可能增加，生产商需提前规划成本控制和产品定价。同时，跨境渠道需关注市场反应，适时调整销售策略。","source_id":"gnews_en_nz_dairy","source_name":"Interest.co.nz","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.interest.co.nz/rural-news/140886/following-good-start-new-dairy-season-and-strong-improving-demand-milk-powders","published_at":"2026-10-30T04:31:00+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:56+08:00","language":"en","author":"","tags":["政策法规","市场数据","质量安全"],"priority":"P0","score":17.6,"matched":["farmgate","milk price","fonterra"],"id":"7f7c95eb56780531","title_zh":"丰塔拉上调2026/27年度场门牛奶价预期","summary_source":"llm","summary_kind":"brief","points":["丰塔拉上调场门牛奶价预期","乳业市场原料价值评估","婴幼儿奶粉生产商需跟踪原料成本","需考虑调整定价策略"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Following a good start to the new dairy season, and strong improving demand for milk powders, Fonterra has added 25c to its new season payout forecast Fonterra has increased the midpoint of the 2026/27 season forecast Farmgate Milk Price from $9.50 per kgMS to $9.75 per kgMS. They have lifted and narrowed the forecast range from $8.50 - $10.50 per kgMS to $9.00 - $10.50 per kgMS. CEO Richard Allen says the updated forecast is driven largely by improving demand for Whole Milk Powder (WMP) and Skim Milk Powder (SMP). “We have also had a good start to the season which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. Thy have also today increased the Organic Milk Price, with the midpoint lifting from $14.30 per kgMS to $15.25 per kgMS, and the range moving from $13.30 - $15.30 per kgMS to $14.50 - $16.00 per kgMS. You can compare Fonterra's payout with the other dairy companies here . Your access to our unique and original content is free, and always has been. But ad revenues are under pressure so we need your support. Supporters can choose any amount, and will get a premium ad-free experience, the ability to comment, and access to our daily/weekly newsletters if giving a minimum of $10/month or $100/year. Learn more here . We welcome your comments below. If you are not already registered, please register to comment Remember we welcome robust, respectful and insightful debate. We don't welcome abusive or defamatory comments and will de-register those repeatedly making such comments. Our current comment policy is here. by redcows | 30th Oct 26, 9:39am 1793306384 Organic $15.25. To think that around ten years ago Fonterra had put a big boot heel on organic pick up purely because management couldn't be bothered. I have nothing to do with organic milk but I'm still thankful for those that persevered both inside and outside the company. by LouB | 30th Oct 26, 10:26am 1793309219 I'm interested in what the relative margin is between organic and traditional production systems. Typical break even $/kg ms (when i try to type that without spacing, I loose the keypad function)?","image":"https://www.interest.co.nz/sites/default/files/2025-03/fonterra-mar20-8.JPG"},{"title":"Fonterra lifts milk price forecast back to season-opening level","summary":"丰塔拉乳业将牛奶价格预期上调至开季水平。这一调整表明乳业市场正在逐步恢复，对跨境乳制品贸易商来说，是观察市场趋势和调整库存策略的信号。","source_id":"gnews_en_nz_dairy","source_name":"BusinessDesk","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.businessdesk.co.nz/primary-sector/fonterra-lifts-milk-price-forecast-back-to-season-opening-level/CRNEI5PNURAD5PZVTV4IIRMK2M/","published_at":"2026-10-30T04:22:58+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:56+08:00","language":"en","author":"","tags":["市场数据","供应链","跨境电商"],"priority":"P0","score":11.2,"matched":["milk price","fonterra"],"id":"05923e3bdc5cfbd3","title_zh":"丰塔拉将牛奶价预期回升至开季水平","summary_source":"llm","summary_kind":"brief","points":["丰塔拉上调牛奶价预期","乳业市场逐步恢复","跨境乳制品贸易商需观察市场趋势"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Richard Allen says the forecast update was driven largely by improving demand for skim and whole milk powders. Photo / Alyse Wright, NZME Fonterra Co-operative Group has lifted its forecast milk price back to where it started the season. On Friday, it increased the midpoint of its current season ’s forecast from $9.50/kgMS to $9.75/kgMS. It also lifted and narrowed the forecast range from between $8.50/kgMS and $10.50/kgMS to between $9/kgMS and $10.50/kgMS. Fonterra opened the season at $9.75/kgMS before cutting it to $9.25/kgMS in July after softer Global Dairy Trade auctions. It then lifted to $9.50/kgMS at its full-year results. Chief executive Richard Allen said the updated forecast was driven largely by improving demand for whole milk powder (WMP) and skim milk powder (SMP). “Over the last two events, our WMP and SMP pricing on Global Dairy Trade has increased by about 5% and 7% respectively.” That was driven by “sustained” demand from across Southeast Asia, the Middle East, Africa and China. “We have also had a good start to the season, which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range.” The co-op also increased its forecast organic milk price to $15.25/kgMS, up from $14.30/kgMS, with the range moving to between $14.50/kgMS and $16.00/kgMS. Organic milk makes up less than 1% of Fonterra’s total collections. The information was obtained throigh an OIA request. He will formally begin the appointment on November 1, 2026.","image":"https://www.businessdesk.co.nz/resizer/v2/MRI2JBD73RH7LNW37XTDHBB75Y.jpg?auth=4de2e4296427e515d937cc316a9072edde5f3bb2d39f01fa6ce327c3443e949e&width=1200&height=675&quality=70&focal=1029%2C412&smart=false"},{"title":"Fonterra boss: Stronger dairy demand lifts milk price forecast","summary":"恒天然负责人表示，公司本季农场门口牛奶价格预测中点上调至每公斤9.75美元，主要受奶粉需求强劲的推动。公司同时收窄了预测区间，从8.50-10.50美元调整为9.00-10.50美元。首席执行官艾伦指出，过去两个事件中，恒天然在全球乳制品贸易中的全脂奶粉和脱脂奶粉价格分别上涨了约5%和7%，这得益于东南亚、中东、非洲和中国的持续需求。","source_id":"gnews_en_nz_dairy","source_name":"NZ Herald","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.nzherald.co.nz/business/companies/agribusiness/fonterra-lifts-202627-farmgate-milk-price-forecast-to-975-per-kgms/KOBYFSOU4FCFJIN2LNNGQYSS3U/","published_at":"2026-10-30T04:17:17+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:47+08:00","language":"en","author":"","tags":["市场数据","供应链","质量安全"],"priority":"P0","score":16.0,"matched":["dairy","milk price","fonterra"],"id":"b777aee48057ecdd","title_zh":"恒天然高管：强劲的乳制品需求推高价格预测","summary_source":"llm","summary_kind":"brief","points":["恒天然高管确认需求推高价格预测","强劲的乳制品需求是关键因素","确认市场需求对定价的主导作用","提醒从业者关注全球乳品贸易动态"],"points_source":"llm","translated":true,"link_resolved":true,"body":"“We have also had a good start to the season which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range,” he said. Fonterra was continuing to monitor factors that could affect global supply and demand for dairy, he said. The co-operative has also increased the organic milk price, with the midpoint lifting from $14.30 per kgMS to $15.25 per kgMS, and the range moving from $13.30-$15.30 per kgMS to $14.50-$16.00 per kgMS. Earlier this month, SMP prices hit a four-year high and futures market pricing pointed to $10-plus milk prices for this year, and the following two years. The futures market now suggests $10.40/kg for the current season, $10.27/kg for 2027/28, and $9.75/kg for 2028/29. Jamie Gray is an Auckland-based journalist, covering the financial markets, the primary sector and energy. He joined the Herald in 2011. Stay ahead with the latest market moves, corporate updates, and economic insights by subscribing to our Business newsletter – your essential weekly round-up of all the business news you need.","image":"https://www.nzherald.co.nz/resizer/v2/HPZVE5BMO5HNRAX636PQIJUOFI.jpg?auth=567b905d96c2269d1d85ed0784b3e009199cb493663fb84cdbbd0649a97a24a7&width=1200&height=675&quality=70&focal=1157%2C887&smart=false"},{"title":"Fonterra Lifts Farmgate Milk Price","summary":"恒天然将本季农场门口牛奶价格预测中点上调至每公斤9.75美元，并将预测区间从8.50-10.50美元收窄至9.00-10.50美元。公司首席执行官艾伦表示，这一调整主要受全脂奶粉和脱脂奶粉需求改善的推动。过去两个事件中，恒天然在全球乳制品贸易中的全脂奶粉和脱脂奶粉价格分别上涨了约5%和7%，这得益于东南亚、中东、非洲和中国的持续需求。","source_id":"gnews_en_nz_dairy","source_name":"Rural News Group","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.ruralnewsgroup.co.nz/dairy-news/dairy-general-news/fonterra-lifts-milk-price-forecast-midpoint-9-75","published_at":"2026-10-30T04:14:09+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:47+08:00","language":"en","author":"","tags":["市场数据","供应链","质量安全"],"priority":"P0","score":17.6,"matched":["farmgate","milk price","fonterra"],"id":"132b25f098bb39af","title_zh":"恒天然上调农场交奶价格","summary_source":"llm","summary_kind":"brief","points":["恒天然宣布上调农场交奶价格","显示乳业市场供需状况积极变化","影响婴幼儿配方奶粉定价空间","关系到供应链稳定性"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The co-operative has also lifted and narrowed the forecast range from $8.50 - $10.50/kgMS to $9 - $10.50/kgMS. Fonterra chief executive, Richard Allen says the updated forecast is driven largely by improving demand for Whole Milk Powder (WMP) and Skim Milk Powder (SMP). \"Over the last two events, our WMP and SMP pricing on Global Dairy Trade has increased by about 5% and 7% respectively. This is driven by sustained demand from across Southeast Asia, Middle East, Africa and China. “We have also had a good start to the season which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. “There’s plenty more to do, and we are continuing to monitor factors that could affect global supply and demand for dairy.\" The co-op has also increased the organic milk price, with the midpoint lifting from $14.30/kgMS to $15.25/kgMS, and the range moving from $13.30 - $15.30/kgMS to $14.50 - $16/kgMS. “Our teams will leverage our scale and flexibility to adapt and make sure we’re capturing the most value for our farmers’ milk,” says Allen.","image":"https://www.ruralnewsgroup.co.nz/media/k2/items/cache/95d263a6a1abadb903ef797d73f58bd0_XL.jpg"},{"title":"Fonterra lifts forecast 2026/27 Farmgate Milk Price","summary":"恒天然宣布上调2026/27年度场门牛奶价格预测，显示乳制品市场可能面临价格上涨。这一预测调整反映了全球乳制品供需关系的变化，对依赖进口原料的跨境奶粉企业产生影响。从业者需关注原料成本波动，评估供应链风险，并考虑调整定价策略以应对市场变化。乳制品价格波动受多种因素影响，包括气候变化、饲料成本及全球贸易环境，行业参与者需保持敏感度。","source_id":"gnews_en_nz_dairy","source_name":"Fonterra","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.fonterra.com/nz/en/our-stories/media/fonterra-lifts-forecast-2026-27-farmgate-milk-price.html","published_at":"2026-10-30T03:41:04+08:00","published_guessed":false,"fetched_at":"2026-10-30T11:04:39+08:00","language":"en","author":"","tags":["市场数据","供应链","跨境电商"],"priority":"P0","score":17.6,"matched":["farmgate","milk price","fonterra"],"id":"79d99589e9202426","title_zh":"恒天然上调2026/27年度场门牛奶价预测","summary_source":"llm","summary_kind":"brief","points":["恒天然预测牛奶价格上涨","反映乳制品供需变化","影响进口原料成本","需关注供应链风险"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Co-operative has also lifted and narrowed the forecast range from $8.50 - $10.50 per kgMS to $9.00 - $10.50 per kgMS. CEO Richard Allen says the updated forecast is driven largely by improving demand for Whole Milk Powder (WMP) and Skim Milk Powder (SMP). \"Over the last two events, our WMP and SMP pricing on Global Dairy Trade has increased by about 5% and 7% respectively. This is driven by sustained demand from across Southeast Asia, Middle East, Africa and China. “We have also had a good start to the season which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. “There’s plenty more to do, and we are continuing to monitor factors that could affect global supply and demand for dairy.\" The Co-operative has also today increased the Organic Milk Price, with the midpoint lifting from $14.30 per kgMS to $15.25 per kgMS, and the range moving from $13.30 - $15.30 per kgMS to $14.50 - $16.00 per kgMS. “Our teams will leverage our scale and flexibility to adapt and make sure we’re capturing the most value for our farmers’ milk,” says Mr Allen. For further information contact: Fonterra Communications Phone: +64 21 507 072"},{"title":"Fonterra lifts forecast 2026/27 Farmgate Milk Price","summary":"恒天然将2026/27年农场门口牛奶价格预测中点上调至每公斤9.75美元，并将预测区间从8.50-10.50美元收窄至9.00-10.50美元。首席执行官艾伦表示，这一调整主要受全脂奶粉和脱脂奶粉需求改善的推动。过去两个事件中，恒天然在全球乳制品贸易中的全脂奶粉和脱脂奶粉价格分别上涨了约5%和7%，这得益于东南亚、中东、非洲和中国的持续需求。","source_id":"fonterra_media","source_name":"Fonterra 恒天然·媒体发布","source_url":"https://www.fonterra.com/nz/en/our-stories/media.html","original_url":"https://www.fonterra.com/nz/en/our-stories/media/fonterra-lifts-forecast-2026-27-farmgate-milk-price.html","published_at":"2026-10-30T03:30:00+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:38+08:00","language":"en","author":"","tags":["市场数据","供应链","质量安全"],"priority":"P0","score":17.6,"matched":["farmgate","milk price","fonterra"],"id":"3b5273566c122c12","title_zh":"恒天然上调2026/27年农场交奶价格预测","summary_source":"llm","summary_kind":"brief","points":["上调2026/27财年农场主支付价格","预测中值从9.50美元升至9.75美元","反映新西兰乳业对长期成本的预期","影响跨境从业者对原料成本的预判"],"points_source":"llm","translated":true,"body":"The Co-operative has also lifted and narrowed the forecast range from $8.50 - $10.50 per kgMS to $9.00 - $10.50 per kgMS. CEO Richard Allen says the updated forecast is driven largely by improving demand for Whole Milk Powder (WMP) and Skim Milk Powder (SMP). \"Over the last two events, our WMP and SMP pricing on Global Dairy Trade has increased by about 5% and 7% respectively. This is driven by sustained demand from across Southeast Asia, Middle East, Africa and China. “We have also had a good start to the season which sees our sales book well-contracted for this stage of the year, despite record milk collections, giving us confidence to lift and narrow the forecast range. “There’s plenty more to do, and we are continuing to monitor factors that could affect global supply and demand for dairy.\" The Co-operative has also today increased the Organic Milk Price, with the midpoint lifting from $14.30 per kgMS to $15.25 per kgMS, and the range moving from $13.30 - $15.30 per kgMS to $14.50 - $16.00 per kgMS. “Our teams will leverage our scale and flexibility to adapt and make sure we’re capturing the most value for our farmers’ milk,” says Mr Allen. For further information contact: Fonterra Communications Phone: +64 21 507 072"},{"title":"FDA Data Shows Most Infant Formula Samples Had Low/Non-Detectable Contaminants","summary":"美国食品药品监督管理局（FDA）公布的数据显示，大多数婴幼儿配方奶粉样品中的污染物含量极低或未检测出。这一结果反映了当前乳品供应链在质量控制方面的成效，也验证了现有食品安全监管体系的可靠性。对于行业从业者而言，该数据有助于增强市场信心，并指导后续的质量检测重点。","source_id":"gnews_en_reg","source_name":"TradingView","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.tradingview.com/news/reuters.com,2026:newsml_FWN46F3MX:0-fda-data-shows-most-infant-formula-samples-had-low-non-detectable-contaminants/","published_at":"2026-10-30T03:20:27+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:45+08:00","language":"en","author":"","tags":["质量安全","市场数据"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"fabf805cdb698a5b","summary_source":"llm","summary_kind":"brief","points":["FDA公布婴幼儿配方奶粉污染物数据","大多数样品污染物含量极低或未检出","反映供应链质量控制成效","验证现有食品安全监管体系"],"points_source":"llm","translated":true,"title_zh":"FDA数据显示大多数婴幼儿配方奶粉样品污染物含量极低或未检测出","link_resolved":true,"image":"https://s.tradingview.com/static/images/illustrations/news-story.jpg"},{"title":"Trump admin moves to update nutrition rules for infant formula, change would be biggest in decades","summary":"特朗普政府计划对婴儿奶粉的营养规则进行更新，这一变化可能成为数十年来最大规模的调整。此举旨在提升婴幼儿奶粉的营养标准，确保产品质量和安全性。对母婴行业从业者而言，这意味着需要密切关注政策变化，及时调整产品配方和生产流程以符合新标准。这一更新反映了市场对婴幼儿健康食品需求的持续增长，也凸显了乳制品行业在食品安全和营养方面的监管重要性。","source_id":"gnews_en_reg","source_name":"Just The News","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://justthenews.com/government/white-house/30-years-making-trumps-hhs-imposes-maha-updates-infant-formula-requirements","published_at":"2026-10-30T02:44:14+08:00","published_guessed":false,"fetched_at":"2026-10-30T11:04:36+08:00","language":"en","author":"","tags":["政策法规","质量安全","品牌动态"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"994ed6b427f14012","title_zh":"特朗普政府拟更新婴儿奶粉营养规则，或为数十年来最大变革","summary_source":"llm","summary_kind":"brief","points":["营养规则将迎来重大调整","提升婴幼儿奶粉营养标准","要求行业适应新规范","关注食品安全与营养监管"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Trump administration took its most significant step yet Thursday to modernize what American babies consume. The Food and Drug Administration proposed a new rule updating the nutrient requirements for infant formula, a change the agency describes as the biggest update to formula standards in nearly 30 years . Health and Human Services Secretary Robert F. Kennedy Jr., who launched the effort last year, has framed the goal in sweeping terms. \"We're going to make American infant formula the gold standard for the world,\" he said in announcing the initiative , called Operation Stork Speed. The proposal is part of the FDA's ongoing review of baby formula nutrients . It is the first phase of a three-part plan to review and possibly revise standards for the 30 nutrients a formula must contain. The rule will go through public comment before any changes take effect. The proposal adjusts the required limits for iodine, vitamins A and D, and manganese , and sets a ceiling on manganese for the first time. It would also update how vitamins A and D are measured, permit a new source of vitamin A, and revise labeling rules. Regulators concluded that current levels of chloride, selenium, potassium and sodium are adequate and will stay as they are. The FDA intends to propose rules covering the rest of the nutrients before issuing a single final rule, and has promised outside peer review of the science behind it. The agency projects the changes will cost manufacturers $8.4 million to $31.7 million a year, with $17.6 million as its central estimate. The proposal moved quickly. The White House received the rule for review on Oct. 14 and classified it as economically significant. It cleared that review Wednesday, after roughly two weeks. The work traces back to May 2025, when the FDA formally requested public input to start the review, noting that its last comprehensive look at formula nutrients came in 1998. Federal formula rules were born from a crisis. In the late 1970s, a formula with too little sodium chloride harmed infants. That led Congress to pass the Infant Formula Act of 1980 , which still underpins today's FDA nutrient rules. Some researchers have argued that the law no longer reflects current science and needs a full independent review. Recent years have brought more turmoil.","image":"https://justthenews.com/sites/default/files/styles/social_media_share/public/2024-08/RFK%20Jr.%20Trump.jpg?h=ca8addfd&itok=D-5DOYCZ"},{"title":"FDA plans to update infant formula nutrition requirements for first time in nearly 30 years","summary":"美国食品药品监督管理局（FDA）计划近30年来首次更新婴儿奶粉的营养要求。这一举措旨在提升婴儿奶粉的营养标准，保障婴幼儿的食品安全和健康。对于跨境母婴行业的从业者而言，FDA的更新将直接影响全球婴儿奶粉市场的产品标准和监管政策，需要密切关注并及时调整产品配方和生产流程，以确保符合新的营养要求。","source_id":"gnews_en_reg","source_name":"news8000.com","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.news8000.com/lifestyle/health/fda-plans-to-update-infant-formula-nutrition-requirements-for-first-time-in-nearly-30-years/article_e655dde9-2d51-52e3-b152-f001717cdf38.html","published_at":"2026-10-30T02:33:34+08:00","published_guessed":false,"fetched_at":"2026-10-30T03:11:38+08:00","language":"en","author":"","tags":["政策法规","质量安全","海外动态"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"8d27d07eaf9f23c4","title_zh":"FDA计划近30年来首次更新婴儿奶粉营养要求","summary_source":"llm","summary_kind":"brief","points":["FDA计划近30年来首次更新婴儿奶粉营养要求","旨在提升婴儿奶粉营养标准","将影响全球婴儿奶粉市场产品标准","要求企业调整产品配方和生产流程"],"points_source":"llm","translated":true,"link_resolved":true,"body":"(CNN) — The US Food and Drug Administration is proposing changes to nutrient requirements for infant formula. The update marks the first nutrition review for formula in nearly 30 years, the agency’s acting director, Kyle Diamantas, said Thursday. The review is part of the Trump administration’s Operation Stork Speed initiative, which was announced in March 2025. The first phase of the review makes changes to four of the 30 required nutrients in formula: iodine, manganese, vitamin A and vitamin D. Dr. Steven Abrams, a pediatrician and professor at the University of Texas’ Dell Medical School, said the nutrition update was overdue. He praised the first phase as “really well done” and “very well thought-out.” The problem, Abrams said, is that the review is tackling the nutrient list piecemeal. This first group of nutrients will be followed by 12 in the next year or so and another batch of 10 after that. That means parents aren’t likely to see any changes to infant formula anytime soon, he said. “These changes that they’re recommending today are not going to be something that’ll show up on the can of formula potentially for several years,” said Abrams, who is an expert on infant nutrition. The nutrition review was conducted by the FDA’s staff scientists and will be submitted for peer review, as required by law. “Parents deserve confidence in every bottle they feed their baby,” US Health and Human Services Secretary Robert F. Kennedy Jr. said in a news release. “Under President Trump’s Operation Stork Speed and Make America Healthy Again agenda, we are proposing stronger nutrient requirements, testing formula for contaminants, and putting the results directly in parents’ hands. We will hold infant formula manufacturers to rigorous scientific standards and put babies’ health first.” The most consequential change in this first slate of recommendations is the proposal to increase vitamin D, Abrams said. Right now, the amount of vitamin D in infant formula is a little below the recommended amount for babies. Many parents supplement formula with extra vitamin D. Adding more vitamin D to formula could potentially save nearly $81 million each year in medical costs tied to a diagnosis of late-onset hypocalcemia, or low blood calcium, the proposed rule said. Vitamin D helps the body absorb calcium and phosphorus from food.","image":"https://bloximages.newyork1.vip.townnews.com/news8000.com/content/tncms/assets/v3/editorial/6/7e/67e0cd0a-0f22-5826-9603-e598bca94587/6ae3980443fc1.image.jpg?crop=1763%2C926%2C0%2C124&resize=1200%2C630&order=crop%2Cresize"},{"title":"FDA plans to update infant formula nutrition requirements for first time in nearly 30 years","summary":"美国食品药品监督管理局（FDA）计划更新婴幼儿配方奶粉的营养要求，这是近30年来的首次调整。新规将重新定义配方奶粉中维生素、矿物质等关键营养素的添加标准，旨在更好地满足婴儿生长发育需求。该政策将迫使相关企业调整产品配方，并可能引发跨境供应链的原料配比与合规性审查。","source_id":"gnews_en_reg","source_name":"CNN","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.cnn.com/2026/10/29/health/infant-formula-nutrition-fda","published_at":"2026-10-30T02:33:34+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:45+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"e4e47cc67642484c","summary_source":"llm","summary_kind":"brief","points":["FDA计划更新婴幼儿配方奶粉营养要求","近30年来首次调整相关标准","涉及维生素和矿物质添加量规定","影响配方奶粉生产配方与合规性"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The US Food and Drug Administration is proposing changes to nutrient requirements for infant formula. The update marks the first nutrition review for formula in nearly 30 years, the agency’s acting director, Kyle Diamantas, said Thursday. The review is part of the Trump administration’s Operation Stork Speed initiative, which was announced in March 2025. The first phase of the review makes changes to four of the 30 required nutrients in formula: iodine, manganese, vitamin A and vitamin D. Iodine is important for the production of thyroid hormone and brain development in infants. The proposed rule triples the amount of iodine required in infant formula, from 5 micrograms to 15, and sets a new upper limit of 50 micrograms. Manganese is a trace mineral that supports enzyme function and bone development. The proposal reduces the minimum required amount from 5 micrograms to 1 microgram per 100 calories, and it establishes a new limit of 50 micrograms. Vitamin A supports vision, immune function and cell growth. The proposal decreases the amount of vitamin A required in formula, from 250 international units per 100 calories to 233 IU. It would also change the units of measure for vitamin A from IU to retinol activity equivalents, or RAE. Vitamin D helps with development of bones and teeth and helps prevent rickets, or soft bones. The proposed rule doubles the minimum required amount of vitamin D from 1 to 2 micrograms and increases the maximum amount allowed to 3 micrograms. The proposed rule also reaffirms requirements for chloride, potassium, selenium and sodium. Dr. Steven Abrams, a pediatrician and professor at the University of Texas’ Dell Medical School, said the nutrition update was overdue. He praised the first phase as “really well done” and “very well thought-out.” The problem, Abrams said, is that the review is tackling the nutrient list piecemeal. This first group of nutrients will be followed by 12 in the next year or so and another batch of 10 after that. That means parents aren’t likely to see any changes to infant formula anytime soon, he said. “These changes that they’re recommending today are not going to be something that’ll show up on the can of formula potentially for several years,” said Abrams, who is an expert on infant nutrition.","image":"https://media.cnn.com/api/v1/images/stellar/prod/gettyimages-2164047744.jpg?c=16x9&q=w_800,c_fill"},{"title":"FDA plans to update nutritional rules for infant formula","summary":"美国食品药品监督管理局（FDA）计划更新婴儿配方奶粉的营养规则，旨在优化产品配方标准。该动作涉及婴幼儿配方奶粉这一关键品类，对行业监管和产品合规产生深远影响。从业者需密切关注新规进展，及时调整产品策略。","source_id":"gnews_en_reg","source_name":"NBC News","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.nbcnews.com/now/video/fda-plans-to-update-nutritional-rules-for-infant-formula-272483909647","published_at":"2026-10-30T02:32:37+08:00","published_guessed":false,"fetched_at":"2026-10-30T06:57:28+08:00","language":"en","author":"","tags":["政策法规"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"d65670705a82136a","title_zh":"FDA计划更新婴儿配方奶粉营养规则","summary_source":"llm","summary_kind":"brief","points":["FDA计划更新婴儿配方奶粉营养规则","涉及婴幼儿配方奶粉品类","对行业合规和产品策略产生影响"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Food and Drug Administration plans to introduce new rules around what nutrients must be added to infant formula. The changes the FDA plans to propose, which were shared in advance with NBC News, would tweak the minimum and maximum levels of four nutrients: iodine, manganese, vitamin A and vitamin D. Oct. 29, 2026","image":"https://media-cldnry.s-nbcnews.com/image/upload/t_nbcnews-fp-1200-630,f_auto,q_auto:best/mpx/2704722219/2026_10/1793298125645_now_daily_a_fda_infant_formula_261029_S3_1920x1080-ndu877.jpg"},{"title":"FDA proposes new iodine, vitamin A and D limits for infant formula","summary":"美国食品药品监督管理局（FDA）提议对婴儿配方奶粉中碘、维生素 A 和 D 的含量设定新限制。此举旨在保障婴幼儿营养需求，符合母婴喂养与乳业食品安全政策。对从业者而言，这意味着需要关注法规变化，及时调整产品配方以满足标准。这类政策调整通常基于科学研究和市场反馈，对行业具有指导意义。","source_id":"gnews_en_reg","source_name":"Contemporary Pediatrics","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.contemporarypediatrics.com/view/fda-proposes-new-iodine-vitamin-a-and-d-limits-for-infant-formula","published_at":"2026-10-30T02:13:21+08:00","published_guessed":false,"fetched_at":"2026-10-30T03:11:38+08:00","language":"en","author":"","tags":["政策法规","质量安全","品牌动态"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"958de296fecc15ab","title_zh":"FDA 提出对婴儿配方奶粉中碘、维生素 A 和 D 的新限制","summary_source":"llm","summary_kind":"brief","points":["FDA 设新标准","涉及碘、维生素 A 和 D"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Vitamin A: current 75–225 µg RAE (250–750 IU); proposed 70–120 µg RAE per 100 kcal, preformed vitamin A only.¹ Vitamin D: current 1–2.5 µg (40–100 IU); proposed 2–3 µg (80–120 IU) per 100 kcal.¹ After its evidence review, the FDA concluded that current specifications for 4 nutrients remain appropriate and proposed to retain them.¹ Those are sodium at 20 to 60 mg, potassium at 80 to 200 mg, chloride at 55 to 150 mg, and selenium at 2 to 7 µg per 100 kcal.¹ Federal regulations require infant formula to contain 30 nutrients, each with a minimum level and 10 with a maximum.³ The Federal Food, Drug, and Cosmetic Act directs the agency to review those requirements every 4 years as appropriate, but its last comprehensive review was in 1998.¹,³ For each nutrient in this phase, the FDA evaluated nutrient reference values, human milk composition, international formula standards, clinical literature published since 1998, and comments submitted to a 2025 request for information.¹ The full review will undergo independent peer review.¹ The proposal neither adds nor removes any required nutrient.¹ It does, however, request input on arachidonic acid (ARA), docosahexaenoic acid (DHA), and L-carnitine, which are not currently required but are commonly added by manufacturers; the FDA said evidence supports their contribution to neurodevelopmental health in infancy.¹ A second phase, now underway, covers vitamin E, the B vitamins, folic acid, biotin, vitamin C, choline, and inositol.¹ A third phase, conducted by an outside organization under FDA oversight, addresses protein, fat, linoleic acid, iron, copper, zinc, calcium, phosphorus, magnesium, and vitamin K, plus potential requirements for DHA, ARA, alpha-linolenic acid, and L-carnitine.¹ Each phase is expected to yield its own proposed rule.¹ The FDA plans to fold all 3 phases into a single final rule that would take effect 60 days after publication, with a proposed compliance date 3 years after that for manufacturers to reformulate and relabel.¹ Comments on this proposal will be accepted for 120 days after Federal Register publication under docket FDA-2026-N-10832.¹ The agency said the changes would have no immediate effect on the WIC program and that it will coordinate with the USDA and monitor supply during any transition.¹ For clinicians, little changes in the near term: formulas on shelves need not change for years, and…","image":"https://cdn.sanity.io/images/0vv8moc6/contpeds/5a34d56df56e4d13ffe4da27edbf1b4f2e22c1cb-5184x3456.jpg?w=1200&fit=max&fm=jpg"},{"title":"FDA proposes rule updating nutrient requirements for infant formula","summary":"美国食品药品监督管理局（FDA）提出更新婴儿配方奶粉营养需求的规则。该政策调整旨在优化婴幼儿奶粉的营养配方，与乳业与食品安全政策直接相关。对跨境母婴行业从业者，这意味着需关注法规变化，及时调整产品配方以满足标准。此类更新通常基于科学研究和市场反馈，对行业具有指导意义。","source_id":"gnews_en_reg","source_name":"ABC News - Breaking News, Latest News and Videos","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://abcnews.com/Health/fda-proposes-rule-updating-nutrient-requirements-infant-formula/story?id=137680100","published_at":"2026-10-30T01:47:12+08:00","published_guessed":false,"fetched_at":"2026-10-30T03:11:38+08:00","language":"en","author":"","tags":["政策法规","质量安全","供应链"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"5c64f89987cf13b9","title_zh":"FDA 提出更新婴儿配方奶粉营养需求的规则","summary_source":"llm","summary_kind":"brief","points":["FDA 更新营养需求","聚焦婴幼儿奶粉成分","符合食品安全政策"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Food and Drug Administration (FDA) announced on Thursday it is proposing a new rule that will update the nutrient requirements for infant formula. The Department of Health and Human Services (HHS), which oversees the FDA, said in a press release that it would be the first major update to infant formula standards in nearly 30 years. Related Abbott launches new infant formula made with whole milk: What parents need to know The proposed rule would update requirements for vitamin A, vitamin D, iodine and manganese as well as reaffirm existing requirements for chloride, potassium, selenium and sodium, the agencies said. It would also change the units of measure for two nutrients and request public input on possible requirements for ingredients not currently required in infant formula but sometimes added by manufacturers, they noted. The ingredients not currently required include arachidonic acid (ARA), docosahexaenoic acid (DHA), and L-carnitine. Some studies have suggested they contribute greatly to infant growth, brain development and health. In this Oct. 14, 2015, file photo, the U.S. Food and Drug Administration campus is shown in Silver Spring, Md. Andrew Harnik/AP Photo, FILE","image":"https://i.abcnewsfe.com/a/bfc02812-414c-4d98-8b2f-665141e9f7e4/baby-formula-gty-jef-261029_1793289705351_hpMain_16x9.jpg?w=1600"},{"title":"FDA proposes rule updating nutrient requirements for infant formula","summary":"美国食品药品监督管理局提出新规则，将更新婴幼儿奶粉的营养要求，这是近30年来首次重大更新。新规则将更新维生素A、维生素D、碘和锰的要求，并确认氯、钾、硒和钠的现有要求。此外，还将改变两种营养素的计量单位，并征求公众对目前未要求但在婴幼儿奶粉中添加的成分的要求意见。这一更新对跨境奶粉行业从业者意味着需及时调整产品配方以符合新标准，确保产品竞争力。","source_id":"gnews_en_reg","source_name":"Yahoo","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.yahoo.com/news/us/articles/fda-proposes-rule-updating-nutrient-174255938.html","published_at":"2026-10-30T01:42:55+08:00","published_guessed":false,"fetched_at":"2026-10-30T06:57:28+08:00","language":"en","author":"","tags":["政策法规","市场数据","质量安全"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"12b3301b36af2e74","title_zh":"FDA提议更新婴儿配方奶粉营养要求规则","summary_source":"llm","summary_kind":"none","translated":true,"needs_summary":true,"link_resolved":true,"body":"The Food and Drug Administration (FDA) announced on Thursday it is proposing a new rule that will update the nutrient requirements for infant formula. The Department of Health and Human Services (HHS), which oversees the FDA, said in a press release that it would be the first major update to infant formula standards in nearly 30 years. Abbott launches new infant formula made with whole milk: What parents need to know The proposed rule would update requirements for vitamin A, vitamin D, iodine and manganese as well as reaffirm existing requirements for chloride, potassium, selenium and sodium, the agencies said. It would also change the units of measure for two nutrients and request public input on possible requirements for ingredients not currently required in infant formula but sometimes added by manufacturers, they noted. The ingredients not currently required include arachidonic acid (ARA), docosahexaenoic acid (DHA), and L-carnitine. Some studies have suggested they contribute greatly to infant growth, brain development and health. Andrew Harnik/AP Photo, FILE - PHOTO: In this Oct. 14, 2015, file photo, the U.S. Food and Drug Administration campus is shown in Silver Spring, Md. The agency said there will be additional phases looking at the remaining required nutrients, potential new nutrient requirements and carbohydrate sources. The FDA said it will welcome public comment during its phases and, in the future, will issue one final rule to cover all the proposed changes. The FDA also released new data on chemical contaminant testing for infant formula and found that most samples tested had \"low or non-detectable levels of chemical contaminants.\" \"Parents deserve confidence in every bottle they feed their baby,\" HHS Secretary Robert F. Kennedy, Jr. said in a statement, in part. \"We will hold infant formula manufacturers to rigorous scientific standards and put babies' health first.\" Last year, the HHS and FDA announced they would review the nutrition quality of infant formula in the U.S. CDC says 51 infants hospitalized in botulism outbreak amid ByHeart voluntary formula recall The FDA said the review -- part of its \"Operation Stork Speed\" initiative -- would look at whether current nutrient requirements need to be updated, including whether additional nutrients need to be considered.","image":"https://s.yimg.com/lo/mysterio/api/06ff7c316723de26514688bf885b285c39aeb7a8bc95c06105e90326e0adceff/lightyear_networkapi/resizefill_w1200%3Bquality_80%3Bformat_jpg/https%3A%2F%2Fmedia.zenfs.com%2Fen%2Fus.abcnews.go.com%2Fabbab1af4fd124648d6ac2071829eaa2.jpg","points":["FDA更新婴幼儿奶粉营养要求","近30年来首次重大更新","涉及多种维生素和矿物质","需调整产品配方以符合新标准"],"points_source":"llm"},{"title":"Trump Administration Announces First Major Update to Infant Formula Standards in Nearly 30 Years","summary":"特朗普政府宣布近 30 年来首次重大更新婴儿配方奶粉标准。这一政策调整对婴幼儿奶粉行业具有深远影响，涉及营养成分和安全性标准。对跨境渠道的从业者，这意味着需关注法规变化，及时调整产品配方以满足标准。此类更新通常基于科学研究和市场反馈，对行业具有指导意义。","source_id":"gnews_en_reg","source_name":"HHS.gov","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.hhs.gov/press-room/fda-updates-infant-formula-standards-first-time-30-years.html","published_at":"2026-10-30T01:10:49+08:00","published_guessed":false,"fetched_at":"2026-10-30T03:11:38+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"faf1d45e7cc80a73","title_zh":"特朗普政府宣布近 30 年来首次重大更新婴儿配方奶粉标准","summary_source":"llm","summary_kind":"brief","points":["政府重大更新标准"],"points_source":"llm","translated":true,"link_resolved":true,"body":"DES MOINES, IA—OCTOBER 29, 2026— As part of President Trump’s Operation Stork Speed and the broader Make America Healthy Again initiative, the U.S. Department of Health and Human Services (HHS), through the Food and Drug Administration, is taking two actions that reflect the FDA’s comprehensive commitment to ensuring that infant formula is both safe and nutritious for American babies. The agency today issued a proposed rule that, if finalized, would update infant formula nutrient requirements. While that process moves forward, the FDA is taking action now — releasing new chemical contaminant testing data showing that most infant formula samples had low or non-detectable levels of contaminants. “Parents deserve confidence in every bottle they feed their baby,” said HHS Secretary Robert F. Kennedy, Jr. “Under President Trump’s Operation Stork Speed and Make America Healthy Again agenda, we are proposing stronger nutrient requirements, testing formula for contaminants, and putting the results directly in parents’ hands. We will hold infant formula manufacturers to rigorous scientific standards and put babies’ health first.” Secretary Kennedy made the announcement at Amanda the Panda Children Center in Des Moines, Iowa. As part of its first comprehensive review of infant formula nutrients since 1998, the FDA today issued the first of three planned proposed rules that, if finalized, would update infant formula nutrient requirements. The proposed changes would help ensure that infant formula requirements reflect the available gold standard science to support infant growth and development. These efforts will modernize infant formula standards and support the Trump Administration’s priority of ensuring that American families have access to safe and nutrient-dense options that give every baby a healthy start. The proposed changes announced today represent the first phase of the FDA’s comprehensive review of the 30 nutrients currently required in infant formula marketed in the United States. The FDA is conducting the review in three phases, allowing the agency to advance and receive public comment on evidence-based proposals as each phase of the review is completed. Subsequent phases will assess the remaining required nutrients, potential new nutrient requirements, and carbohydrate sources.","image":"https://www.hhs.gov/sites/default/files/styles/og_image_style/public/news_release.png?itok=xKtXaFfw"},{"title":"US FDA proposes new nutrient limits, labeling rules for infant formula","summary":"美国FDA再次提议对婴儿奶粉设定新的营养限制和标签规则，进一步规范产品信息，保障消费者权益。这一政策动向对跨境电商行业影响显著，从业者需关注并调整产品策略以适应新规。","source_id":"gnews_en_reg","source_name":"Reuters","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.reuters.com/business/healthcare-pharmaceuticals/us-fda-proposes-new-nutrient-limits-labeling-rules-infant-formula-2026-10-29/","published_at":"2026-10-30T00:53:53+08:00","published_guessed":false,"fetched_at":"2026-10-30T01:10:18+08:00","language":"en","author":"","tags":["政策法规","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"9c27d064ab938b43","title_zh":"美国FDA提议对婴儿奶粉设定新的营养限制和标签规则","summary_source":"llm","summary_kind":"brief","points":["FDA设定营养限制"],"points_source":"llm","translated":true,"link_resolved":true},{"title":"FDA Proposes Major Update To Infant Formula Nutrient Standards","summary":"美国食品药品监督管理局（FDA）提议对婴幼儿奶粉的营养成分标准进行重大更新。这一举措旨在提高婴幼儿奶粉的营养质量和安全性，确保产品符合儿童成长需求。对跨境电商和母婴行业从业者而言，这意味着需要密切关注政策变化，及时调整产品配方和标签信息，以符合新的法规要求。这一变化将直接影响产品在跨境市场的准入和销售，相关企业需提前做好准备，确保产品符合标准。","source_id":"gnews_en_reg","source_name":"KOA 850 AM & 94.1 FM","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://koacolorado.iheart.com/content/2026-10-29-fda-proposes-major-update-to-infant-formula-nutrient-standards/","published_at":"2026-10-30T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-30T03:11:38+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"afc688eb52bce282","title_zh":"FDA 提出婴幼儿奶粉营养标准重大更新","summary_source":"llm","summary_kind":"brief","points":["美国 FDA 更新婴幼儿奶粉营养标准","新标准将强制执行","跨境奶粉企业需调整配方和标签","行业需关注法规变化并作出应对"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Food and Drug Administration (FDA) is moving forward with a proposed rule to update nutrient requirements for infant formula sold in the United States. According to NBC News , the proposed rule marks the first phase of a three-part plan to review and potentially modify standards for 30 nutrients currently required in infant formula, representing what the agency says would be the biggest update in nearly 30 years. According to Bloomberg Law , the FDA’s proposal cleared a key White House review on Wednesday, paving the way for its public release as soon as Thursday (October 29). The review process at the White House’s Office of Management and Budget was completed in about two weeks. The update follows a comprehensive review of infant formula nutrient standards that began under President Donald Trump ’s administration in 2025. While the exact changes included in the new proposal have not been disclosed, the move signals a significant shift in how infant formula is regulated and may affect the ingredients and nutritional profiles of products marketed to families in the United States. As the FDA prepares for the public release of the proposed rule , industry stakeholders and consumer groups are expected to review and comment on the potential changes. The agency’s plan to modernize infant formula standards comes at a time of increased focus on food safety, nutrition, and innovation in the broader food and nutrition sector. The FDA’s proposed rule on infant formula is expected to undergo public comment before any final changes are implemented, with further phases of the nutrient standards review still to come.","image":"https://i.iheart.com/v3/re/assets.getty/6ae36d0a48a3daaf01b68139?ops=gravity(%22north%22),fit(1200,675),quality(65)"},{"title":"FDA Proposes Major Update To Infant Formula Nutrient Standards","summary":"FDA提议对婴幼儿奶粉营养标准进行重大更新，以提升产品营养水平。这一政策变化对行业从业者至关重要，需密切关注更新内容，及时调整产品配方和营销策略。","source_id":"gnews_en_reg","source_name":"WGCI-FM","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://wgci.iheart.com/content/2026-10-29-fda-proposes-major-update-to-infant-formula-nutrient-standards/","published_at":"2026-10-30T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:54+08:00","language":"en","author":"","tags":["政策法规","质量安全"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"ae0833614b0556e8","title_zh":"FDA拟对婴幼儿奶粉营养标准进行重大更新","summary_source":"llm","summary_kind":"brief","points":["FDA拟对婴幼儿奶粉营养标准进行重大更新"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Food and Drug Administration (FDA) is moving forward with a proposed rule to update nutrient requirements for infant formula sold in the United States. According to NBC News , the proposed rule marks the first phase of a three-part plan to review and potentially modify standards for 30 nutrients currently required in infant formula, representing what the agency says would be the biggest update in nearly 30 years. According to Bloomberg Law , the FDA’s proposal cleared a key White House review on Wednesday, paving the way for its public release as soon as Thursday (October 29). The review process at the White House’s Office of Management and Budget was completed in about two weeks. The update follows a comprehensive review of infant formula nutrient standards that began under President Donald Trump ’s administration in 2025. While the exact changes included in the new proposal have not been disclosed, the move signals a significant shift in how infant formula is regulated and may affect the ingredients and nutritional profiles of products marketed to families in the United States. As the FDA prepares for the public release of the proposed rule , industry stakeholders and consumer groups are expected to review and comment on the potential changes. The agency’s plan to modernize infant formula standards comes at a time of increased focus on food safety, nutrition, and innovation in the broader food and nutrition sector. The FDA’s proposed rule on infant formula is expected to undergo public comment before any final changes are implemented, with further phases of the nutrient standards review still to come.","image":"https://i.iheart.com/v3/re/assets.getty/6ae36d0a48a3daaf01b68139?ops=gravity(%22north%22),fit(1200,675),quality(65)"},{"title":"FDA targets infant formula in 3 big moves. is your baby’s food safer?","summary":"美国食品药品监督管理局（FDA）计划在未来三年内对婴幼儿配方奶粉实施三大重要举措，旨在提升婴幼儿食品的安全性。FDA的人用食品计划已概述了其2026年的优先事项，包括逐步淘汰由石油制成的食品色素、审查引发安全问题的食品添加剂以及为食品包装正面创建营养标签。FDA还计划要求企业提交所有声称属于“公认安全”（GRAS）的新物质的通知，并继续审查已用于食品的化学物质，特别是消费者最担心的物质，如邻苯二甲酸酯、丙基对苯甲酸酯、BHA和BHT。","source_id":"gnews_en_reg","source_name":"Rolling Out","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://rollingout.com/2026/10/29/fda-targets-infant-formula-in-3-big-move/","published_at":"2026-10-29T23:51:56+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:45+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"f8bdd716178ea53d","summary_source":"llm","link_resolved":true,"body":"The Food and Drug Administration has big plans for what ends up on Americans’ plates. The agency’s Human Foods Program has outlined its priorities for 2026, an agenda tied to the Trump administration and Health and Human Services Secretary Robert F. Kennedy Jr.’s Make America Healthy Again initiative. The FDA regulates about 80% of the nation’s food supply, so the changes could reach nearly every kitchen in the country. The new goals build on work that began in 2025, including efforts to phase out food dyes made from petroleum, review food additives that have raised safety concerns and create nutrition labels for the front of food packages. The FDA has organized its 2026 agenda around three main areas. One of the agency’s biggest moves involves substances known as Generally Recognized as Safe, or GRAS. Under the current voluntary system, companies can add certain ingredients to food without notifying the FDA. The agency plans to propose a rule requiring companies to submit notices for all new substances they claim fall under GRAS. The FDA will also continue reviewing chemicals already used in food, starting with those that worry consumers most, such as phthalates, propylparaben, BHA and BHT. Microplastics are on the radar, too. The agency will research reliable ways to detect and measure the tiny particles in food so it can act if they pose a health risk. Through its Closer to Zero initiative, the FDA aims to set limits for cadmium and inorganic arsenic in baby and toddler foods. It also plans to speed up reviews of natural color additives as dyes made from petroleum are phased out, and to issue guidance on when fruit and vegetable juices count as color additives. The FDA wants to help Americans eat better and reduce diseases such as diabetes, obesity, heart disease and certain cancers. Working with the U.S. Department of Agriculture, the agency plans to develop a federal definition of ultraprocessed foods. Through a research partnership with the National Institutes of Health, experts will study how and why these foods may harm health. The FDA also plans to create a strategy to reduce added sugar, which could include defining a low added sugar claim and encouraging companies to cut sugar in processed foods.","image":"https://rollingout.com/wp-content/uploads/2026/10/shutterstock_2463393487-scaled-e1793288584836.jpg","points":["FDA计划未来三年对婴幼儿配方奶粉实施三大举措","逐步淘汰由石油制成的食品色素","审查引发安全问题的食品添加剂","跨境从业者需加强产品安全管理"],"points_source":"llm"},{"title":"FDA Announces Proposed Rule On Infant Formula Nutrient Requirements - Federal Register","summary":"FDA公布婴儿奶粉营养要求新规则提案，涉及营养成分和标签要求，旨在规范市场秩序，保障婴幼儿健康。对母婴行业从业者而言，需及时了解并适应新规则，确保产品符合法规要求。","source_id":"gnews_en_reg","source_name":"TradingView","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.tradingview.com/news/reuters.com,2026:newsml_FWN46F347:0-fda-announces-proposed-rule-on-infant-formula-nutrient-requirements-federal-register/","published_at":"2026-10-29T23:48:10+08:00","published_guessed":false,"fetched_at":"2026-10-30T01:10:18+08:00","language":"en","author":"","tags":["政策法规","质量安全"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"01fdb062cba5e015","title_zh":"FDA公布婴儿奶粉营养要求新规则提案","summary_source":"llm","summary_kind":"brief","points":["FDA公布新规则提案"],"points_source":"llm","translated":true,"link_resolved":true,"image":"https://s.tradingview.com/static/images/illustrations/news-story.jpg"},{"title":"FDA plans to update nutrition rules for infant formula","summary":"美国食品药品监督管理局FDA计划更新婴儿奶粉的营养规则，旨在提升婴儿奶粉的营养标准，保障婴幼儿健康。这一政策调整对跨境电商和母婴行业从业者至关重要，意味着需密切关注FDA的新规动态，及时调整产品配方和营销策略以符合更高标准。行业背景显示，全球范围内对婴幼儿食品营养安全的监管趋严，符合高标准的产品更易获得消费者信任和市场准入优势。","source_id":"gnews_en_reg","source_name":"NBC News","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.nbcnews.com/health/kids-health/fda-infant-formula-update-nutrition-rules-rcna606315","published_at":"2026-10-29T23:48:03+08:00","published_guessed":false,"fetched_at":"2026-10-30T01:10:18+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"afb2a10669f941de","title_zh":"FDA计划更新婴儿奶粉营养规则","summary_source":"llm","summary_kind":"brief","points":["FDA更新营养规则","提升婴儿奶粉标准"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The Food and Drug Administration will propose a new rule Thursday that would update the nutrient requirements for infant formula.","image":"https://media-cldnry.s-nbcnews.com/image/upload/t_nbcnews-fp-1200-630,f_auto,q_auto:best/rockcms/2026-10/261029-baby-rs-8c9b98.jpg"},{"title":"伊利股份前三季度营收约935.82亿元，同比增长3.59%","summary":"伊利股份公布前三季度财报，营收达到935.82亿元，同比增长3.59%。这一增长反映出公司在乳制品市场的稳健表现，对行业内的其他企业具有参考价值。对于跨境电商和母婴行业的从业者来说，伊利作为龙头企业的发展态势，暗示了市场对优质婴幼儿奶粉和乳制品的持续需求，同时也提示从业者需关注行业竞争格局和消费者偏好变化。","source_id":"gnews_cn_brand_fin","source_name":"东方财富","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://emwap.eastmoney.com/a/202610293914989385.html","published_at":"2026-10-29T22:56:56+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:11:20+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","供应链"],"priority":"P1","score":8.0,"matched":["伊利","营收"],"id":"4be6f8bace683ee9","title_zh":"伊利股份前三季度营收约935.82亿元，同比增长3.59%","summary_source":"llm","summary_kind":"brief","points":["伊利股份营收增长3.59%","乳制品市场表现稳健","对行业具有参考价值"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月29日， 伊利股份 发布2026年三季度报告，第三季度实现营业收入约为292.51亿元，同比增长2.40%；实现归母净利润约为30.45亿元。前三季度营业收入约为935.82亿元，同比增长3.59%；实现归母净利润约为88.04亿元。","image":"https://g1.dfcfw.com/g4/202112/20211206191716.png"},{"title":"ByHeart Is “Discontinued” – But Its Founders Are Buying Perrigo’s Infant Formula Business","summary":"ByHeart 品牌的运营状态发生重大变化，宣布停产但创始人计划收购佩里戈旗下的婴幼儿奶粉业务。这一举措显示出对婴幼儿奶粉市场的持续关注和投资。对于母婴行业的从业者而言，这意味着市场竞争格局可能发生变化，需要密切关注相关企业的后续动向和潜在的市场整合影响。","source_id":"gnews_en_reg","source_name":"Marler Blog","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.marlerblog.com/case-news/byheart-is-discontinued-but-its-founders-are-buying-perrigos-infant-formula-business/","published_at":"2026-10-29T22:38:28+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:11:37+08:00","language":"en","author":"","tags":["品牌动态","供应链","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"eab60933f14b9bf5","title_zh":"ByHeart 已“停产”– 但其创始人正收购佩里戈的婴幼儿奶粉业务","summary_source":"llm","summary_kind":"brief","points":["创始人收购佩里戈婴幼儿奶粉业务","品牌运营状态变化","市场竞争格局可能调整"],"points_source":"llm","translated":true,"link_resolved":true,"body":"A hat tip to Anna Edney at Bloomberg News , who has done as much as any reporter in the country to keep infant formula safety in front of the public, for breaking the news today that the people who ran ByHeart are about to become major players in the store-brand formula business. According to Edney’s story, a company led by ByHeart co-founders Ron Belldegrun and Mia Funt – a brother and sister who are now CEO and president of MeridianMade, a contract manufacturer – has agreed to buy Perrigo’s infant formula business for up to $175 million. Dublin-based Perrigo makes the store-brand formula sold under retailer labels across the country. Perrigo says the sale, expected to close in the first half of 2027, will let it focus on its consumer self-care products. Most important for the families: a MeridianMade spokesperson told Bloomberg that ByHeart has been “discontinued” and will not relaunch. ByHeart formula is not coming back. So, ByHeart is gone for good. The babies it sickened, and their families, are not. Before everyone moves on, here is a reminder of what happened and why. In October 2025, California’s Infant Botulism Treatment and Prevention Program noticed that three infants with suspected infant botulism had all been fed the same powdered formula – ByHeart Whole Nutrition. The signal was hard to miss. ByHeart had roughly one percent of U.S. powdered formula sales, yet of the 36 infants treated with BabyBIG between August 1 and November 10, 2025, who had any powdered-formula exposure, 15 – more than 40 percent – had been fed ByHeart. The FDA’s own internal outbreak record called that “highly unusual.” It was the FDA, not ByHeart, that asked for the recall: two lots on November 8, 2025, then every ByHeart product on November 11. ByHeart’s own testing soon found Clostridium botulinum in five of 36 unopened cans spanning three lots. When the CDC declared the outbreak over on February 26, 2026, the final count was 48 infants – 28 confirmed and 20 probable – in 17 states. Every one of them was hospitalized and treated with BabyBIG. Thankfully, none died. But illness onsets ran from December 24, 2023, to November 29, 2025, and ByHeart reported that one positive lot had a production date of November 15, 2024 – meaning contaminated formula was being made and sold nearly a year before the recall."},{"title":"Perrigo to sell infant formula business in deal worth up to $175M","summary":"美国Perrigo公司计划出售其婴儿奶粉业务，交易额最高可达1.75亿美元。这一举措可能改变全球婴幼儿奶粉市场的竞争格局，对跨境奶粉渠道和品牌格局产生深远影响。出售业务通常意味着市场资源的重新分配，从业者需关注潜在的市场变化和机遇。行业背景表明，并购重组是乳业常见策略，可能引发市场集中度提升或新竞争者出现，对品牌定位和渠道布局提出新要求。","source_id":"gnews_en_dairy","source_name":"Crain's Grand Rapids Business","source_url":"https://news.google.com/rss/search?q=(%22infant%20formula%22%20OR%20%22dairy%20industry%22%20OR%20%22milk%20powder%22)%20(price%20OR%20export%20OR%20regulation%20OR%20plant)&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.crainsgrandrapids.com/consumer-products/cgr-perrigo-sells-infant-formula-business-meridianmade-20261029/","published_at":"2026-10-29T22:22:00+08:00","published_guessed":false,"fetched_at":"2026-10-30T01:09:57+08:00","language":"en","author":"","tags":["市场数据","品牌动态","跨境电商"],"priority":"P1","score":12.8,"matched":["infant formula","infant"],"id":"96c30dc041d01da2","title_zh":"Perrigo要出售婴儿奶粉业务 交易额高达1.75亿美元","summary_source":"llm","summary_kind":"brief","points":["美国Perrigo公司计划出售婴儿奶粉业务","交易额最高可达1.75亿美元","可能改变全球婴幼儿奶粉市场竞争格局"],"points_source":"llm","translated":true,"link_resolved":true,"body":"From business and government to philanthropy, education and the arts, these are the leaders shaping West Michigan.","image":"https://www.crainsgrandrapids.com/resizer/v2/ZWF2PK7RU45VWKIKDG7XBO3G7E.jpg?auth=63afe53834a51432e37cc063ecc13a41a512c4916e1fb73a0d077f5d5b23f8e4&width=1200"},{"title":"FDA’s Infant Formula Standards Proposed Rule Moves Step Forward","summary":"美国食品药品监督管理局（FDA）发布了拟议规则，要求婴儿配方奶粉制造商改变产品中四种营养素的含量，这些产品旨在替代或补充母乳。根据FDA的提案，碘、维生素A、维生素D和锰的含量将发生变化，制造商每年重新配方和重新标签产品的成本预计在840万美元到3170万美元之间。该提案是在特朗普政府于2025年启动了数十年来首次全面审查FDA规定的营养素之后提出的。","source_id":"gnews_en_reg","source_name":"Bloomberg Law News","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://news.bloomberglaw.com/health-law-and-business/fdas-infant-formula-standards-proposed-rule-moves-step-forward","published_at":"2026-10-29T22:11:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:11:37+08:00","language":"en","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"207441bff4513328","summary_source":"llm","summary_kind":"brief","points":["FDA婴幼儿奶粉标准提案进展"],"points_source":"llm","translated":true,"title_zh":"FDA的婴儿配方奶粉标准拟议规则向前迈出一步","link_resolved":true,"body":"Infant formula manufacturers face new requirements to change the amount of four nutrients they must include in products designed to replace or supplement breast milk under a proposed rule the FDA released Thursday. A baby formula product’s level of iodine, Vitamin A, Vitamin D, and manganese would have to change under the Food and Drug Administration’s proposal , which estimates implementing the changes by reformulating and relabeling products will cost manufacturers between $8.4 million to $31.7 million annually. The agency’s proposal comes after the Trump administration in 2025 launched the first comprehensive review in decades of nutrients FDA regulations require ... Bloomberg Law provides trusted coverage of current events enhanced with legal analysis. Log in to keep reading or access research tools and resources.","image":"https://news-api.bloomberglaw.com/v1/resize-image?url=https%3A%2F%2Fbloomberg-bna-brightspot.s3.us-east-1.amazonaws.com%2Fbf%2Fbe%2F3c0b64074250a954f4c627333537%2Fgettyimages-1407581605.jpg&width=1200&height=630&fit=cover&removeAnimation=true"},{"title":"Danone changes US leadership in ‘offensive phase’ of its turnaround","summary":"达能任命Francois Lacombe为美国区总裁，旨在扭转美国业务表现不佳的局面。此前美国市场面临需求激增与客户服务滞后的双重挑战。此次人事调整表明达能正加大力度优化区域运营，提升供应链响应速度与服务质量。这对跨境母婴从业者而言，意味着国际乳企在区域市场的渠道管理与客户服务能力将成为竞争关键。","source_id":"fooddive","source_name":"Food Dive","source_url":"https://www.fooddive.com/feeds/news/","original_url":"https://www.fooddive.com/news/Danone-US-protein-glp1-oikos-production-customer-service-disruption/873125","published_at":"2026-10-29T22:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:10:38+08:00","language":"en","author":"Christopher Doering","tags":["品牌动态","供应链","跨境电商"],"priority":"P1","image":"https://imgproxy.divecdn.com/-gX7tX32EKNYap7Kbl7-vlvNEJaWNX6XI_-szAXE0p4/g:nowe:0:765/c:3099:1751/rs:fill:1600:900:1/Z3M6Ly9kaXZlc2l0ZS1zdG9yYWdlL2RpdmVpbWFnZS9JTUdfMDY1M18xLWZvdG9yLTIwMjYwNjE2MTYyNjQyLmpwZw==.webp","score":4.8,"matched":["danone"],"id":"50509fe33ad4fc8b","title_zh":"达能美国业务进入转型攻坚期","summary_source":"llm","summary_kind":"brief","points":["任命Francois Lacombe为美国区总裁","美国市场面临需求激增与服务滞后","达能加大力度优化区域运营表现"],"points_source":"llm","translated":true},{"title":"乳业龙头伊利“现金”奶牛实锤：现金流膨胀至154亿元","summary":"乳业龙头企业伊利被称作“现金”奶牛，其现金流已膨胀至154亿元。这一数据凸显了伊利在经营管理和资本运作方面的卓越能力，为其未来的战略布局和投资提供了坚实保障。对于跨境电商和母婴行业的从业者而言，伊利强大的现金流状况是行业健康发展的一个缩影，也提示从业者需注重企业自身的现金流管理和财务稳健性。","source_id":"gnews_cn_brand_fin","source_name":"搜狐网","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.sohu.com/a/1094581670_121157270?scm=10001.325_13-325_13.0.0-0-0-0-0.5_1334","published_at":"2026-10-29T21:30:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:11:20+08:00","language":"zh","author":"","tags":["品牌动态","质量安全","供应链"],"priority":"P1","score":12.8,"matched":["伊利","乳业","奶牛"],"id":"bdea18813299f319","title_zh":"乳业龙头伊利“现金”奶牛实锤：现金流膨胀至154亿元","summary_source":"llm","summary_kind":"brief","points":["伊利现金流达154亿元","显示公司经营管理卓越","为未来投资提供保障"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月29日晚间，乳业龙头 伊利股份（600887.SH） 披露2026年前三季度业绩报告。前三季度，实现营收935.82亿元，同比增长3.59%；归母净利润88.04亿元，同比下降15.56%；扣非归母净利润85.32亿元，同比降幅为15.55%。 单三季度看，公司实现营收292.51亿元，同比增长2.40%；归母净利润30.45亿元，同比下降5.6%。 从现金流维度看，前三季度伊利现金流增速远超营收增速，彰显出强劲的“造血”能力。具体而言，前三季度公司经营活动现金流量净额同比大涨64.27%至154.41亿元，主要系“收入增加使得销售商品的现金流入增加，同时应付供应商的款项增加，使得购买商品现金流出减少”。 从营收构成来看，伊利股份前三季度的主营业务收入926.77亿元，其中液体乳贡献557.21亿元，占主营业务收入比例的60.12%；奶粉及奶制品收入248.23亿元，占比26.78%；冷饮产品收入101.18亿元，占比10.92%；其他产品收入20.15亿元，占比2.17%。 前三季度，伊利股份的经销收入为879.56亿元，直销模式收入为47.21亿元。分地区看，伊利股份在华北地区的营收为267.71亿元，华南地区的营收为224.98亿元，华中地区的营收为172.57亿元，华东地区的营收为135.35亿元。其他地区的营收为126.15亿元。 从费用端来看，今年前三季度，伊利股份的营业成本为600.71亿元，同比增长2.81%。销售费用为167.53亿元，同比增长1.21%。管理费用为36.18亿元，同比增长4.15%。研发费用为6.32亿元，同比增长0.72%。 与此同时，公司同步披露2026年中期分红预案。据公告，伊利股份拟每股派发现金红利0.42元（含税），以2026年10月22日总股本63.25亿股计算，扣除公司回购专户股份180.02万股，合计派发现金红利26.56亿元，占2026年前三季度归属于上市公司股东净利润的30.17%。 而在此前的9月16日，伊利股份披露大手笔回购方案。公告称，公司2026年第一次临时股东会审议通过回购股份方案，拟使用10亿元—20亿元自有资金，以不超过39.53元/股的价格回购公司股份，回购期限自股东会审议通过之日起不超过6个月，回购股份将全部注销并减少注册资本。 截至10月29日收盘，伊利股份的股价为29.45元/股，涨2.65%，公司总市值为1863亿元。","image":"https://q7.itc.cn/q_70/images03/20261029/599ec5c8a50e457098bf0c4881fb7f03.jpeg"},{"title":"厚积成势 向新而进 伊利前三季度营收核心经营利润双增","summary":"伊利股份前三季度业绩报告显示，公司营收与核心经营利润同步提升。报告强调企业通过积累优势与创新驱动实现增长，这一趋势反映出中国乳企在激烈市场竞争中保持领先地位。伊利持续投入研发与市场拓展，为婴幼儿奶粉行业树立标杆，其成功经验对同类企业具有重要借鉴意义。","source_id":"gnews_cn_brand_fin","source_name":"搜狐网","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.sohu.com/a/1094564360_120988576?scm=10001.325_13-325_13.0.0-0-0-0-0.5_1334","published_at":"2026-10-29T20:56:04+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:28+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","政策法规"],"priority":"P1","score":8.0,"matched":["伊利","营收"],"id":"b24b8d9fca934511","title_zh":"厚积成势 向新而进 伊利前三季度营收核心经营利润双增","summary_source":"llm","summary_kind":"brief","points":["伊利营收利润同步提升","强调积累与创新驱动","保持行业领先地位"],"points_source":"llm","translated":true,"link_resolved":true,"body":"潮起有时，势成于先。10月29日，伊利股份发布2026年三季报，前三季度营业总收入达938.13亿元，在高基数上同比增长3.59%，核心经营利润更是实现9%的增长。 乳业“一超”，不只“超”在规模，更“超”在增长的稳定性和持续性。拉长周期看，1995年至2025年，公司营业总收入、归母净利润年化复合增速超23%。这份可预见，恰是不确定时代最可贵的价值。 前三季度，基本盘液体乳业务稳健复苏，营收达557.21亿元；实现大满贯的奶粉及奶制品稳健增长，营收248.23亿元，再创历史新高；冷饮业务营收101.18亿元。 双节期间，依托全新渠道体系，伊利主动出击、全线发力，液奶终端动销提速，零食店、会员店、电商平台等均实现较好增长；战略新业务成人营养品更是实现双位数增长，为四季度冲刺及2027年加速增长蓄足动能。 三季报发布同期，伊利还发布中期利润分配预案，拟派发现金红利总额为26.6亿元，经营成果及时回馈广大投资者。另外，公司已启动规模不超过20亿元的回购注销计划，传递出对未来发展的坚定信心和回馈股东的十分诚意。 拿着旧地图，到不了新大陆。对于公司最大的基本盘液奶业务，伊利从未停止思考和布局。 过去的“普适性增长”已逐渐见顶，但下游市场依然存在结构性机遇，消费分级趋势愈发明显。 洞察到消费者对口感、新鲜度的双重需求，伊利以“工欲善其事，必先利其器”的战略耐心和魄力，对液奶业务进行了颠覆性的数智化变革，强力推动新鲜度领先战略，以此重塑终端渠道，渠道库存和产品新鲜度得到极大优化。 通过数智化手段，构建“一物一码”的物码体系，给每一件产品赋予唯一的数字身份证，从产品下线的那一刻起，就伴随着它走完整个生命周期：从生产线赋码、经销商扫码入库、门店扫码收货，到消费者扫码领奖，实现全流程数据追踪。 这种全链路透明，全链路可控，保障了每一件产品在整个周转过程中以更新鲜的日期、更快地抵达消费者。 与此同时，过去面对电商冲击“有劲使不上”的渠道伙伴，在伊利数智赋能下对渠道的一系列大力整顿优化后，发现“自己又能了”，重新掌握经营主动权，盈利得到显著提升。 渠道秩序改善，经营信心回归，团队活力全面激活。提质增效之外，数智化工具的最大价值，是让人与人距离更近，与合作伙伴建立起更强的互信机制，厂商发力方向开始一致。 通过近两年的渠道价值链重塑，产业链上下游生态变得更好，伊利具备了更强的市场终端覆盖能力，体系能力进一步夯实。 渠道变革之外，产品端也在一起发力。以更鲜活的产品，去赢得消费者、赢得市场，是伊利推进新鲜度领先战略的另一个重点。","image":"https://q1.itc.cn/q_70/images03/20261029/fc42f0446c6a42e59769ac96c858b06f.jpeg"},{"title":"Nestlé tackles regenerative agriculture’s missing piece","summary":"雀巢与欧洲鸟类保护组织启动三年半项目，测量再生农业对生物多样性的影响。这一举措标志着行业从关注土壤健康和碳减排转向生态系统修复的更广泛转变。对跨境母婴行业而言，可持续农业实践将影响原料供应链和产品配方研发方向，推动行业向更环保、更可持续的方向发展，促使企业更加重视生态平衡和生物多样性保护，以适应未来市场变化和消费者需求。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/29/nestle-x-birdlife-collaboration-signals-next-phase-of-regenerative-agriculture","published_at":"2026-10-29T18:56:30+08:00","published_guessed":false,"fetched_at":"2026-10-29T19:01:44+08:00","language":"en","author":"Donna Eastlake","tags":["品牌动态","政策法规","质量安全"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/UI766HWE6BHYLOL7MHUMCUDI4Q.jpg?auth=52122dfa8e8ed938af79534ebbd1fec3bf74b87b07e0485aa58c525cd496cd98&smart=true&width=4528&height=3012","score":4.8,"matched":["nestlé"],"id":"2a1ee9da1c2d9416","title_zh":"雀巢解决再生农业的缺失环节","summary_source":"llm","summary_kind":"brief","points":["转向生态系统修复","推动农业可持续发展"],"points_source":"llm","translated":true},{"title":"Nestlé tackles regenerative agriculture’s missing piece","summary":"雀巢与BirdLife Europe合作启动为期三年半的项目，旨在评估再生农业对生物多样性的影响。该项目标志着雀巢在农业可持续发展领域的战略深化，从关注土壤健康和碳减排转向更广泛的生态系统修复。对于跨境母婴从业者，这反映了乳业上游供应链正加速向可持续与生态友好型转型，绿色供应链管理将成为行业新趋势。","source_id":"foodnavigator_asia","source_name":"FoodNavigator-Asia","source_url":"https://www.foodnavigator-asia.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/29/nestle-x-birdlife-collaboration-signals-next-phase-of-regenerative-agriculture","published_at":"2026-10-29T18:56:30+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:10:38+08:00","language":"en","author":"Donna Eastlake","tags":["供应链"],"priority":"P1","image":"https://www.foodnavigator.com/resizer/v2/UI766HWE6BHYLOL7MHUMCUDI4Q.jpg?auth=52122dfa8e8ed938af79534ebbd1fec3bf74b87b07e0485aa58c525cd496cd98&smart=true&width=4528&height=3012","score":4.8,"matched":["nestlé"],"id":"a7c5fa91bb0de256","title_zh":"雀巢启动再生农业项目","summary_source":"llm","summary_kind":"brief","points":["雀巢与BirdLife启动三年半再生农业项目","项目聚焦评估再生农业对生物多样性影响","乳业供应链加速向可持续生态友好转型"],"points_source":"llm","translated":true},{"title":"伊利股份前三季度营收、核心经营利润双增，中期分红26.6亿","summary":"伊利股份公布前三季度财报，营收与核心经营利润实现双增长，并宣布中期分红26.6亿元。这一业绩表现反映出公司在母婴奶粉市场的强劲竞争力，分红政策增强投资者信心。伊利作为行业龙头，其经营状况对整个乳制品行业具有风向标意义，持续增长也表明市场对高品质婴幼儿奶粉的需求稳定。","source_id":"gnews_cn_brand_fin","source_name":"金融界","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://stock.jrj.com.cn/2026/10/29185458933018.shtml","published_at":"2026-10-29T18:54:50+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:28+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","政策法规"],"priority":"P1","score":8.0,"matched":["伊利","营收"],"id":"c1b9e52b97c811f7","title_zh":"伊利股份前三季度营收、核心经营利润双增，中期分红26.6亿","summary_source":"llm","summary_kind":"brief","points":["伊利营收利润双增长","中期分红26.6亿元","母婴市场竞争力强劲"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月29日， 伊利股份 （600887.SH）披露2026年三季报。前三季度，公司实现营业总收入938.13亿元，同比增长3.59%，稳居亚洲乳业第一；核心经营利润114亿元，同比增长9.0%，再创新高；核心经营利润率12.3%，同比提升63个基点，盈利质量持续走强。 公司三大核心业务均稳居行业第一。前三季度，基本盘液体乳业务稳健复苏，营收达557.21亿元；实现大满贯的奶粉及奶制品稳健增长，营收248.23亿元，再创历史新高；冷饮业务营收101.18亿元，连续31年稳居行业第一。 公司同步披露2026年中期分红预案，拟向全体股东派发现金红利26.6亿元。另外，公司已启动的规模不超过20亿元的回购注销计划，传递出对未来发展的坚定信心和回馈股东的十分诚意。 伊利股份的高股息、稳增长属性进一步获得长期资金青睐。北向资金三季度累计增持伊利股份8903万股。 AI智能分析该文，为您挖掘投资机会 该AI功能处于试用阶段，内容仅供参考，请仔细甄别！ 展开 AI智能分析该文，为您挖掘投资机会 该AI功能处于试用阶段，内容仅供参考，请仔细甄别！","image":"https://img.jrjimg.cn/2026/10/20261029185440571.jpeg"},{"title":"【立方招采通】郑州山姆会员商店泛光照明工程项目招标/郑大三附院预算1200万元采购婴幼儿辅食营养包","summary":"郑州山姆会员商店启动泛光照明工程项目招标，同时郑大三附院计划投入1200万元采购婴幼儿辅食营养包。此举显示母婴用品市场需求旺盛，尤其婴幼儿辅食营养包作为重要品类，其采购规模扩大对相关供应商和渠道商带来积极信号。对于跨境母婴行业从业者而言，此类采购活动反映了市场对婴幼儿产品品质和营养价值的持续关注，提示需加强供应链管理和产品研发以适应市场需求变化。","source_id":"gnews_cn_baby_category","source_name":"大河财立方","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://app.dahecube.com/article.html?artid=291302?recid=1","published_at":"2026-10-29T17:26:47+08:00","published_guessed":false,"fetched_at":"2026-10-30T09:21:25+08:00","language":"zh","author":"","tags":["市场数据","供应链","品牌动态"],"priority":"P1","score":12.8,"matched":["婴幼儿","辅食"],"id":"7e50c40868282be9","title_zh":"郑州山姆会员商店泛光照明工程项目招标/郑大三附院预算1200万元采购婴幼儿辅食营养包","summary_source":"llm","summary_kind":"brief","points":["郑州山姆会员商店招标泛光照明工程","郑大三附院采购婴幼儿辅食营养包预算1200万元","母婴用品市场需求旺盛","婴幼儿辅食营养包采购规模扩大"],"points_source":"llm","translated":true,"link_resolved":true,"image":"https://res.dahecube.com/nweb/res/pc/img/2.png"},{"title":"从“全球奶粉销量第一”口径看佳贝艾特悦白：细分品类的吸收与低敏验证_行业新闻","summary":"佳贝艾特悦白奶粉作为全球销量领先的细分品类产品，通过吸收与低敏验证，满足了特定需求消费者。这一成功案例为母婴行业提供了细分市场开发的参考，从业者可借鉴其产品研发和市场定位策略。对行业而言，这意味着关注消费者差异化需求，通过产品创新满足细分市场，是提升竞争力的关键。","source_id":"gnews_cn_crossborder","source_name":"证券之星","source_url":"https://news.google.com/rss/search?q=%E8%B7%A8%E5%A2%83%E7%94%B5%E5%95%86%20(%E5%A5%B6%E7%B2%89%20OR%20%E5%A9%B4%E9%85%8D%20OR%20%E6%AF%8D%E5%A9%B4)%20OR%20%E6%B5%B7%E5%85%B3%20(%E5%A9%B4%E5%B9%BC%E5%84%BF%E9%85%8D%E6%96%B9%E4%B9%B3%E7%B2%89%20OR%20%E5%A5%B6%E7%B2%89)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://finance.stockstar.com/IG2026102900037607.shtml","published_at":"2026-10-29T15:54:31+08:00","published_guessed":false,"fetched_at":"2026-10-29T19:02:04+08:00","language":"zh","author":"","tags":["市场数据","质量安全","品牌动态"],"priority":"P0","score":12.8,"matched":["奶粉","佳贝艾特"],"id":"44ebedad34982d08","title_zh":"从“全球奶粉销量第一”口径看佳贝艾特悦白：细分品类的吸收与低敏验证","summary_source":"llm","summary_kind":"brief","points":["佳贝艾特悦白奶粉销量领先","细分品类产品通过吸收与低敏验证","为母婴行业提供市场开发参考","借鉴产品研发和市场定位策略"],"points_source":"llm","translated":true,"link_resolved":true,"image":"https://i.ssimg.cn/ssimages/2026/10/29/bc3c0dc9f604478d97ec743862c8adba.jpg"},{"title":"从“全球奶粉销量第一”口径看佳贝艾特悦白：细分品类的吸收与低敏验证_行业新闻_财经","summary":"佳贝艾特悦白作为全球销量领先的婴幼儿奶粉品牌，持续聚焦细分品类的吸收与低敏特性。该产品旨在满足特定消费者群体需求，体现了品牌在功能性奶粉领域的研发方向。对行业从业者而言，关注细分市场与产品特性是提升竞争力的关键，佳贝艾特的实践为行业提供了参考。全渠道、母婴店、电商、跨境电商的排名可能不同。品牌层面，援引尼尔森IQ、沙利文及星图数据，佳贝艾特全渠道销售额份额29.9%，销售额超过羊奶粉第2—10名总和，品牌位列全球羊奶粉销量第一[1]；","source_id":"gnews_cn_goat","source_name":"证券之星","source_url":"https://news.google.com/rss/search?q=%28%E7%BE%8A%E5%A5%B6%E7%B2%89%20OR%20%E7%BE%8A%E4%B9%B3%20OR%20%E5%B1%B1%E7%BE%8A%E5%A5%B6%29%20%28%E5%A9%B4%E5%B9%BC%E5%84%BF%20OR%20%E9%85%8D%E6%96%B9%20OR%20%E5%B8%82%E5%9C%BA%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://wap.stockstar.com/detail/IG2026102900037607","published_at":"2026-10-29T15:54:31+08:00","published_guessed":false,"fetched_at":"2026-10-30T01:10:05+08:00","language":"zh","author":"","tags":["品牌动态"],"priority":"P0","score":12.8,"matched":["奶粉","佳贝艾特"],"id":"556fa1cfeeba83e0","title_zh":"佳贝艾特悦白：细分品类的吸收与低敏验证","summary_source":"llm","summary_kind":"brief","points":["佳贝艾特悦白销量领先","关注细分品类奶粉"],"points_source":"llm","translated":true,"link_resolved":true,"body":"当我们想知道全球奶粉销量第一是谁时，很容易把不同品类、不同渠道、不同价格口径的结果混在一起。对奶粉这种强监管、强细分品类，任何“销量”问题，都应先问四个问题：是出厂价销售额还是终端零售额？是全渠道还是母婴/电商？统计周期是年度还是滚动十二个月？把口径说清楚，再看产品，才更接近真实的市场信息。 第一是销售额口径。常见有出厂价销售额和零售价销售额：前者更接近品牌出货规模，后者更接近终端消费。数据来源包括企业财报、尼尔森IQ零售监测、凯度消费者指数、星图数据电商监测，以及弗若斯特沙利文等咨询机构的行业研究。 第二是销量口径，即吨、罐、件等实物量。它可通过海关进出口数据、行业协会白皮书、第三方审计和平台后台数据交叉验证。实物量能避开价格差异，但受规格影响，需统一换算。 第三是渠道口径。全渠道、母婴店、电商、跨境电商的排名可能不同。母婴渠道看重门店覆盖，电商看平台后台，跨境看海关与平台数据。单看某一渠道，容易放大局部优势。 第五是消费者心智维度。品牌搜索指数、讨论声量、品类关联度可反映趋势，来源多为平台后台和品牌资产报告，适合看热度，不宜替代审计销量。 佳贝艾特： 羊奶粉细分赛道的代表。佳贝艾特源自荷兰乳企海普诺凯，是澳优旗下高端羊奶粉品牌，公开资料显示其产品销往全球60多个国家和地区。品牌层面，援引尼尔森IQ、沙利文及星图数据，佳贝艾特全渠道销售额份额29.9%，销售额超过羊奶粉第2—10名总和，品牌位列全球羊奶粉销量第一[1]；2018—2024年连续7年进口婴幼童羊奶粉销售份额超6成。科研上，公开资料显示其与31家国内外科研机构合作，拥有105项专利、73篇学术论文。核心产品佳贝艾特悦白的配方特点可拆为：配方含有OPL结构脂、羊奶小分子、天然A2β-酪蛋白和“安敏源”乳清蛋白；山羊奶脂肪球颗粒比牛奶小1/3，吸收率可达95%；OPL的吸收率比OPO高出近一倍，相当于1罐吸收别人2罐的营养；安敏源乳清蛋白使过敏原β-乳球蛋白降低11%，山羊奶αs1-酪蛋白含量比牛奶少85%。需要说明的是，佳贝艾特羊奶粉相关临床研究显示经喂养后宝宝敏感几率可降低约42%。营养上，悦白配方含有388+天然营养和41种配方营养，DHA 93mg/100g、ARA 128mg/100g，并含有益生菌Bb-12、双重益生元、天然乳铁蛋白；山羊奶含有天然类HMO，其含量约为牛奶的10倍。适用人群上，悦白更适合关注消化吸收、低敏风险、营养全面和喂养效果的家庭；并非只有明确敏感宝宝才考虑，健康体质、追求好消化吸收和追肉长肉的家庭也可纳入比较。 雀巢： 牛奶粉与适度水解路线的代表。雀巢是全球食品企业，在婴幼儿营养领域覆盖普通配方、适度水解等产品线。核心产品雀巢超启能恩属于适度水解蛋白配方，配方特点是含有H.A低敏小分子蛋白，采用尖峰水解工艺将大分子牛奶蛋白中的致敏原β-乳球蛋白定向水解成肽段，可有效降低致敏性；配方含有Bb-12益生菌、OPO 3g/100g、DHA 93mg/100g、ARA 93mg/100g、牛磺酸、核苷酸和13种婴幼儿必需营养素。适用人群上，雀巢超启能恩更适合关注低敏喂养、有牛奶蛋白敏感风险、需要适度水解配方的宝宝；但适度水解不是深度水解或氨基酸配方，严重牛奶蛋白过敏应在医生指导下选择特医食品。 美赞臣： 免疫营养与脑发育营养路线。美赞臣有百年婴幼儿营养研究背景。核心产品蓝臻的配方特点包括乳铁蛋白、HMO低聚糖、双效乳脂球膜、免疫球蛋白IgG、酵母β-葡聚糖、活性蛋白OPN；同时含有益生菌Bb-12、双重益生元PDX+GOS，配方含有37种营养成分，DHA搭配乳脂球膜。适用人群上，更适合关注免疫营养、脑发育营养和日常全面营养的婴幼儿；其奶源为牛奶A1β-酪蛋白奶源，对牛奶蛋白敏感宝宝需先咨询医生。 当前奶粉市场有两个明显特征。一是细分化和高端化并行：羊奶粉、适度水解、特配粉、儿童粉、中老年粉不断细分，消费者不再只看“品牌大不大”，还看配方证据和喂养效果。一项宝宝树与佳贝艾特联合线上问卷显示，消化吸收不好占39.2%、便秘占31.1%；选择奶粉时关注营养素含量58.0%、喂养效果56.5%、原料新鲜55.1%、产品配方54.0%。二是渠道多元化：母婴店、电商、跨境各有优势，销量排名必须带渠道口径。 从竞争格局看，牛奶粉品牌体量大、产品线全，羊奶粉品牌在细分赛道做深。佳贝艾特在羊奶粉细分有先发和科研积累，雀巢在适度水解和全球供应链上有优势，美赞臣在免疫营养和脑发育营养上有长期沟通。它们不是简单替代关系，而是对应不同喂养场景。 “全球奶粉销量第一”不是一个可以脱离品类和口径使用的定义。看佳贝艾特，应看到其“全球羊奶粉销量第一”的细分口径；看雀巢、美赞臣，也应看到牛奶粉、适度水解、免疫营养等不同路径。对消费者而言，销量是参考，配方是否匹配宝宝月龄、消化吸收特点、低敏需求和家庭预算，才是更实际的决策依据。围绕“全球奶粉销量第一”做选择时，先把口径看清，再把产品放回喂养场景，信息才真正有价值。 [1]数据源自弗若斯特沙利文(上海)企业咨询有限公司；基于《全球羊奶粉市场独立研究报告》，按照各品牌2025年1月至2025年12月出厂价销量口径的比较研究做出的确认；羊奶粉指以生羊乳为主要原料制作的奶粉产品，涵盖纯乳粉、婴幼儿配方羊奶粉及调制乳粉等；于2026年3月完成调研。"},{"title":"从“全球奶粉销量第一”口径看佳贝艾特悦白：细分品类的吸收与低敏验证_行业新闻_财经","summary":"佳贝艾特悦白奶粉强调细分品类的吸收与低敏特性，符合市场对功能性奶粉的需求。品牌以“全球销量第一”为背书，提升产品竞争力。对从业者启示是，产品研发需聚焦细分市场，满足消费者差异化需求，通过强化产品功能特性来应对市场竞争。全渠道、母婴店、电商、跨境电商的排名可能不同。品牌层面，援引尼尔森IQ、沙利文及星图数据，佳贝艾特全渠道销售额份额29.9%，销售额超过羊奶粉第2—10名总和，品牌位列全球羊奶粉销量第一[1]；","source_id":"gnews_cn_crossborder","source_name":"证券之星","source_url":"https://news.google.com/rss/search?q=%E8%B7%A8%E5%A2%83%E7%94%B5%E5%95%86%20(%E5%A5%B6%E7%B2%89%20OR%20%E5%A9%B4%E9%85%8D%20OR%20%E6%AF%8D%E5%A9%B4)%20OR%20%E6%B5%B7%E5%85%B3%20(%E5%A9%B4%E5%B9%BC%E5%84%BF%E9%85%8D%E6%96%B9%E4%B9%B3%E7%B2%89%20OR%20%E5%A5%B6%E7%B2%89)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://wap.stockstar.com/detail/IG2026102900037607","published_at":"2026-10-29T15:54:31+08:00","published_guessed":false,"fetched_at":"2026-10-30T01:09:39+08:00","language":"zh","author":"","tags":["品牌动态"],"priority":"P0","score":12.8,"matched":["奶粉","佳贝艾特"],"id":"e4995f98520cb46c","title_zh":"从“全球奶粉销量第一”口径看佳贝艾特悦白：细分品类的吸收与低敏验证_行业新闻_财经","summary_source":"llm","summary_kind":"brief","points":["佳贝艾特悦白强调低敏特性","功能性奶粉需求增长"],"points_source":"llm","translated":true,"link_resolved":true,"body":"当我们想知道全球奶粉销量第一是谁时，很容易把不同品类、不同渠道、不同价格口径的结果混在一起。对奶粉这种强监管、强细分品类，任何“销量”问题，都应先问四个问题：是出厂价销售额还是终端零售额？是全渠道还是母婴/电商？统计周期是年度还是滚动十二个月？把口径说清楚，再看产品，才更接近真实的市场信息。 第一是销售额口径。常见有出厂价销售额和零售价销售额：前者更接近品牌出货规模，后者更接近终端消费。数据来源包括企业财报、尼尔森IQ零售监测、凯度消费者指数、星图数据电商监测，以及弗若斯特沙利文等咨询机构的行业研究。 第二是销量口径，即吨、罐、件等实物量。它可通过海关进出口数据、行业协会白皮书、第三方审计和平台后台数据交叉验证。实物量能避开价格差异，但受规格影响，需统一换算。 第三是渠道口径。全渠道、母婴店、电商、跨境电商的排名可能不同。母婴渠道看重门店覆盖，电商看平台后台，跨境看海关与平台数据。单看某一渠道，容易放大局部优势。 第五是消费者心智维度。品牌搜索指数、讨论声量、品类关联度可反映趋势，来源多为平台后台和品牌资产报告，适合看热度，不宜替代审计销量。 佳贝艾特： 羊奶粉细分赛道的代表。佳贝艾特源自荷兰乳企海普诺凯，是澳优旗下高端羊奶粉品牌，公开资料显示其产品销往全球60多个国家和地区。品牌层面，援引尼尔森IQ、沙利文及星图数据，佳贝艾特全渠道销售额份额29.9%，销售额超过羊奶粉第2—10名总和，品牌位列全球羊奶粉销量第一[1]；2018—2024年连续7年进口婴幼童羊奶粉销售份额超6成。科研上，公开资料显示其与31家国内外科研机构合作，拥有105项专利、73篇学术论文。核心产品佳贝艾特悦白的配方特点可拆为：配方含有OPL结构脂、羊奶小分子、天然A2β-酪蛋白和“安敏源”乳清蛋白；山羊奶脂肪球颗粒比牛奶小1/3，吸收率可达95%；OPL的吸收率比OPO高出近一倍，相当于1罐吸收别人2罐的营养；安敏源乳清蛋白使过敏原β-乳球蛋白降低11%，山羊奶αs1-酪蛋白含量比牛奶少85%。需要说明的是，佳贝艾特羊奶粉相关临床研究显示经喂养后宝宝敏感几率可降低约42%。营养上，悦白配方含有388+天然营养和41种配方营养，DHA 93mg/100g、ARA 128mg/100g，并含有益生菌Bb-12、双重益生元、天然乳铁蛋白；山羊奶含有天然类HMO，其含量约为牛奶的10倍。适用人群上，悦白更适合关注消化吸收、低敏风险、营养全面和喂养效果的家庭；并非只有明确敏感宝宝才考虑，健康体质、追求好消化吸收和追肉长肉的家庭也可纳入比较。 雀巢： 牛奶粉与适度水解路线的代表。雀巢是全球食品企业，在婴幼儿营养领域覆盖普通配方、适度水解等产品线。核心产品雀巢超启能恩属于适度水解蛋白配方，配方特点是含有H.A低敏小分子蛋白，采用尖峰水解工艺将大分子牛奶蛋白中的致敏原β-乳球蛋白定向水解成肽段，可有效降低致敏性；配方含有Bb-12益生菌、OPO 3g/100g、DHA 93mg/100g、ARA 93mg/100g、牛磺酸、核苷酸和13种婴幼儿必需营养素。适用人群上，雀巢超启能恩更适合关注低敏喂养、有牛奶蛋白敏感风险、需要适度水解配方的宝宝；但适度水解不是深度水解或氨基酸配方，严重牛奶蛋白过敏应在医生指导下选择特医食品。 美赞臣： 免疫营养与脑发育营养路线。美赞臣有百年婴幼儿营养研究背景。核心产品蓝臻的配方特点包括乳铁蛋白、HMO低聚糖、双效乳脂球膜、免疫球蛋白IgG、酵母β-葡聚糖、活性蛋白OPN；同时含有益生菌Bb-12、双重益生元PDX+GOS，配方含有37种营养成分，DHA搭配乳脂球膜。适用人群上，更适合关注免疫营养、脑发育营养和日常全面营养的婴幼儿；其奶源为牛奶A1β-酪蛋白奶源，对牛奶蛋白敏感宝宝需先咨询医生。 当前奶粉市场有两个明显特征。一是细分化和高端化并行：羊奶粉、适度水解、特配粉、儿童粉、中老年粉不断细分，消费者不再只看“品牌大不大”，还看配方证据和喂养效果。一项宝宝树与佳贝艾特联合线上问卷显示，消化吸收不好占39.2%、便秘占31.1%；选择奶粉时关注营养素含量58.0%、喂养效果56.5%、原料新鲜55.1%、产品配方54.0%。二是渠道多元化：母婴店、电商、跨境各有优势，销量排名必须带渠道口径。 从竞争格局看，牛奶粉品牌体量大、产品线全，羊奶粉品牌在细分赛道做深。佳贝艾特在羊奶粉细分有先发和科研积累，雀巢在适度水解和全球供应链上有优势，美赞臣在免疫营养和脑发育营养上有长期沟通。它们不是简单替代关系，而是对应不同喂养场景。 “全球奶粉销量第一”不是一个可以脱离品类和口径使用的定义。看佳贝艾特，应看到其“全球羊奶粉销量第一”的细分口径；看雀巢、美赞臣，也应看到牛奶粉、适度水解、免疫营养等不同路径。对消费者而言，销量是参考，配方是否匹配宝宝月龄、消化吸收特点、低敏需求和家庭预算，才是更实际的决策依据。围绕“全球奶粉销量第一”做选择时，先把口径看清，再把产品放回喂养场景，信息才真正有价值。 [1]数据源自弗若斯特沙利文(上海)企业咨询有限公司；基于《全球羊奶粉市场独立研究报告》，按照各品牌2025年1月至2025年12月出厂价销量口径的比较研究做出的确认；羊奶粉指以生羊乳为主要原料制作的奶粉产品，涵盖纯乳粉、婴幼儿配方羊奶粉及调制乳粉等；于2026年3月完成调研。"},{"title":"Bubs Australia (ASX:BUB) Secures Permanent FDA Authorisation for Three Infant Formula Products","summary":"Bubs Australia（澳交所：BUB）宣布其三种婴儿奶粉产品获得美国FDA的永久授权。这一重要进展表明该公司产品符合美国严格的食品安全标准，有助于提升品牌在美国市场的竞争力。对于跨境母婴行业从业者，这意味着Bubs Australia的产品将更容易进入美国市场，为消费者提供更多选择。同时，这也反映了美国市场对高品质婴儿奶粉的需求持续增长，为行业提供了新的发展机遇。","source_id":"gnews_en_reg","source_name":"Kalkine","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://kalkine.com.au/news/healthcare/bubs-australia-asxbub-secures-permanent-fda-authorisation-for-three-infant-formula-products","published_at":"2026-10-29T12:58:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:45+08:00","language":"en","author":"","tags":["品牌动态","政策法规","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"b3007213b8c619e8","title_zh":"Bubs Australia（澳交所：BUB）获得美国FDA对三种婴儿奶粉产品的永久授权","summary_source":"llm","summary_kind":"brief","points":["获得FDA永久授权"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Bubs Australia (ASX:BUB) Limited said it secured permanent US Food and Drug Administration authorisation in September 2026 for three of its infant formula products. The company said it is the only Australian infant formula manufacturer holding this authorisation. The announcement came in its report for the quarter ended 30 September 2026, in which group net revenue fell to A$23.1 million. Bubs said potential private label participation in the US market is subject to further regulatory, technical and commercial milestones, so the authorisation does not by itself represent a contract or revenue. The company said its products are now in more than 12,000 US stores across all 50 states, retail scan sales hit a record, up 46.5 per cent on the prior corresponding period and 10.6 per cent on the June quarter, and Amazon consumer sell-through rose more than 14 per cent year on year. The September quarter also marked the first sales through the CVS drug channel. Group net revenue was A$23.1 million, down 9.8 per cent from A$25.6 million a year earlier. Bubs said currency translation reduced reported US revenue by A$1.2 million, with the average exchange rate at 0.71 against 0.65 a year earlier. US revenue was A$15.3 million (US$10.8 million), compared with A$16.8 million (US$11.0 million). The company said Walmart and Target grew strongly while Amazon sales fell because the year-earlier quarter had a higher replenishment base. China revenue was A$2.6 million, up from A$2.5 million, with channel sell-in and sell-through described as normalised. Australia was A$4.1 million, down from A$4.4 million, which the company attributed to cost-of-living pressure while noting early signs of stabilisation. Rest of World was A$1.2 million, down from A$1.9 million because of disrupted trading that the company said is partly recovering. Receipts from customers were A$24.193 million. Operating cash outflow was A$6.006 million, compared with A$4.4 million in the first quarter of FY26. Operating payments included A$18.7 million for manufacturing and operating costs, A$3.1 million for advertising and marketing, A$4.6 million for staff costs and A$3.0 million for administration and corporate costs.","image":"https://kalkine.com.au/featured_image/gallery/xlarge/shutterstock_2294203817_10_29_2026_05_00_44_344434.jpg"},{"title":"光明致优如何决胜实体母婴？","summary":"光明致优通过打击窜货行为，强化实体渠道管控，提升品牌形象。2025年，坦图在杭州发现一箱窜货奶粉，最终溯源至湖南张家界。这一行动展示了光明致优对渠道管理的重视，对行业其他企业具有借鉴意义。窜货行为损害品牌声誉，加强管控有助于维护市场秩序，提升消费者信任度。","source_id":"muyingqianyan","source_name":"母婴前沿","source_url":"https://www.muyingqianyan.com/feed","original_url":"https://www.muyingqianyan.com/123368.html","published_at":"2026-10-29T11:26:51+08:00","published_guessed":false,"fetched_at":"2026-10-29T13:02:01+08:00","language":"zh","author":"前沿, 母婴","tags":["品牌动态","跨境电商","政策法规"],"priority":"P0","score":10.9,"matched":["奶粉","母婴店","母婴"],"id":"43e59e1bfb11eac0","title_zh":"光明致优如何决胜实体母婴？","summary_source":"llm","summary_kind":"brief","points":["打击窜货行为强化管控","提升消费者信任度"],"points_source":"llm","translated":true,"body":"2025年，坦图在杭州市场发现一箱窜货奶粉。顺着货流追查，货源最终指向湖南张家界一家母婴店。为查清这条线索，坦图团队亲自驱车前往，来回近1000公里，12小时，住宿、油费、人力加起来至少2000块。 如果你想问，就为了一条窜货线索，值吗？算单笔账，血亏。但坦图却认为， 这趟必须得走，要让全国代理商和门店都看见，光明致优在控货这件事上，不是说说而已。 到了张家界，门店拿出一套微信聊天记录，试图解释货物流向，但坦图团队还是从蛛丝马迹中发现，聊天记录是门店伪造的，查实了窜货源头。 在婴配粉行业，控货防串是人人都会念的经，但真正愿意为了一条窜货线索就烧掉几千块，屈指可数。但坦图算的不是这一单的账，而是另一本账： 你放过一家窜货门店，就会有100个门店不再相信你。 在一个出生人口跌到792万，婴配粉销量增长几乎全靠价增的年份里，渠道信任比黄金贵，这就是坦图的“狠”。 “狠”也在另一组数字里： 九个客服，一年回访出76%以上的回购率，退货率控制在万分之六；不碰大连锁，只做单体店和中小连锁；河北、湖北、湖南还有几个地级市没进，但这些市场空白全部都要消灭掉。 2023年，坦图接手光明致优，第一年55万罐，2024年155万罐，2025年200多万罐。在存量市场里画出这条上升曲线，靠的不是风口和速度，是用最笨的办法，守最贵的信任。 对母婴品牌来说，实体渠道中最稀缺的资源，从来不是门店数量，而是“愿意认真卖一个品牌”的门店意愿。而摧毁这种意愿最直接的方式，就是串货和乱价。 坦图团队一直强调，价格体系就是婴配粉事业的“基石”，并且给出了一个在业内并不常见的责任划分： 价格管控95%的责任在厂家，不在门店，不在代理商，更不在串货商。 这句话的分量就在于，它承认了一个基本事实：渠道不会主动维护一个品牌的价格秩序， 除非品牌方自己把这件事当作生死线来守。 据了解，坦图在思慕尔时期就上了“天眼系统”，24小时追踪监控全国货物流向，对可疑的窜货门店进行筛选、监督和核查，对于非法渠道销售、恶意窜货的产品，坦图会通过追溯系统赋予红码，打上“本罐禁止销售”标签，以警示消费者。 曾有一名“推广女将”私发了一件奶粉给疑似串货商，查实后直接辞退。还有代理商在窜货被查后打电话求饶四十多分钟，哭诉说市场建起来不容易，愿意接受更大处罚，但仍被终止合作。 坦图总经理何康辉在跟笔者讲述这些事的时候很平静，或许因为整个团队已经想得足够清楚： 高压线就是高压线，谁碰谁走，能力再强再优秀也得走。 不过，在市场管控这件事上，坦图并不觉得已经做到头了， 还需要更努力，把要求提得更高，把市场管得更细，只有将窜货空间和低价翘客行为极限遏制，市场才能更健康，光明致优才有更长久的未来， 全国八九千家门店在前端经营时，没有后顾之忧。据悉，坦图已经推出了积分系统，接下来还将在市场管控上，陆续推出更多的优化措施。","image":"https://www.muyingqianyan.com/wp-content/uploads/2021/07/e6570c2e9d90b442ec5abe68c80669c.png"},{"title":"孩子王前三季度营收75亿元，门店加速下沉，利润增长仍承压","summary":"孩子王前三季度营收达75亿元，加速门店下沉战略，但利润增长面临压力。这反映了母婴零售市场对综合服务的需求，但利润承压提醒从业者需优化运营效率与成本控制，平衡扩张与盈利能力。10月28日，孩子王发布2026年第三季度报告。前三季度，公司实现营业收入75.06亿元，同比增长2.14%；归属于上市公司股东的净利润2.08亿元，同比下降0.40%。","source_id":"gnews_cn_retail","source_name":"搜狐网","source_url":"https://news.google.com/rss/search?q=%28%E6%AF%8D%E5%A9%B4%E5%BA%97%20OR%20%E6%AF%8D%E5%A9%B4%E8%BF%9E%E9%94%81%20OR%20%E5%AD%A9%E5%AD%90%E7%8E%8B%20OR%20%E7%88%B1%E5%A9%B4%E5%AE%A4%20OR%20%E6%AF%8D%E5%A9%B4%E6%B8%A0%E9%81%93%29%20%28%E5%A5%B6%E7%B2%89%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%85%B3%E5%BA%97%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.sohu.com/a/1094249051_120773210?scm=10001.325_13-325_13.0.0-0-0-0-0.5_1334","published_at":"2026-10-29T10:25:44+08:00","published_guessed":false,"fetched_at":"2026-10-29T11:02:59+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P0","score":9.6,"matched":["孩子王","营收"],"id":"514125654f70d5ed","title_zh":"孩子王前三季度营收75亿元，门店加速下沉，利润增长仍承压","summary_source":"llm","summary_kind":"brief","points":["孩子王营收75亿元"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月28日，孩子王发布2026年第三季度报告。前三季度，公司实现营业收入75.06亿元，同比增长2.14%；归属于上市公司股东的净利润2.08亿元，同比下降0.40%。其中，第三季度营收24.11亿元，同比下降1.08%；归母净利润3669.80万元，同比下降44.42%。据界面新闻报道，孩子王第三季度净利润出现明显下滑。 门店扩张是孩子王当前的重要策略。财报显示，前三季度公司新增加盟门店近180家。此前，公司披露，2026年上半年加盟精选店累计开业近300家，加盟业务收入达5.08亿元，同比增长超过200%。 下沉市场的机会，在于把母婴商品与服务送到更多家庭身边。围绕奶粉、纸尿裤、婴幼儿洗护等高频消费品，孩子王可以利用门店和会员体系，结合宝宝不同成长阶段开展精准推荐，并通过会员专属优惠、组合购及育儿服务带动复购。对加盟门店而言，统一选品、供应链和数字化运营，也有助于减少经营摸索成本。 与此同时，孩子王还在拓展母婴以外的业务。财报显示，丝域生物前三季度新增门店172家，其中中国港澳地区及海外市场新增6家。母婴零售与养发服务面向不同消费需求，能否形成稳定的协同效应，仍需观察后续经营表现。 扩张也带来现实压力。据东方财富网报道，孩子王第三季度净利润同比下降约四成，新店前期投入以及下沉市场加盟业务仍处于扩张期，是需要关注的经营因素。 对孩子王来说，挑战不只是开出更多门店，还要让新店尽快形成稳定销售。奶粉、纸尿裤等刚需商品有助于提高消费频次，但价格透明、品牌竞争激烈，单纯依靠打折促销可能挤压利润。公司可以通过优化商品组合、发展自有及差异化商品、提高会员复购率来改善经营质量，同时加强加盟门店的库存管理和单店盈利评估，避免规模增长快于经营效率提升。 接下来，孩子王需要同时回答两个问题：下沉加盟能否持续贡献收入，丝域生物能否在扩店后实现稳定回报。前三季度营收仍保持增长，但利润表现说明，扩张速度与盈利质量之间的平衡，将成为公司后续经营的重要考验。","image":"https://q7.itc.cn/images01/20261029/b7caa323e5924d228f934369c3d92b46.jpeg"},{"title":"送爸妈真实惠 伊利富硒高钙奶粉两大罐：秒杀价78.65元起","summary":"伊利推出富硒高钙奶粉促销活动，两大罐秒杀价78.65元起。此举旨在吸引消费者关注婴幼儿奶粉的营养价值，特别是针对中老年群体的健康需求。对从业者而言，这反映了市场对健康奶粉的持续关注，以及企业通过价格策略拓展消费群体的策略。伊利富硒高钙奶粉 700g*2 罐，日常售价为 200 元， 今日淘宝秒杀活动，到手价为 78.65 元起 。","source_id":"gnews_cn_brand_news","source_name":"驱动之家","source_url":"https://news.google.com/rss/search?q=%E5%A5%B6%E7%B2%89%20%28%E9%A3%9E%E9%B9%A4%20OR%20%E4%BC%8A%E5%88%A9%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E8%BE%BE%E8%83%BD%20OR%20%E9%9B%80%E5%B7%A2%20OR%20%E7%BE%8E%E8%B5%9E%E8%87%A3%20OR%20%E6%83%A0%E6%B0%8F%20OR%20%E9%9B%85%E5%9F%B9%20OR%20%E6%BE%B3%E4%BC%98%20OR%20%E8%B4%9D%E5%9B%A0%E7%BE%8E%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://news.mydrivers.com/1/1161/1161473.htm","published_at":"2026-10-29T10:13:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:11:23+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","质量安全"],"priority":"P0","score":12.8,"matched":["奶粉","伊利"],"id":"5d528b89518ce639","title_zh":"送爸妈真实惠 伊利富硒高钙奶粉两大罐：秒杀价78.65元起","summary_source":"llm","summary_kind":"brief","points":["伊利富硒高钙奶粉促销","两大罐秒杀价78.65元"],"points_source":"llm","translated":true,"link_resolved":true,"body":"伊利富硒高钙奶粉 700g*2 罐，日常售价为 200 元， 今日淘宝秒杀活动，到手价为 78.65 元起 。 下单方式：淘宝APP扫码下图二维码，点击详情页【淘宝秒杀】卡片，再去淘宝首页，点击淘宝秒杀，通过秒杀活动列表下单。 京东无门槛红包（每天可抽 3 次，至高 26888 元），领取方式： 点击领取 或 京东APP搜“每日福利981”。 淘宝无门槛红包（每天可抽 1 次，至高 26888 元），领取方式： 点此领取 或 淘宝APP搜“天降红包39933”。 天猫伊利奶粉旗舰店商品，正品保障，支持七天无理由退换，赠退货宝，请查看最新评价后再入手~","image":"https://img1.mydrivers.com/img/20261029/a796c5d89d0349c392a0ec7514c6b619.png"},{"title":"周末露营塞婴儿车，X5放倒座椅2070L，GLE后备厢差在哪","summary":"周末露营塞婴儿车，X5放倒座椅2070L，GLE后备厢差在哪 汽车之家","source_id":"gnews_cn_baby_category","source_name":"汽车之家","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://chejiahao.autohome.com.cn/info/26760443?reply=reply","published_at":"2026-10-29T09:51:39+08:00","published_guessed":false,"fetched_at":"2026-10-29T13:02:16+08:00","language":"zh","author":"","tags":["行业动态"],"priority":"P1","score":11.2,"matched":["婴儿","婴儿车"],"id":"a83a28f3ba87a349","link_resolved":true,"image":"https://www2.autoimg.cn/chejiahaodfs/g34/M09/63/B4/autohomecar__ChxpV2ripN2AeJuQAAKK4KmMUYc000.jpg"},{"title":"Bega Cheese Asks Queensland Dairy Farmers to Boost Milk Supply","summary":"贝加奶酪公司向澳大利亚昆士兰州奶农提出增加牛奶供应的要求。这一举动可能影响全球乳制品供应链，特别是依赖澳大利亚奶源的跨境母婴品牌需密切关注原奶供应变化，评估潜在的市场风险与成本波动。对行业从业者而言，澳大利亚奶源的变化直接关系到产品成本和供应稳定性，需及时调整采购策略以应对市场波动。","source_id":"gnews_en_nz_dairy","source_name":"www.marketscreener.com","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.marketscreener.com/news/bega-cheese-asks-queensland-dairy-farmers-to-boost-milk-supply-ce785cd3db80fe24","published_at":"2026-10-29T09:14:20+08:00","published_guessed":false,"fetched_at":"2026-10-29T11:03:08+08:00","language":"en","author":"","tags":["供应链","海外动态","质量安全"],"priority":"P0","score":11.2,"matched":["dairy","milk supply"],"id":"3fb42204bcb0ee3f","summary_source":"llm","summary_kind":"brief","points":["Bega Cheese要求增加牛奶供应","影响全球乳制品供应链"],"points_source":"llm","translated":true,"title_zh":"贝加奶酪要求昆士兰州奶农增加牛奶供应","link_resolved":true},{"title":"快60岁“苗连”满头白发抱奶瓶，小27岁央视妻悄悄领证！被嘲“爷孙恋”后，打了谁的脸","summary":"《我是特种兵》里骂新兵跟骂儿子似的“苗连”，现实里快60了，被路人拍到在小区门口抱个小娃娃，头发白一大片，卫衣旧得发毛，手里还拎个粉色保温奶瓶。网友先愣住：这咋像邻家爷爷接孙女放学？再一扒，娃娃是他亲闺女。老婆是央视十七套的出镜记者、制片人商文婷，硕士，去过日本交流，常年在田埂上拍基层片子，比他小27岁。俩人没办婚礼，2025年悄悄领证，回家吃顿家宴就算完事。","source_id":"gnews_cn_baby_category","source_name":"360娱乐","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://yule.360.com/detail/5271272","published_at":"2026-10-29T07:29:20+08:00","published_guessed":false,"fetched_at":"2026-10-29T13:02:16+08:00","language":"zh","author":"","tags":["行业动态"],"priority":"P1","score":4.8,"matched":["奶瓶"],"id":"3283771ad56a711d","summary_source":"extract","link_resolved":true,"body":"有个事挺炸的。《我是特种兵》里骂新兵跟骂儿子似的“苗连”，现实里快60了，被路人拍到在小区门口抱个小娃娃，头发白一大片，卫衣旧得发毛，手里还拎个粉色保温奶瓶。网友先愣住：这咋像邻家爷爷接孙女放学？再一扒，娃娃是他亲闺女。老婆是央视十七套的出镜记者、制片人商文婷，硕士，去过日本交流，常年在田埂上拍基层片子，比他小27岁。俩人没办婚礼，2025年悄悄领证，回家吃顿家宴就算完事。片场共事认识的——2023年公益电影《那年我们十八岁》，他主演，她管宣传制片。没人信这段能成。年龄差摆在那，网上阴阳怪气的不少：“老演员傍小才女”“晚年折腾”“图流量吧”。周惠林不回。商文婷也不回。后来有博主发图：菜市场里他提着一袋小白菜，她低头回工作微信，婴儿车放中间，像普通两口子。 周惠林是江苏连云港赣榆青口镇人。1983年进化工厂，三班倒，下班对着镜子练台词。1986年借调淮海歌舞团，1987考进江苏省戏剧学校，1990调南京市话剧团。上世纪90年代和同乡侯勇演小品《退票》，俩人挤小剧场后台吃盒饭，抠词抠到半夜。1994年央视《三国演义》他演毛玠，镜头没几句词。2002年《DA师》演坦克团团长包尔达夫，站坦克边腰板直。《我是特种兵》苗连凶，转头往被窝塞干粮。《利刃出鞘》范天雷鬼主意多。他不挑戏，几场戏也抠人物。拍军旅戏先扎部队，跟新兵出操、爬战术、滚泥地。女儿出生那天他在外地拍戏。接到电话当天跟组里请半月假，飞回来在产房外来回走，手心全是汗。孩子一哭，这演了半辈子硬汉的男人背过身，眼圈红了半天。之后他推掉长周期外景。冲奶粉拿温度计控40度，辅食火候写便签，换尿布从手忙脚乱到利索。有回带娃逛公园，全程抱怀里，逗孩子哼军歌调子，跟戏里教官判若两人。 商文婷没退圈，央视纪实报道还做，只是节奏慢了，家里辅食锅和采访本放一块。侯勇也是赣榆人，同岁。《大染坊》演主角，飞天金鹰拿遍。三段婚姻，第三任王瑞小二十岁，珠宝设计师，2017北京办婚礼闹过一阵。2024年57岁得儿子，出席活动状态年轻。周惠林头婚，侯勇三婚。一个藏名字在角色后头，一个把名字顶在片头上。被拍到同框那次，周惠林鬓角白，商文婷气质舒展，视觉差一眼就出来。有营销号写“爷孙恋”，底下有人怼：人家片场较真，一个抠本子一个抠镜头，你懂啥。周惠林现在主要排话剧、客串，不接大量影视剧。有次演出结束，观众凑过去合影，他怀里娃娃睡着了，他比了个“嘘”。商文婷在旁边拎着帆布包，包上别个“乡村振兴采访”徽章。网上传过“周惠林靠老婆上央视资源”，没实锤，也没人出来辟。也有人翻他早年话剧奖：江苏省五一工程奖、全国小品大赛个人表演奖。不炒绯闻那套，他不会。女儿百天没发朋友圈，亲戚说就煮了锅红鸡蛋。侯勇那边热搜是“硬汉升级奶爸”，周惠林这边是路人图先火。有剧粉说：苗连当年罚卧撑，现在半夜起来拍嗝，角色没白演，心软了。商文婷之前跑基层，蹲半天拍麦农，稿子不煽情。周惠林排练厅啃馒头看剧本，导演说“老周你别太轴”，他说“兵不是演出来的”。俩人家里没豪宅图流出，客厅婴儿垫占半间，茶几上话剧本压着育儿书。有回商文婷发工作图，背景虚掉那角，有人认出是周惠林在哄娃。没加文案，没挂情侣标。周惠林原单位南京话剧团老同事聊过：他中年才影视圈混出来，从不攀关系。《三国演义》那会儿住招待所，侯勇来找他，俩人分一根冰棍。现在侯勇儿子小，周惠林闺女小，同乡硬汉都晚当爹。拍《那年我们十八岁》时，商文婷嫌他一条过太板，他嫌她剪辑太花，后来片尾字幕俩人名字挨着。没吻戏，没绯闻镜头，就片场盒饭坐一张桌子。有记者问商文婷“差27岁怎么处”，她说“他背词比我都熟”。周惠林被问“老来得女累不累”，回“比爬战术轻松点”。被拍到抱娃买包子，老板娘认出来：这不是电视里那个连长嘛。他笑笑：连长下岗了，现在管喂奶。商文婷在旁边扫码付款，顺手把包子掰小块喂他。没摆拍，没通稿。网上吵“年龄差婚姻靠不靠谱”，他家灯晚上九点就灭了，婴儿哭一声他先醒。侯勇携妻儿走红毯，周惠林推婴儿车走菜场路。一个镜头前，一个镜头外。话剧《雷雨》他演周萍爹辈角色，谢幕抱花下去，兜里露出半个磨牙棒。舞美小伙说：老周以前进组先敬礼，现在进组先问“有没有母婴室”。商文婷做十七套农业选题，出差带吸奶器，他在外地戏份压缩到三天拍完赶回。没说爱不爱，就是孩子发烧他守到天亮，她改稿到三点，俩人分一碗粥。有八卦号编“周惠林靠央视老婆洗白资源”，底下剧迷列他九几年话剧票根：那时候她还在上学。也有人说商文婷“下嫁老演员”，她同事回：她最烦油嘴男的，周惠林片场较真像老教务主任，她对路数。女儿周岁没请圈里人，侯勇寄了套小军装，周惠林发张娃穿反的照片，没配字。商文婷妈晒过一条：外孙女抓周抓了支 周惠林快六十岁了才当上爹。这事挺意外，毕竟他以前在镜头前是个硬汉形象。他娶了个小他二十七岁的女人，对方是央视的记者周周。两人年龄差摆在那儿，刚在一起时大家都觉得挺新鲜，纷纷送祝福。可最近他们一块儿出现时，气氛似乎变了味。老张脸上的褶子深得像刀刻的一样，每一道都藏着年纪。他旁边的老伴儿站在那儿，身板挺得笔直，衣服穿得整整齐齐，看着一点没显老态。这两人凑在一块儿，岁数差着好几轮呢，外人看着都觉得稀罕。窗外的风刮过来，吹得窗帘角轻轻晃了一下。十六岁那年，也就是1983年，他进了县七二化工厂干活，身份是个普通工人。人生的转折往往就藏在那些看似不经意的瞬间里，周惠林的经历就是最典型的注脚。1986年，他去了市淮海歌舞团。那是借调，身份不算正式。他在那儿当演员，日子就这么混过去了。第二年，他考进了省戏剧学校。不是随便玩玩，是去学真本事。系统性的训练，把底子打得死死的。基本功这东西，急不得，得一点点磨出来。1990年，他进了南京市话剧团。职业演员这条路算是正式迈开了腿。刚进去的那阵子，没挑活儿。什么配角都接，龙套也演。","image":"https://p0.qhimg.com/t11508c75c8b114d663b12b0016.jpg"},{"title":"Fonterra Reports Strong FY26 Performance With $9.69 Milk Payout And $1B Protein Push","summary":"恒天然发布FY26财年业绩报告，表现强劲，每公斤乳酪分红9.69美元，并启动10亿美元蛋白质投资计划。这一分红水平创历史新高，显示出恒天然在乳制品市场回暖背景下的盈利能力。对于跨境母婴从业者而言，恒天然作为全球重要的乳业原料供应商，其分红增加和投资计划意味着上游原料供应的稳定性提升，且未来可能推出更多高蛋白产品。","source_id":"gnews_en_nz_dairy","source_name":"https://en.edairynews.com/","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://en.edairynews.com/fonterra-reports-strong-fy26-performance-with-9-69-milk-payout-and-1b-protein-push/","published_at":"2026-10-29T04:54:39+08:00","published_guessed":false,"fetched_at":"2026-10-29T06:55:42+08:00","language":"en","author":"","tags":["供应链"],"priority":"P0","score":16.0,"matched":["payout","milk payout","fonterra"],"id":"c186de2c4ee12f29","title_zh":"恒天然FY26财年表现强劲 每公斤乳酪分红9.69美元","summary_source":"llm","summary_kind":"brief","points":["恒天然FY26财年表现强劲","每公斤乳酪分红9.69美元","启动10亿美元蛋白质投资计划"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The cooperative posted an underlying operating profit for its continuing operations of $1.8 billion and a consolidated profit after tax of $1.2 billion, achieving a return on capital of 14.2 percent, well above its long-term target threshold of 10 to 12 percent. This financial outcome confirms that Fonterra has already restored underlying earnings to pre-divestment baselines, meeting its operational targets ahead of schedule following the divestiture of its global Consumer brands and the Mainland Group. The cooperative’s core Ingredients division served as the primary earnings engine, generating $1,293 million in operating profit on the back of favorable product mix optimization and surging global demand for functional milk proteins, while the Foodservice unit contributed $547 million in operating profit through volume and pricing expansion across key Asian and Middle Eastern corridors. Capitalizing on its refined business-to-business (B2B) focus, Fonterra announced an incremental capital commitment of $1 billion over the next three years to expand and upgrade its South Island industrial processing network. The multi-year capital deployment will accelerate advanced protein fractionation, expand high-spec drying infrastructure, and install modernized environmental systems to lower industrial emissions and improve factory water recycling. The new facilities, slated to become fully operational in 2029, are engineered to capture premium global margins for specialized nutritional ingredients while generating 50 to 60 permanent manufacturing jobs alongside substantial regional construction activity across the South Island. The cooperative’s specialized organic pool achieved a historic financial milestone, with the final organic milk price of $14.13 per kgMS marking a sixth consecutive year of payout increases, up from $12.35 per kgMS in FY25. Andrew Henderson, Fonterra’s General Manager for Organic, noted that export demand for certified grass-fed organic ingredients remains strong—particularly across the United States, where domestic organic milk availability has faced localized supply deficits. To service these high-margin overseas contracts, Fonterra is actively recruiting additional pasture-based dairy suppliers across both the North Island and South Island to expand its specialized organic and pasture-certified milk pools.","image":"https://en.edairynews.com/wp-content/uploads/2026/10/Fonterra-reports-strong-FY26-performance-with-9.69-milk-payout-and-1B-protein-push.jpeg"},{"title":"Nestlé targets two booming beverage trends with latest launch","summary":"雀巢扩展了Sanpellegrino零添加糖系列，推出草莓奶油口味。这款低卡产品融合了甜点风味和功能性，反映了市场对兼具享受与健康的高端软饮日益增长的需求。这一举措对从业者意味着，在追求健康的同时，创新口味和功能性是吸引消费者的关键。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/nestle-taps-two-booming-beverage-trends-with-sanpellegrino-strawberry-crema","published_at":"2026-10-29T00:47:49+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:54:40+08:00","language":"en","author":"Donna Eastlake","tags":["品牌动态","市场数据","质量安全"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/3YNAZB5DGFD47MFA6C6CTIN7BY.jpg?auth=acf671ad43d9dd6912940efe9dbcf6d11d24b22aa5473487bf3443ec2c6b211f&smart=true&width=1920&height=1080","score":4.8,"matched":["nestlé"],"id":"11955b536b079d23","title_zh":"雀巢推出新品，瞄准两大增长饮料趋势","summary_source":"llm","summary_kind":"brief","points":["推出草莓奶油口味零添加糖饮料","产品低卡且融合甜点风味和功能性","反映高端软饮市场对健康与享受结合的需求增长"],"points_source":"llm","translated":true},{"title":"Nestlé targets two booming beverage trends with latest launch","summary":"雀巢通过推出含草莓奶油的零添加糖桑培乐，将甜点风味与健康益处相结合，拓展零添加糖系列。这一举措反映了消费者对兼具享受与健康的高端软饮料需求增长。对跨境母婴行业从业者而言，雀巢的行动表明企业正积极迎合健康消费趋势，推动产品创新。","source_id":"foodnavigator_asia","source_name":"FoodNavigator-Asia","source_url":"https://www.foodnavigator-asia.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/nestle-taps-two-booming-beverage-trends-with-sanpellegrino-strawberry-crema","published_at":"2026-10-29T00:47:49+08:00","published_guessed":false,"fetched_at":"2026-10-29T01:42:37+08:00","language":"en","author":"Donna Eastlake","tags":["品牌动态","市场数据","质量安全"],"priority":"P1","image":"https://www.foodnavigator.com/resizer/v2/3YNAZB5DGFD47MFA6C6CTIN7BY.jpg?auth=acf671ad43d9dd6912940efe9dbcf6d11d24b22aa5473487bf3443ec2c6b211f&smart=true&width=1920&height=1080","score":4.8,"matched":["nestlé"],"id":"99d93592a89672eb","title_zh":"雀巢瞄准两大饮料趋势推出新品","summary_source":"llm","summary_kind":"brief","points":["零添加糖系列拓展","高端软饮料需求增长","健康消费趋势明显"],"points_source":"llm","translated":true},{"title":"Health Canada issues product recall notice for baby items sold at Walmart, Winners, HomeSense and Marshals","summary":"加拿大卫生部发布产品召回通知，召回Simmons Kozy和Nido品牌的婴儿睡篮和躺椅。这些产品在加拿大境内的Walmart、Winners、HomeSense、Marshalls及Amazon有售，因存在跌落风险。生产商报告称2022年1月至2026年9月期间在加拿大售出约25,088件受影响产品。截至10月19日，加拿大尚未收到任何伤害或事故报告。","source_id":"gnews_en_anz_recall","source_name":"Inside Halton","source_url":"https://news.google.com/rss/search?q=(FSANZ%20OR%20%22Food%20Standards%20Australia%20New%20Zealand%22%20OR%20%22Ministry%20for%20Primary%20Industries%22%20OR%20%22product%20recall%22)%20(recall%20OR%20%22food%20safety%22%20OR%20withdrawal)%20when:30d&hl=en-AU&gl=AU&ceid=AU:en","original_url":"https://www.insidehalton.com/news/canada-product-recall-baby-nest-loungers-winners/article_0be6fb91-7d24-5fcd-bfce-50395b29f0cd.html","published_at":"2026-10-29T00:09:00+08:00","published_guessed":false,"fetched_at":"2026-10-30T03:10:42+08:00","language":"en","author":"","tags":["质量安全"],"priority":"P1","score":4.8,"matched":["recall"],"id":"c4fa4895377f20cc","title_zh":"加拿大健康部召收回售于多家商家的婴儿用品","summary_source":"llm","summary_kind":"brief","points":["加拿大健康部召回首批婴儿用品","涉及沃尔玛等多家商家","跨境产品需符合各国标准"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Simmons Kozy and Nido baby nests and loungers sold at Winners, HomeSense, Marshalls and Walmart have been recalled. Health Canada issued a product recall notice for Simmons Kozy and Nido baby nests and loungers sold in Canada though Walmart, Winners, HomeSense, Marshalls and Amazon due to fall hazard. The company reported 25,088 units of the affected products were sold in Canada between January 2022 and September 2026. As of Oct. 19, the company hasn’t received any reports of injury or incidents in Canada. Simmons Kozy and Nido baby nests and loungers sold in Canada recalled. Health Canada tells parents and caregivers the safest place for a baby to sleep is on their back on a firm, flat surface intended for sleep. You can find more information on safe sleeping practices for infants online . You can report a food concern or complaint to CFIA online. Consumers can report any health or safety incidents related to the use of products by filling out a consumer product incident report form . To report a health or safety complaint with a cannabis product, fill out the cannabis reporting form online.","image":"https://bloximages.chicago2.vip.townnews.com/insidehalton.com/content/tncms/assets/v3/editorial/a/20/a20fb75c-0496-5828-bb6a-32f1aec822c0/6ae21a9960f39.image.jpg?crop=1662%2C873%2C0%2C187&resize=1200%2C630&order=crop%2Cresize"},{"title":"High&GoGo Story有机成长奶粉上市，为学龄期成长添动力，身高·眼脑·自护一步到位","summary":"High&GoGo品牌推出有机成长奶粉，专为3-14岁学龄期儿童设计，强调有机奶源和科学配方，注重身高、眼脑、自护三大维度的营养支持。该产品符合当前市场对有机、科学喂养的需求，对跨境母婴行业从业者意味着需关注高端有机奶粉市场趋势和消费者对产品功能的关注点。再搭配维生素A、铁、锌等协同营养，让孩子“看得清黑板、记得住知识”，学习效率自然提升。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/6/20261029/1869549.shtml","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T17:08:56+08:00","language":"zh","author":"","tags":["品牌动态","质量安全","市场数据"],"priority":"P1","score":9.6,"matched":["奶粉","上市"],"id":"1e16afed98f6eced","image":"https://objectem.oss-cn-shenzhen.aliyuncs.com/yhdoc/202610/29/20261029162554646991263.png","body":"10月底，源自丹麦的高端儿童营养品牌High&GoGo正式官宣新品——High&GoGo Story有机成长奶粉上市。这款专为3-14岁学龄期儿童定制的配方奶粉，以“有机奶源+科学配比”为核心，凭借“成长、眼脑、自护、吸收”四效合一的卓越配方，为中国家庭提供儿童成长营养的科学新方案。 3-14岁是儿童眼脑发育、骨骼发育、认知进阶、免疫力构建的“黄金窗口期”，营养供给的“精准度”与“天然性”直接影响成长质量。High&GoGo Story有机成长奶粉从源头把控品质，甄选北欧百年牧场有机奶源，遵循欧盟有机认证标准，拒绝化肥、农药与激素，确保每一滴奶的纯净安全。同时，依托“Clean Recipe”理念，将有机奶源中的天然活性营养精准保留，让“纯净”与“高效”完美融合，为孩子打下安全且有力的成长地基。 针对学龄期儿童“长不高、用眼多、注意力易分散、易生病”的家长痛点，High&GoGo Story有机儿童配方奶粉从身高、眼脑、自护力三大维度构建“协同营养矩阵”： 针对学龄期用眼过度、学习分心问题，配方科学注入“眼脑黄金”——叶黄素酯(犹如眼睛的“防晒伞”，过滤蓝光损伤)与牛磺酸(大脑的“加油站”，提升专注力与记忆力)。再搭配维生素A、铁、锌等协同营养，让孩子“看得清黑板、记得住知识”，学习效率自然提升。 配方特含BIO CBP(初乳碱性蛋白)，唤醒骨骼生长力;搭配原生天然牛乳钙与天然赖氨酸，为骨骼强健提供充足的营养支持，让孩子的成长更有底气。。此外，丹麦益生菌的加入进一步调节肠道菌群平衡，让营养“吸得进、留得住”，全链路助力身高突破。 免疫力是成长的“隐形盾牌”。High&GoGo Story有机成长奶粉以乳铁蛋白构建第一道防线，减少换季小状况，让孩子“少生病、活力足”，家长更安心。 除了核心功能，新品更打造“一站式营养补给”：欧洲12种维生素+6种矿物质覆盖成长所需，96%以上有机配方比例，既满足“有机纯净”需求，又实现“科学全面”补给;同时通过BB-12 & LGG益生菌+有机FOS益生元组合，调节肠道菌群、促进营养吸收，解决“补了白补”的吸收难题，让每一口奶粉都转化为成长动力。 “孩子的生长不是一场冲刺，而是一段需要耐心守护的旅程。”High&GoGo品牌负责人表示，“我们希望用一杯‘有机+科学’的奶粉，让家长放下焦虑，让孩子在身高、眼脑、自护力的协同发展中，自信探索世界。” 11月起，High&GoGo Story有机儿童成长奶粉将正式发售。从北欧牧场的纯净奶源，到实验室里的科学配比，再到孩子手中的每一杯温暖，High&GoGo正以“有机为底，科学为翼”，为学龄期儿童成长书写新的营养篇章，陪伴孩子们健康、快乐地迈向未来!","points":["High&GoGo有机成长奶粉上市","3-14岁学龄期儿童配方","有机奶源科学配比","身高眼脑自护营养支持"],"points_source":"llm","summary_source":"llm","title_zh":"High&GoGo Story有机成长奶粉上市，为学龄期成长添动力，身高·眼脑·自护一步到位","translated":true},{"title":"向善守护 强健未来——第四届强健宝宝成长峰会聚力儿童健康","summary":"10月23日，第四届强健宝宝成长峰会在宁夏银川举办。本次峰会由人民网-人民幼教主办，新西特承办，汇聚了宁夏民政公益领导、幼教平台代表、医学专家、行业大咖及全国母婴渠道代表。大会围绕儿童科学营养与公益实践展开交流，并启动了“塞上护苗”困境幼儿养育帮扶项目。活动旨在共探母婴行业高质量发展路径，推动儿童健康事业发展。","source_id":"baobei360","source_name":"中婴网","source_url":"https://www.baobei360.com/","original_url":"http://info.baobei360.com/info/2026-10-29/10028874.html","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T17:07:47+08:00","language":"zh","author":"","tags":["政策法规"],"priority":"P1","score":8.0,"matched":["宝宝","儿童"],"id":"0641a6711b3d25cd","image":"https://m.baobei360.com/upfile/news/202610/202610291532294399_400x300.jpg","body":"10月23日，由人民网-人民幼教主办，新西特承办的第四届强健宝宝成长峰会暨“塞上护苗”困境幼儿养育帮扶项目启动仪式在宁夏银川举办。本次峰会汇聚了宁夏民政公益领导、幼教平台代表、医学专家、行业大咖、全国母婴渠道代表，以及奥运冠军孙杨。大会围绕儿童科学营养、儿童公益实践等议题展开交流，共探母婴行业高质量发展路径。 峰会现场，宁夏回族自治区民政厅慈善事业促进处处长赵琨、人民网・人民幼教总经理李静先后致辞。致辞中聚焦儿童健康发展与公益帮扶，呼吁社会各界持续关注困境儿童成长，凝聚多方力量护航孩子科学养育、强健成长，为本次峰会定下专业向善的主基调。 峰会邀请多位行业权威专家带来主题分享。北京大学第一医院杨艳玲教授围绕《脑健康与营养代谢》展开分享，解读儿童大脑发育关键周期，为渠道从业者与广大家长普及儿童认知成长相关科学知识。 西北妇女儿童医院李占魁聚焦婴幼儿牛奶蛋白过敏议题，拆解宝宝过敏各类预警信号，分享婴幼儿过敏的科学干预与养育方案。 乳业专家宋亮发表《营养品：母婴行业下一个主战场与品牌制胜之道》主题演讲。他指出营养品时代已经到来，结合当前母婴行业新格局，剖析营养品赛道增长机遇、竞争挑战以及品牌突围方向，解读人口新周期下行业发展趋势，为在场渠道伙伴提供务实的行业参考。 新西特总裁宋海华阐述品牌“改善中国宝宝体质”的初心使命，回顾品牌深耕乳铁蛋白、DHA等科学营养领域的积淀，矢志把科学营养理念送入万千普通母婴家庭，守护孩子健康成长。他始终聚焦儿童营养健康，希望用专业营养力量，为更多宝宝筑牢成长根基。宋总表示选择孙杨为品牌代言人，正是看中冠军身上拼搏坚守、恪守高标准的精神内核，将这份严谨与坚持融入品牌理念，依托冠军榜样力量，向广大家长传递科学养育的理念，守护每一位孩子的强健未来。 孙杨登台带来《强大，不止于天赋》主题分享，结合自身竞技生涯，诠释坚持、自律、热爱对于成长的重要意义。他将竞技体育的成长逻辑延伸至儿童养育，提出孩子强健体质离不开长期科学营养的浇灌，宝宝自护力养成没有捷径，需要日复一日的呵护。 儿童的健康成长，是民生关切，也是一份温暖的时代使命。宁夏困境幼儿的现实难题，需要更多爱心力量接力守护。峰会现场新西特携手各界代表正式启动“塞上护苗” 困境幼儿养育帮扶项目。 据了解，新西特早在2017年便已在宁夏红寺堡落地助学帮扶行动。在今年9月中华慈善日，品牌捐赠价值101万元爱心物资，用于帮扶困境儿童。本次峰会现场，相关领导、专家为到场的红寺堡受助儿童发放爱心礼包。宁夏慈善总会副会长彭荣军现场发言号召更多社会力量参与困境儿童关爱事业。 本届峰会虽已落幕，新西特表示，未来将继续坚守“改善中国宝宝体质”的品牌初心，联动专家、渠道与社会各界力量，兼顾产品创新与公益践行，守护更多中国宝宝健康强健成长。","points":["第四届强健宝宝成长峰会举办","启动“塞上护苗”困境幼儿帮扶项目","汇聚行业专家与渠道代表","聚焦儿童科学营养与公益实践"],"points_source":"llm","summary_source":"llm","summary_kind":"brief","title_zh":"向善守护 强健未来——第四届强健宝宝成长峰会聚力儿童健康","translated":true},{"title":"爸爸打呼噜，会不会吵坏宝宝睡眠？","summary":"爸爸打呼噜可能影响宝宝睡眠质量，尤其对于新生儿和早产儿。婴儿睡眠浅，对声音敏感，爸爸的鼾声可能导致他们频繁醒来，影响生长发育。家长需关注宝宝睡眠状况，必要时调整睡姿或分房睡。对于跨境母婴从业者，了解不同文化背景下的睡眠习惯差异，能更好地为消费者提供科学育儿建议，促进产品销售和服务升级。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/1/20261029/1869550.shtml","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T19:02:41+08:00","language":"zh","author":"","tags":["质量安全","海外动态"],"priority":"P1","score":4.8,"matched":["宝宝"],"id":"1a185d30f94ed47e","title_zh":"爸爸打呼噜，会不会吵坏宝宝睡眠？","summary_source":"llm","summary_kind":"brief","points":["打呼噜影响婴儿睡眠","新生儿对声音敏感","需关注宝宝睡眠质量","调整睡姿或分房睡"],"points_source":"llm","translated":true,"body":"很多宝妈宝爸夜里都会被同一个问题困扰：爸爸呼噜声一响，宝宝会不会被吵醒?会不会影响睡眠质量?结论是：有可能吵到，但不等于一定会“吵坏”。关键要看呼噜声的大小、变化、持续时间，以及宝宝自己的反应。 宝宝的睡眠结构和成人不同，浅睡眠比例更高，外界声音突然变大、变尖、断断续续时，更容易惊醒、翻动或哭闹。呼噜声往往忽高忽低，还可能伴随呼吸暂停后的突然声响，对宝宝来说并不是稳定的“背景音”。所以，爸爸打呼噜确实可能增加宝宝夜醒、入睡困难或浅睡增多的情况。但宝宝也有一定适应能力，如果声音较低、隔得较远、持续时间稳定，影响可能相对小一些。 判断会不会影响，不能只听呼噜声大不大，更要看宝宝表现。如果宝宝夜间惊醒增多、夜醒次数明显增加、入睡变难、白天烦躁或精神差，就要考虑睡眠环境中的呼噜声因素。调整睡眠安排后，宝宝睡眠变稳，说明关系可能较大。如果宝宝睡眠和白天状态都正常，不必过度焦虑，但仍建议减少长期大声暴露。 减少影响可以从环境和健康两方面做。宝宝应睡独立小床，保持仰卧、床面平整，同房不同床;让宝宝与打呼噜的大人保持距离，必要时分房或隔墙睡;可以先哄睡宝宝，再让大人入睡;不建议给宝宝戴耳塞;白噪音音量要低，不要用白噪音去掩盖呼噜声。爸爸方面，睡前少饮酒，尽量侧睡，控制体重，处理鼻塞;如果打鼾声音很大、伴有憋气、白天嗜睡，建议就医评估睡眠呼吸暂停。 总之，爸爸打呼噜可能干扰宝宝睡眠，但多数情况可以通过调整睡眠位置和改善打鼾来降低影响。宝妈宝爸既要重视，也不必恐慌。多观察宝宝夜醒和白天状态，必要时咨询儿科或耳鼻喉科医生。安全睡眠永远是第一位。"},{"title":"宝宝夜里哭闹是什么原因？先排查这一点","summary":"许多宝妈宝爸面临宝宝夜里哭闹的问题。文章指出，在给哭闹贴上“缺钙”“被吓到”或“故意闹人”的标签前，应先排查宝宝的基本生理需求和安全睡眠环境。常见原因包括饥饿、尿布湿、温度不适、衣物或床品不舒服等。家长需按顺序检查尿布、后颈和手脚温度、衣物松紧、床面平整度，并确保空气流通。安全睡眠环境要求宝宝仰卧睡在独立小床上，周围不放枕头、厚被、毛绒玩具等。作息和环境因素如白天小睡不足、睡前玩得太兴奋、光线过亮、声音突然变大等也会影响夜间睡眠。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/2/20261029/1869551.shtml","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:42+08:00","language":"zh","author":"","tags":["质量安全","品牌动态"],"priority":"P1","score":4.8,"matched":["宝宝"],"id":"7200d30af024a46c","body":"宝宝夜里哭闹，是很多宝妈宝爸都会遇到的事。先别急着给哭闹贴上“缺钙”“被吓到”或“故意闹人”的标签，也不要一哭就喂奶或长时间摇晃。第一步应先排查：宝宝的基本生理需求和安全睡眠环境有没有问题。 先看基本需求。宝宝夜里哭闹，常见原因是饿了、尿布湿了、太热或太冷、衣服或床品不舒服。家长可以按顺序快速检查：尿布是否湿脏，后颈和手脚温度是否合适，衣物是否过紧，床面是否有硌人的东西。不要只看手脚凉就加被子，后颈温热、不出汗通常更可靠。若宝宝有鼻塞、呼吸不畅，也可能睡不安稳，需要先清理鼻腔、保持空气流通。还要看睡眠环境是否安全舒适：宝宝应仰卧睡在独立小床上，床面平整，周围不放枕头、厚被、毛绒玩具和松散物品，坚持同房不同床。安全睡眠永远是第一位。 再排查作息和环境。宝宝过度疲劳时反而更难入睡，夜里也容易频繁哭闹。白天小睡不足、入睡时间太晚、睡前玩得太兴奋，都可能影响夜间睡眠。卧室光线太亮、声音突然变大、温度不适、睡前流程混乱，也会让宝宝睡不踏实。家长可以固定睡前流程，降低光线和声音刺激，让宝宝在相对稳定的环境里入睡。 之后再看身体和情绪因素。出牙不适、肠胀气、湿疹瘙痒、鼻塞、分离焦虑、睡眠倒退等，都可能让宝宝夜里哭闹。处理时要先安抚，再观察，不要盲目用药，也不要用偏方。哭闹时可以先轻拍、低声安抚，检查基本需求，避免一哭就喂导致过度喂养，也避免剧烈摇晃。若宝宝只是短暂翻动或哼唧，可以先观察片刻，不一定马上抱起。 还要记住就医信号。如果宝宝出现发热、呼吸费力、频繁呕吐、精神差、哭声尖或弱、拒奶、尿量明显减少等情况，应及时就医。多数夜里哭闹通过排查需求、调整作息和改善睡眠环境可以缓解。家长不必过度焦虑，但要用顺序排查代替胡乱猜测。先排查基本需求和安全睡眠环境，再找其他原因，往往更稳妥。","summary_source":"llm","title_zh":"宝宝夜里哭闹是什么原因？先排查这一点","points":["排查基本生理需求","注意安全睡眠环境","关注身体和情绪因素"],"points_source":"llm","translated":true},{"title":"Danone joins Nestlé, Coca-Cola in revising recycling labels after EU greenwashing probe","summary":"在欧盟针对“漂绿”行为的调查背景下，达能、雀巢和可口可乐等食品饮料巨头正修订其回收标签。此举旨在明确标注瓶身回收材料的比例并避免误导性营销，体现了行业巨头对环保合规及消费者透明度要求的重视，对跨境出口产品的标签合规具有警示意义。对行业从业者而言，需关注欧盟环保法规变化，确保产品标签符合最新要求，避免合规风险。","source_id":"fooddive","source_name":"Food Dive","source_url":"https://www.fooddive.com/feeds/news/","original_url":"https://www.fooddive.com/news/danone-joins-nestle-coca-cola-revises-recycling-labels-after-eu-greenwashing-complaint/872777","published_at":"2026-10-28T22:18:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T22:44:57+08:00","language":"en","author":"Zoya Mirza","tags":["政策法规","质量安全","海外动态"],"priority":"P1","image":"https://imgproxy.divecdn.com/SFoJ6ZtSs8AMGzArpdRaKY5NZKQtnhTOH2Y7q_SNlv0/g:ce/rs:fill:1600:900:1/Z3M6Ly9kaXZlc2l0ZS1zdG9yYWdlL2RpdmVpbWFnZS9ldmlhbi5qcGc=.webp","score":9.6,"matched":["danone","nestlé"],"id":"f2376a5fff873fda","title_zh":"达能加入雀巢与可口可乐行列修订回收标签","summary_source":"llm","summary_kind":"brief","points":["达能修订回收标签应对欧盟调查","明确标注瓶身回收材料比例","避免误导性营销 claims"],"points_source":"llm","translated":true},{"title":"Dairy Farmers of America closes in on Nestlé in global dairy rankings","summary":"美国乳农合作社DFA通过一系列收购行动，正在重新塑造全球乳业排名，预计其销售额将超越雀巢。这一变化凸显了全球乳业竞争格局的动态调整，并购整合成为行业巨头提升市场地位的重要手段。对跨境母婴行业从业者而言，这意味着需要密切关注全球乳业的竞争态势，理解并购整合可能对市场格局及供应链带来的影响，以便及时调整策略以适应变化的市场环境。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/dairy-ma-reshapes-global-rankings-and-growth-strategies","published_at":"2026-10-28T21:44:27+08:00","published_guessed":false,"fetched_at":"2026-10-28T22:44:57+08:00","language":"en","author":"Timothy Inklebarger","tags":["市场数据","品牌动态","供应链"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/MANMYZOHVZCMVGAG7TEY5U4NTI.jpg?auth=b245991f1d2c2796ebe5eb60977f65c8d27a7c896642792fe663d2d0d2b0ebcf&smart=true&width=2121&height=1414","score":9.6,"matched":["nestlé","dairy"],"id":"4f58f2280bc22ba0","title_zh":"美国乳农合作社全球排名逼近雀巢","summary_source":"llm","summary_kind":"brief","points":["美国乳农合作社通过收购重塑排名","有望在销售额上超越雀巢","全球乳业竞争格局正在发生变化"],"points_source":"llm","translated":true},{"title":"Dairy Farmers of America closes in on Nestlé in global dairy rankings","summary":"美国乳农合作社DFA通过收购重塑全球乳业排名，有望在销售额上超越雀巢。这一动态表明全球乳业竞争格局正在发生变化，并购整合成为行业巨头提升排名的重要手段。对跨境母婴行业从业者而言，需关注全球乳业竞争态势，理解并购整合对市场格局及供应链可能产生的影响。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/dairy-ma-reshapes-global-rankings-and-growth-strategies","published_at":"2026-10-28T21:44:27+08:00","published_guessed":false,"fetched_at":"2026-10-29T09:17:46+08:00","language":"en","author":"Timothy Inklebarger","tags":["市场数据","政策法规","品牌动态"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/MANMYZOHVZCMVGAG7TEY5U4NTI.jpg?auth=b245991f1d2c2796ebe5eb60977f65c8d27a7c896642792fe663d2d0d2b0ebcf&smart=true&width=2121&height=1414","score":9.6,"matched":["nestlé","dairy"],"id":"281895efb1bc9a51","title_zh":"美国乳农合作社DFA有望超越雀巢全球排名","translated":true,"summary_source":"llm","summary_kind":"brief","points":["美国乳农合作社DFA通过收购提升排名","全球乳业竞争格局变化","并购整合成为重要手段","关注全球乳业竞争态势"],"points_source":"llm"},{"title":"Dairy Farmers of America closes in on Nestlé in global dairy rankings","summary":"RaboResearch指出，美国奶农合作社正接近雀巢，有望在乳业全球销售排名中超越雀巢。这一变化主要受收购活动重塑全球乳业20强格局的影响，显示出北美乳业巨头在整合与扩张方面的积极态势。对跨境母婴行业从业者而言，需关注全球乳业竞争态势，理解并购整合对市场格局及供应链可能产生的影响。","source_id":"foodnavigator_asia","source_name":"FoodNavigator-Asia","source_url":"https://www.foodnavigator-asia.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/dairy-ma-reshapes-global-rankings-and-growth-strategies","published_at":"2026-10-28T21:44:27+08:00","published_guessed":false,"fetched_at":"2026-10-30T06:56:27+08:00","language":"en","author":"Timothy Inklebarger","tags":["市场数据","政策法规","品牌动态"],"priority":"P1","image":"https://www.foodnavigator.com/resizer/v2/MANMYZOHVZCMVGAG7TEY5U4NTI.jpg?auth=b245991f1d2c2796ebe5eb60977f65c8d27a7c896642792fe663d2d0d2b0ebcf&smart=true&width=2121&height=1414","score":9.6,"matched":["nestlé","dairy"],"id":"b428beb2e50b8c95","title_zh":"美国奶农合作社接近雀巢全球排名","summary_source":"llm","summary_kind":"brief","points":["美国奶农合作社接近雀巢","有望在乳业全球销售排名中超越雀巢","收购活动重塑全球乳业20强格局"],"points_source":"llm","translated":true},{"title":"今天，达能最新季报出炉：亚太区前三季度增长最快，爱他美奶粉双11渠道进货积极","summary":"达能最新季报显示，亚太区前三季度增长最快，其中爱他美奶粉在双11期间渠道进货积极。这一数据反映出中国等亚太市场对婴幼儿奶粉的需求持续增长，对跨境奶粉品牌和渠道商意味着市场潜力巨大，需持续优化渠道策略以抓住增长机遇。最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。回顾前三季度，达能销售额同比增长3.6%，亚太市场以4.9%增幅成为增长最高的大区，且主要由销量/组合拉动。","source_id":"gnews_cn_ecom","source_name":"小食代","source_url":"https://news.google.com/rss/search?q=%E5%A5%B6%E7%B2%89%20%28%E7%9B%B4%E6%92%AD%20OR%20%E6%8A%96%E9%9F%B3%20OR%20%E5%A4%A9%E7%8C%AB%20OR%20%E4%BA%AC%E4%B8%9C%20OR%20%E5%8F%8C11%20OR%20%E6%8B%BC%E5%A4%9A%E5%A4%9A%29%20%28%E9%94%80%E9%87%8F%20OR%20%E5%A2%9E%E9%95%BF%20OR%20%E4%BB%B7%E6%A0%BC%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.foodinc.com.cn/2026/10/28/20261028002/","published_at":"2026-10-28T21:42:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:39:46+08:00","language":"zh","author":"","tags":["市场数据","跨境电商","品牌动态"],"priority":"P0","score":20.8,"matched":["奶粉","达能","爱他美","渠道"],"id":"cd68197b09ca2665","title_zh":"达能亚太区增长强劲，爱他美双11渠道活跃","summary_source":"llm","summary_kind":"brief","points":["达能亚太区增长最快","爱他美双11渠道进货积极","反映亚太市场需求增长","跨境奶粉品牌需优化渠道策略"],"points_source":"llm","translated":true,"link_resolved":true,"body":"最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。回顾前三季度，达能销售额同比增长3.6%，亚太市场以4.9%增幅成为增长最高的大区，且主要由销量/组合拉动。 财报显示，今年第三季度，达能销售额为72.33亿欧元（约合人民币536亿元），同比增长4%，其中销量/组合增长0.4%，定价增长3.6%。今年前三季度，该集团销售额为211.76亿欧元（约合人民币1570亿元），同比增长3.6%，其中销量/组合增长1.3%。 达能首席执行官盛睿安（Antoine de Saint-Affrique）表示，达能又一季的强劲表现反映出 全品类和地区的广泛增长势头 。该集团的多引擎增长模式继续展现出韧性，这得益于以健康为核心的产品优势和与市场趋势的契合度。 “从高蛋白、肠道健康到医学营养品，我们优势产品的需求在全球范围内保持强劲。”盛睿安说。 他又指，在依然波动的环境中，达能重申全年业绩指引不变。2026年，该集团预计销售额同比增长在3%～5%之间，经常性营业利润增速将高于销售额增长，两者均与达能中期目标保持一致。 小食代留意到，如何控制成本通胀在会上也是受关注话题之一。前几年，不少跨国快消企业因为通胀提价而遭遇销量下滑，处理好成本消化与品牌需求维持的矛盾成为共同课题。 据Esser透露，第三季度，油价及相关商品价格指数持续高企。 基于以往通胀周期经验，达能当季采取了主动且审慎的定价行动，按品类、按市场有选择地执行 ，始终将消费者置于决策的中心，平衡好可负担性、产品竞争力和可持续价值创造。 “ 我们尽早且果断地采取行动而不是拖延，以避免后续更大幅度的涨价。 ” Esser说，“油价持续高企，意味着我们通过大宗商品常规对冲所受到的保护越来越少，因此通胀压力正在逐季增加。” 他表示，面对这种情况，达能除了采取定价措施，也正大力提升生产力和效率。围绕销量/组合、定价和生产力的“组合拳”，将是达能在今年剩余时间和2027年推动利润率朝正确方向发展的关键。 财报显示，今年第三季度，达能亚太市场销售额同比增长 3.6% 至 16.46 亿欧元（约合人民币 122 亿元）。其中，销量 / 组合增长 1.7 % ，定价增长 1.9% 。前三季度 ，该大区 实现销售收入 47.62亿欧元，同比增长4.9% ，其中 销量 / 组合增长 3 .7 % 。 当季，达能亚太的专业特殊营养销售额同比增长7.9%至10.96亿欧元。达能首席财务官Juergen Esser表示， 专业特殊营养最重要的市场是中国。当季，中国业务对该品类业绩做出了超额贡献（注：即对增长贡献的占比超过自身规模占比）。 婴幼儿奶粉品牌爱他美保持良好表现，ESSENSIS熠系列仍是最大贡献者。 渠道在双11对达能奶粉的进货也非常积极 ，这是潜在需求强劲的一个信号。 “虽然（婴幼儿奶粉）品类增长疲软，但我们的表现优于市场，ESSENSIS熠系列做得非常好，销量/组合销售呈现积极态势。” Esser说。 他又指出，医学营养品也保持增长， 作为传统产品的医院肠内管饲继续增长。同时，达能也正大力投资院外业务，包括在药店销售的口服非处方营养品。 新业务虽然尚未真正规模化，但正加速发展，反响令人振奋。 再来看看脉动所在的饮料与饮用水。第三季度，达能饮用水和饮料业务实现销售收入13.70亿欧元，同比增长3.6%。","image":"https://www.foodinc.com.cn/wp-content/uploads/2026/10/c1ce4011396fd5707b8de31ef9fee156.jpg"},{"title":"今天，达能最新季报出炉：亚太区前三季度增长最快，爱他美奶粉双11渠道进货积极","summary":"达能第三季度销售额同比增长4%，亚太区增幅达4.9%，主要得益于销量和组合增长。亚太区前三季度销售额同比增长3.6%，其中中国对专业特殊营养品类业绩贡献突出。爱他美奶粉在双11期间渠道进货积极，ESSENSIS熠系列表现优异。达能正通过调整定价、提升生产效率等措施应对通胀压力，预计2026年销售额同比增长3%-5%。最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。","source_id":"gnews_cn_brands","source_name":"小食代","source_url":"https://news.google.com/rss/search?q=(%E9%9B%80%E5%B7%A2%20OR%20%E8%BE%BE%E8%83%BD%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E4%BC%8A%E5%88%A9%20OR%20%E6%BE%B3%E4%BC%98)%20(%E5%A5%B6%E7%B2%89%20OR%20%E5%A9%B4%E9%85%8D)%20-%E8%82%A1%E7%A5%A8&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.foodinc.com.cn/2026/10/28/20261028002/","published_at":"2026-10-28T21:42:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:39:14+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":20.8,"matched":["奶粉","达能","爱他美","渠道"],"id":"e85eba0d36d837a6","title_zh":"达能亚太区前三季度增长最快，爱他美奶粉双11渠道进货积极","summary_source":"llm","summary_kind":"brief","points":["达能亚太区增长快","爱他美双11进货积极","跨境电商渠道表现好"],"points_source":"llm","translated":true,"link_resolved":true,"body":"最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。回顾前三季度，达能销售额同比增长3.6%，亚太市场以4.9%增幅成为增长最高的大区，且主要由销量/组合拉动。 财报显示，今年第三季度，达能销售额为72.33亿欧元（约合人民币536亿元），同比增长4%，其中销量/组合增长0.4%，定价增长3.6%。今年前三季度，该集团销售额为211.76亿欧元（约合人民币1570亿元），同比增长3.6%，其中销量/组合增长1.3%。 达能首席执行官盛睿安（Antoine de Saint-Affrique）表示，达能又一季的强劲表现反映出 全品类和地区的广泛增长势头 。该集团的多引擎增长模式继续展现出韧性，这得益于以健康为核心的产品优势和与市场趋势的契合度。 “从高蛋白、肠道健康到医学营养品，我们优势产品的需求在全球范围内保持强劲。”盛睿安说。 他又指，在依然波动的环境中，达能重申全年业绩指引不变。2026年，该集团预计销售额同比增长在3%～5%之间，经常性营业利润增速将高于销售额增长，两者均与达能中期目标保持一致。 小食代留意到，如何控制成本通胀在会上也是受关注话题之一。前几年，不少跨国快消企业因为通胀提价而遭遇销量下滑，处理好成本消化与品牌需求维持的矛盾成为共同课题。 据Esser透露，第三季度，油价及相关商品价格指数持续高企。 基于以往通胀周期经验，达能当季采取了主动且审慎的定价行动，按品类、按市场有选择地执行 ，始终将消费者置于决策的中心，平衡好可负担性、产品竞争力和可持续价值创造。 “ 我们尽早且果断地采取行动而不是拖延，以避免后续更大幅度的涨价。 ” Esser说，“油价持续高企，意味着我们通过大宗商品常规对冲所受到的保护越来越少，因此通胀压力正在逐季增加。” 他表示，面对这种情况，达能除了采取定价措施，也正大力提升生产力和效率。围绕销量/组合、定价和生产力的“组合拳”，将是达能在今年剩余时间和2027年推动利润率朝正确方向发展的关键。 财报显示，今年第三季度，达能亚太市场销售额同比增长 3.6% 至 16.46 亿欧元（约合人民币 122 亿元）。其中，销量 / 组合增长 1.7 % ，定价增长 1.9% 。前三季度 ，该大区 实现销售收入 47.62亿欧元，同比增长4.9% ，其中 销量 / 组合增长 3 .7 % 。 当季，达能亚太的专业特殊营养销售额同比增长7.9%至10.96亿欧元。达能首席财务官Juergen Esser表示， 专业特殊营养最重要的市场是中国。当季，中国业务对该品类业绩做出了超额贡献（注：即对增长贡献的占比超过自身规模占比）。 婴幼儿奶粉品牌爱他美保持良好表现，ESSENSIS熠系列仍是最大贡献者。 渠道在双11对达能奶粉的进货也非常积极 ，这是潜在需求强劲的一个信号。 “虽然（婴幼儿奶粉）品类增长疲软，但我们的表现优于市场，ESSENSIS熠系列做得非常好，销量/组合销售呈现积极态势。” Esser说。 他又指出，医学营养品也保持增长， 作为传统产品的医院肠内管饲继续增长。同时，达能也正大力投资院外业务，包括在药店销售的口服非处方营养品。 新业务虽然尚未真正规模化，但正加速发展，反响令人振奋。 再来看看脉动所在的饮料与饮用水。第三季度，达能饮用水和饮料业务实现销售收入13.70亿欧元，同比增长3.6%。","image":"https://www.foodinc.com.cn/wp-content/uploads/2026/10/c1ce4011396fd5707b8de31ef9fee156.jpg"},{"title":"Danone delivers a strong Q3 performance","summary":"达能第三季度业绩增长主要得益于高蛋白、肠道健康及医学营养产品在关键全球市场的强劲需求。该业绩表现反映了乳业高端化与功能性产品趋势的延续，对行业从业者具有积极的参考价值。这一趋势表明消费者对高端和功能性乳制品的需求持续增长，为行业产品研发和市场布局提供了方向。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/strong-q3-driven-by-nutrition-trends","published_at":"2026-10-28T21:00:58+08:00","published_guessed":false,"fetched_at":"2026-10-28T21:16:37+08:00","language":"en","author":"","tags":["品牌动态","质量安全","市场数据"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/TFBLXX44NZHZXJ43H2ABZDVEP4.jpg?auth=789d53c44e9f407e06b1d9feae8073f368896c7f45d75e02f5d2a41790de038a&smart=true&width=2000&height=1500","score":4.8,"matched":["danone"],"id":"55a6b3475e71ed6f","title_zh":"达能第三季度业绩强劲","summary_source":"llm","summary_kind":"brief","points":["高蛋白及医学营养产品需求强劲","肠道健康品类增长显著","全球市场表现亮眼"],"points_source":"llm","translated":true},{"title":"Nestle USA names top trends for 2027","summary":"雀巢美国预测2027年蛋白质趋势将持续演变，果味风味产品将更受消费者青睐。这一趋势预测为行业产品研发与市场布局提供了前瞻性指引，有助于企业把握未来消费方向。对从业者而言，需关注蛋白质趋势演变和果味产品市场变化，及时调整产品策略以适应未来消费需求。","source_id":"foodbusinessnews","source_name":"Food Business News","source_url":"https://www.foodbusinessnews.net/rss/articles","original_url":"https://www.foodbusinessnews.net/articles/31255-nestle-usa-names-top-trends-for-2027","published_at":"2026-10-28T19:22:15+08:00","published_guessed":false,"fetched_at":"2026-10-28T21:16:38+08:00","language":"en","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","image":"https://www.foodbusinessnews.net/ext/resources/2026/10/28/nestle-trends-lead.webp?t=1793190418","score":4.8,"matched":["nestle"],"id":"d3bcd784d769e2d7","title_zh":"雀巢美国发布2027年趋势预测","summary_source":"llm","summary_kind":"brief","points":["蛋白质趋势将持续演变","果味风味产品需求上升","2027年趋势预测发布"],"points_source":"llm","translated":true},{"title":"孩子王三季度归母净利润3669.80万元 同比下降44.42%","summary":"孩子王作为母婴零售行业的知名企业，其三季度业绩出现明显下滑，归母净利润同比下降44.42%。这一数据反映出母婴零售市场面临消费疲软和竞争加剧的挑战。对行业从业者而言，孩子王的经营状况警示着市场的不确定性，需要加强成本控制和渠道创新以应对变化。","source_id":"gnews_cn_retail","source_name":"观点网","source_url":"https://news.google.com/rss/search?q=%28%E6%AF%8D%E5%A9%B4%E5%BA%97%20OR%20%E6%AF%8D%E5%A9%B4%E8%BF%9E%E9%94%81%20OR%20%E5%AD%A9%E5%AD%90%E7%8E%8B%20OR%20%E7%88%B1%E5%A9%B4%E5%AE%A4%20OR%20%E6%AF%8D%E5%A9%B4%E6%B8%A0%E9%81%93%29%20%28%E5%A5%B6%E7%B2%89%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%85%B3%E5%BA%97%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.guandian.cn/article/20261028/619654.html","published_at":"2026-10-28T17:56:21+08:00","published_guessed":false,"fetched_at":"2026-10-28T21:17:26+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","跨境电商"],"priority":"P0","score":6.4,"matched":["孩子王"],"id":"9bbc919ac34eed71","title_zh":"孩子王三季度归母净利润3669.80万元 同比下降44.42%","summary_source":"llm","summary_kind":"brief","translated":true,"link_resolved":true,"body":"观点网讯： 孩子王数智科技股份有限公司发布2026年第三季度报告，前三季度公司营业收入75.06亿元，同比增长2.14%；归属于上市公司股东的净利润2.08亿元，同比下降0.40%。 第三季度单季，公司营业收入24.11亿元，同比下降1.08%；归母净利润3669.80万元，同比下降44.42%；扣除非经常性损益的净利润2550.58万元，同比下降37.93%。 盈利指标方面，公司第三季度基本每股收益0.0292元/股，同比下降44.17%；加权平均净资产收益率0.83%，同比减少0.81个百分点。 前三季度，公司扣非净利润1.50亿元，同比下降3.90%；基本每股收益0.1659元/股，同比下降0.06%；加权平均净资产收益率4.81%，同比减少0.20个百分点；经营活动产生的现金流量净额6.95亿元，同比下降36.46%。 报告期末，公司总资产106.13亿元，比上年度末下降1.48%；归属于上市公司股东的所有者权益44.21亿元，比上年度末增长3.93%。 非经常性损益方面，前三季度公司计入当期损益的政府补助2216.90万元，系政府拨付的各项补助金；持有及处置金融资产相关损益4767.54万元，系公司为提高资金使用效率购买低风险理财产品；非流动性资产处置损益1129.69万元，主要系本期处置资产形成的收益。 公告显示，第三季度财务会计报告未经审计，公司无需追溯调整或重述以前年度会计数据。","image":"https://www.guandian.cn/statics/index2022/img/search.png","points":["归属于上市公司股东的净利润2.08亿元，同比下降0.40%","第三季度单季，公司营业收入24.11亿元，同比下降1.08%","归母净利润3669.80万元，同比下降44.42%"],"points_source":"extract"},{"title":"【微奶价】3.26元/公斤！内蒙古第四季度生鲜乳交易参考价确定","summary":"搜狐网报道，内蒙古第四季度生鲜乳交易参考价确定为每公斤3.26元。这一价格变动对婴幼儿奶粉行业从业者有重要影响，意味着原料成本的变化，需关注乳制品供应链成本调整。生鲜乳是婴幼儿奶粉的主要原料，价格波动直接影响生产成本和产品定价策略。从业者需密切关注原料市场动态，优化供应链管理，以应对成本变化带来的挑战。","source_id":"gnews_cn_supply","source_name":"搜狐网","source_url":"https://news.google.com/rss/search?q=(%E5%8E%9F%E5%A5%B6%20OR%20%E7%94%9F%E9%B2%9C%E4%B9%B3%20OR%20%E4%B9%B3%E6%B8%85%20OR%20%E4%B9%B3%E9%93%81%E8%9B%8B%E7%99%BD%20OR%20%E5%A4%A7%E5%8C%85%E7%B2%89%20OR%20%E5%8E%9F%E6%96%99%E5%A5%B6%E7%B2%89)%20(%E4%BB%B7%E6%A0%BC%20OR%20%E6%8B%8D%E5%8D%96%20OR%20%E4%BE%9B%E5%BA%94%20OR%20%E4%BA%A7%E8%83%BD)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.sohu.com/a/1093950304_122014422?scm=10001.325_13-325_13.0.0-0-0-0-0.5_1334","published_at":"2026-10-28T17:35:40+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:32+08:00","language":"zh","author":"","tags":["市场数据","供应链"],"priority":"P0","score":4.8,"matched":["生鲜乳"],"id":"335a5003a6eb2318","title_zh":"【微奶价】3.26元/公斤！内蒙古第四季度生鲜乳交易参考价确定","summary_source":"llm","summary_kind":"brief","translated":true,"link_resolved":true,"body":"10月26日，内蒙古自治区生鲜乳价格协调委员会召开全区第四季度生鲜乳价格协商会议。经第三方机构科学测算、与会委员共同协商，商定2026年第四季度生鲜乳交易参考价为3.26元/公斤。鼓励优质优价，因指标差异等市场因素，可以上下浮动，上浮不设限，下浮不超过3%。 请生鲜乳购销双方以交易参考价为基础，按照质价相符、以质论价、互利共赢原则，协商确定生鲜乳实际收购价格。","image":"https://q8.itc.cn/q_70/images03/20261028/8126a86c193c4886894f9113a714ec59.png","points":["经第三方机构科学测算、与会委员共同协商，商定2026年第四季度生鲜乳交易参考价为3.26元/…","鼓励优质优价，因指标差异等市场因素，可以上下浮动，上浮不设限，下浮不超过3%","请生鲜乳购销双方以交易参考价为基础，按照质价相符、以质论价、互利共赢原则，协商确定生鲜乳实际…"],"points_source":"extract"},{"title":"Danone sales rise as health-focused brands and price increases drive growth","summary":"达能公司报告销售额强劲增长，主要得益于其健康品牌组合和价格提升。这一增长反映了消费者对健康产品的持续需求，以及企业通过价格策略应对市场变化的能力。对于婴幼儿奶粉行业的从业者而言，这意味着健康定位和灵活定价策略的重要性日益凸显，需要密切关注市场动态和消费者偏好变化，及时调整产品策略以适应市场需求。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/28/danone-q3-sales-rise-4-as-health-focused-brands-and-price-increases-drive-growth","published_at":"2026-10-28T17:27:56+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:07+08:00","language":"en","author":"","tags":["品牌动态","市场数据","政策法规"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/7VVKPWGRV5EWDHEPVBPXRP4BUE.jpg?auth=c2327b005da8f896e88fcb8b22ed914d5d574e2f90f22ed02976376c9ca84682&smart=true&width=2120&height=1414","score":4.8,"matched":["danone"],"id":"5af5a2e6379ec805","title_zh":"达能销售额增长 健康品牌和提价推动增长","summary_source":"llm","summary_kind":"brief","points":["达能健康品牌推动增长","提价策略成效显著"],"points_source":"llm","translated":true},{"title":"【微奶价】3.26元/公斤！内蒙古第四季度生鲜乳交易参考价确定","summary":"内蒙古发布第四季度生鲜乳交易参考价，每公斤3.26元。该价格反映了当前原奶市场的供需状况，对上游牧场经营和下游乳企成本控制具有参考意义。","source_id":"gnews_cn_supply","source_name":"新浪财经","source_url":"https://news.google.com/rss/search?q=(%E5%8E%9F%E5%A5%B6%20OR%20%E7%94%9F%E9%B2%9C%E4%B9%B3%20OR%20%E4%B9%B3%E6%B8%85%20OR%20%E4%B9%B3%E9%93%81%E8%9B%8B%E7%99%BD%20OR%20%E5%A4%A7%E5%8C%85%E7%B2%89%20OR%20%E5%8E%9F%E6%96%99%E5%A5%B6%E7%B2%89)%20(%E4%BB%B7%E6%A0%BC%20OR%20%E6%8B%8D%E5%8D%96%20OR%20%E4%BE%9B%E5%BA%94%20OR%20%E4%BA%A7%E8%83%BD)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://finance.sina.com.cn/roll/2026-10-28/doc-iniwuqvu3305979.shtml","published_at":"2026-10-28T16:55:50+08:00","published_guessed":false,"fetched_at":"2026-10-30T05:00:17+08:00","language":"zh","author":"","tags":["市场数据"],"priority":"P0","score":4.8,"matched":["生鲜乳"],"id":"6a4e777ce1ec6625","title_zh":"内蒙古第四季度生鲜乳交易参考价确定","summary_source":"llm","summary_kind":"brief","points":["内蒙古第四季度生鲜乳交易参考价确定为3.26元/公斤","原奶价格波动直接影响牧场盈利与乳企成本结构","参考价机制为行业提供价格风向标与决策依据"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月26日，内蒙古自治区生鲜乳价格协调委员会召开全区第四季度生鲜乳价格协商会议。经第三方机构科学测算、与会委员共同协商， 商定2026年第四季度生鲜乳交易参考价为 3.26元/公斤 。 鼓励优质优价，因指标差异等市场因素，可以上下浮动，上浮不设限， 下浮不超过3%。 请生鲜乳购销双方以交易参考价为基础，按照质价相符、以质论价、互利共赢原则，协商确定生鲜乳实际收购价格。 24小时滚动播报最新的财经资讯和视频，更多粉丝福利扫描二维码关注（sinafinance）","image":"https://n.sinaimg.cn/front20261028ac/460/w1030h1030/20261028/6fb6-50bc8bbcda074dca8367f9f912fce6f5.jpg"},{"title":"中印尼企业合建纸尿裤工厂投产在即","summary":"中国与印尼企业合作建设的纸尿裤工厂即将投产，显示两国在婴幼儿用品供应链领域的合作深化。这一事件对跨境母婴行业有重要意义，表明供应链多元化布局有助于降低成本、提升效率。对从业者而言，这意味着更多市场机会和更优化的资源配置选择。按照规划，这条高速产线满负荷运转，年产能最高可达到18亿片纸尿裤。企业长期目标是陆续配齐10条全自动生产线，完成上下游垂直整合。MMIX原本是进口授权产品的大型经销商，这次转型自主生产，是公司最重要的增长引擎。","source_id":"gnews_cn_baby_category","source_name":"每日印尼","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.indonesia-daily.com/page_52664.html","published_at":"2026-10-28T14:56:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:30+08:00","language":"zh","author":"","tags":["供应链","跨境电商","海外动态"],"priority":"P1","score":4.8,"matched":["纸尿裤"],"id":"b15a55d803ecdf48","title_zh":"中印尼企业合建纸尿裤工厂投产在即","summary_source":"llm","summary_kind":"brief","points":["中印尼企业合建纸尿裤工厂","跨境行业重要意义"],"points_source":"llm","translated":true,"link_resolved":true,"body":"印尼上市公司PT Multi Medika Internasional Tbk（MMIX）加速业务转型，正抓紧完工和中国福建恒安集团合资建设的纸尿裤工厂，合资主体为PT Multi Nice Paper Indonesia（MNPI）。 项目选址万丹省唐格朗，占地1公顷，产线设计速度可达每分钟1000片纸尿裤，为印尼当前速度最快的纸尿裤生产线。MMIX公司秘书表示，该项目是企业加码个人护理赛道、打造可持续业务组合的重要布局。这座一体化工厂落地后，将实现主力品牌MIUBaby婴儿纸尿裤本地化生产。 该品牌目前已经在Alfamart、Indomaret等大型连锁商超拿到独家分销渠道，本地化生产将进一步巩固渠道优势。工厂初期主打婴儿纸尿裤，后续会逐步拓展成人纸尿裤、女性卫生巾、湿巾等品类。按照规划，这条高速产线满负荷运转，年产能最高可达到18亿片纸尿裤。企业长期目标是陆续配齐10条全自动生产线，完成上下游垂直整合。通过自产模式，企业可以更好管控生产成本、把控产品品质，显著降低销售成本，增厚净利润空间。 MMIX原本是进口授权产品的大型经销商，这次转型自主生产，是公司最重要的增长引擎。母婴护理板块目标在2026年贡献公司总营收的40%–50%。管理层看好印尼本土市场，随着家长对高品质母婴产品需求提升，期待母婴护理业务保持11%及以上的增速。该合资项目进展持续受到资本市场关注，项目推进消息在印尼交易所发布后，获得市场积极反馈。 依托中方成熟的制造技术，叠加印尼本土成熟零售网络，这家合资工厂有望改变印尼纸尿裤市场格局，也成为中企在印尼快消品本土化投资的典型案例。","image":"https://www.indonesia-daily.com/wp-content/uploads/2026/10/08_________________-2.webp"},{"title":"庖根闻笛丨跨境营养品“翻车”启示录","summary":"跨境营养品市场近年来出现产品质量不过关、虚假宣传等问题，给消费者和行业带来负面影响。这提醒从业者必须重视产品质量和合规性，加强供应链管理，避免类似事件发生。关注行业动态，及时调整策略，是维护市场信誉和长远发展的关键。这一事件反映了跨境营养品市场存在的风险，从业者需提高警惕，加强内部管理，确保产品符合目标市场的法规要求，以维护行业声誉和消费者信任。","source_id":"muyingqianyan","source_name":"母婴前沿","source_url":"https://www.muyingqianyan.com/feed","original_url":"https://www.muyingqianyan.com/123364.html","published_at":"2026-10-28T10:35:50+08:00","published_guessed":false,"fetched_at":"2026-10-28T11:45:19+08:00","language":"zh","author":"前沿, 母婴","tags":["跨境电商","质量安全","品牌动态"],"priority":"P0","score":4.8,"matched":["营养品"],"id":"0bcc13c29cc7fa21","image":"https://www.muyingqianyan.com/wp-content/uploads/2021/07/e6570c2e9d90b442ec5abe68c80669c.png","title_zh":"庖根闻笛丨跨境营养品“翻车”启示录","summary_source":"llm","summary_kind":"brief","points":["跨境营养品市场问题频发","产品质量和合规性受关注","供应链管理需加强"],"points_source":"llm","translated":true},{"title":"宝宝辅食工具必备清单","summary":"虎扑体育发布宝宝辅食工具清单，涵盖各类辅助喂养设备。这类清单为母婴用品销售和推荐提供指导，帮助从业者优化产品组合与营销策略。对跨境母婴行业而言，了解消费者对辅食工具的需求有助于把握市场趋势，开发符合需求的产品和服务。辅食工具是婴幼儿喂养的重要辅助，其市场变化直接反映消费者需求升级，从业者需密切关注此类清单，及时调整产品策略以适应市场变化。","source_id":"gnews_cn_baby_category","source_name":"虎扑体育","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.hupu.com/score-item/common_second/3575610","published_at":"2026-10-28T09:53:53+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:30+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":11.2,"matched":["辅食","宝宝"],"id":"4da94d655e11e2e5","title_zh":"宝宝辅食工具必备清单","summary_source":"llm","summary_kind":"brief","points":["列出宝宝辅食工具清单","涉及辅助喂养设备","指导母婴用品销售","优化产品组合与营销"],"points_source":"llm","translated":true,"link_resolved":true},{"title":"中顺洁柔（云浮）纸业年产5.5 万吨湿巾项目环评公示","summary":"纸业网公示了中顺洁柔（云浮）纸业年产5.5万吨湿巾项目的环境影响评价。该项目涉及湿巾生产，对原料供应链和产品质量安全有直接影响。对母婴行业从业者而言，了解相关企业的生产动态有助于把握行业发展趋势，关注供应链变化。湿巾是婴幼儿日常护理的重要用品，其生产企业的动态变化关系到行业供应链的稳定性和产品质量，从业者需持续关注此类信息，确保供应链安全与合规。","source_id":"gnews_cn_baby_category","source_name":"纸业网","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"http://www.paper.com.cn/news/daynews/2026/261028095119527233.htm","published_at":"2026-10-28T09:52:39+08:00","published_guessed":false,"fetched_at":"2026-10-28T13:00:28+08:00","language":"zh","author":"","tags":["政策法规","供应链","质量安全"],"priority":"P1","score":4.8,"matched":["湿巾"],"id":"c2bb9e9434e156b5","title_zh":"中顺洁柔（云浮）纸业年产5.5万吨湿巾项目环评公示","summary_source":"llm","summary_kind":"brief","points":["湿巾生产项目环评公示"],"points_source":"llm","translated":true,"link_resolved":true,"image":"https://www.paper.com.cn/images/cnpaper.png"},{"title":"DairyNZ Outlines Six Government Priorities As Dairy Export Revenues Reach $28.8B - https://en.edairynews.com/","summary":"新西兰乳业出口收入达到 28.8 亿美元，DairyNZ 列出六项政府优先事项。对从业者意味着需关注新西兰乳业的出口表现和政策导向，这类数据反映了奶源国的市场竞争力和发展潜力。对跨境乳企而言，需关注奶源国的市场动态和政策支持，以把握市场机遇和提升自身竞争力。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://en.edairynews.com/dairynz-outlines-six-government-priorities-as-dairy-export-revenues-reach-28-8b/","published_at":"2026-10-28T07:35:07+08:00","published_guessed":false,"fetched_at":"2026-10-28T09:20:25+08:00","language":"en","author":"","tags":["市场数据","海外动态","跨境电商"],"priority":"P0","score":9.6,"matched":["dairy","dairy export"],"id":"a0eebd30f732fb24","link_resolved":true,"body":"The central pillar of DairyNZ’s briefing to political parties is the demand for regulatory durability that respects agricultural investment horizons. Brown pointed out that commercial dairy enterprises make capital allocation decisions—such as commissioning advanced rotary milking sheds, installing environmental riparian corridors, or constructing automated effluent containment infrastructure—that span decades rather than three-year parliamentary cycles. Continuous regulatory revisions, particularly surrounding freshwater management and resource consents, generate operational uncertainty and stall on-farm capital deployment. The industry is advocating for a clear legislative standard: environmental and resource regulations must be evidence-based, scientifically robust, workable under everyday commercial farming conditions, and resilient enough to remain relevant over a 10-year planning window. The organization’s six core priorities focus directly on addressing structural bottlenecks across the pastoral value chain: practical freshwater and Resource Management Act (RMA) reforms that protect natural waterways while allowing productive land use; a fortified national biosecurity system prepared for emergent biological incursions; immigration and vocational settings that attract skilled labor to rural careers; sustained investment in agricultural science paired with expedited access to productivity-enhancing agritech; resilient rural infrastructure alongside workable, non-punitive pathways to lower on-farm greenhouse gas emissions; and science-grounded animal welfare standards that reflect operational realities. From an environmental compliance and farm systems perspective, dairy producers have already demonstrated significant proactive stewardship, investing millions in stream exclusion fencing, constructed wetlands, and precision nutrient management plans. However, industry leadership warns that policy friction arises when centralized mandates become overly complex, impose redundant compliance reporting, or enforce arbitrary restrictions that ignore regional catchment diversity.","image":"https://en.edairynews.com/wp-content/uploads/2026/10/DairyNZ-outlines-six-government-priorities-as-dairy-export-revenues-reach-28.8B.jpg","summary_source":"llm","summary_kind":"brief","title_zh":"新西兰乳业出口收入达288亿美元","translated":true,"points":["新西兰乳业出口收入28.8亿美元","DairyNZ列六项政府优先事项","关注新西兰乳业出口表现","需关注奶源国政策支持"],"points_source":"llm"},{"title":"Arunachal Dairy Sector Gets ITBP Milk Supply Pact - urbanacres.in","summary":"Arunachal Pradesh has signed an agreement with the Indo-Tibetan Border Police (ITBP) to supply locally produced packaged milk and dairy products to the force’s 31st Battalion, creating an assured inst…","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://urbanacres.in/arunachal-dairy-sector-gets-itbp-market-boost-under-new-milk-pact/","published_at":"2026-10-28T07:15:13+08:00","published_guessed":false,"fetched_at":"2026-10-28T09:20:25+08:00","language":"en","author":"","tags":["供应链"],"priority":"P0","score":16.0,"matched":["dairy","milk supply","dairy sector"],"id":"4c3b84aa51171ce0","summary_source":"extract","link_resolved":true,"body":"Arunachal Pradesh has signed an agreement with the Indo-Tibetan Border Police (ITBP) to supply locally produced packaged milk and dairy products to the force’s 31st Battalion, creating an assured institutional market for dairy cooperatives and milk producers in the state. The memorandum of understanding was signed at the civil secretariat in Itanagar on Monday in the presence of state Animal Husbandry, Veterinary and Dairy Development minister Gabriel D Wangsu and senior government and ITBP officials. A milk supply van was also flagged off at the event. The products will be supplied under the Arun Dairy brand. The state government said the arrangement is intended to strengthen the dairy cooperative sector and provide a dependable market for local milk producers. The agreement connects local production with the regular procurement requirements of a large institutional consumer rather than leaving farmers dependent only on fragmented retail demand. Wangsu said dairy development could help increase farmers’ incomes, generate rural employment and promote economic self-reliance. He also said institutional partnerships could give local producers access to assured markets, encourage dairy entrepreneurship and make dairy farming a more viable livelihood. The partnership also places operational emphasis on the supply chain required to move packaged milk and dairy products from local producers to the ITBP battalion. The source report does not specify the volume of milk to be supplied, the contract period, pricing arrangements, the number of participating cooperatives or the locations from which the products will be sourced. ITBP deputy inspector general for the North East Frontier, Abu Sufian, highlighted the importance of linking local dairy production with the force’s institutional requirements. The agreement therefore serves both a procurement function for the battalion and a market-access function for producers, although the available information does not establish how many farmers or cooperatives will benefit initially. Chief minister Pema Khandu welcomed the initiative in a post on X, appreciating the Animal Husbandry, Veterinary and Dairy Development department and the ITBP for joining hands to facilitate the supply of locally produced milk and dairy products.","image":"https://urbanacres.in/wp-content/uploads/2026/10/urban-acres-news-265289.webp"},{"title":"Conveyors and palletizers keep dairy processing lines moving","summary":"输送机和托盘装载机在乳制品加工中扮演关键角色，其市场预计将持续增长。这些设备对加工线的性能有显著影响，能提升产品流转效率、保证产品完整性和卫生标准。对从业者而言，了解这些设备的技术发展趋势，有助于优化生产线布局，提高生产效率和产品质量。","source_id":"dairyfoods","source_name":"Dairy Foods","source_url":"https://www.dairyfoods.com/","original_url":"https://www.dairyfoods.com/articles/99495-conveyors-and-palletizers-keep-dairy-processing-lines-moving","published_at":"","published_guessed":true,"fetched_at":"2026-10-28T04:52:48+08:00","language":"en","author":"","tags":["供应链","质量安全","跨境电商"],"priority":"P2","score":4.8,"matched":["dairy"],"id":"e08c2fca4c1cf86e","image":"https://www.dairyfoods.com/ext/resources/2026/10/27/Key.jpg?height=635&t=1793129250&width=1200","body":"Conveyors and palletizers are big businesses. According to India-based Mordor Intelligence, the global conveyor market is expected to surpass $10 billion this year, and is forecast to reach $12.5 billion by 2031, growing at a 4.3% compound annual growth rate (CAGR). Meanwhile, palletizer sales are expected to be $2.6 billion globally this year and grow at a 2.2% CAGR to reach $3.2 billion by 2036, predicts Newark, Del.-based Future Markets Insights. According to Tom Munck, director of engineering at Walla Walla, Wash.-based Key Technology, conveyors have a significant impact on the performance of the entire dairy processing line. “Positioned between major processing steps, they help determine how efficiently product reaches sorters, multi-head weighers, packaging machines and other downstream equipment. Modern conveying systems do much more than move products from Point A to Point B,” he tells Dairy Foods . “They manage product flow by distributing, spreading, aligning and feeding product to downstream processes, while also performing functions such as fines removal, dewatering, scalping and lane diversion.” Three priorities consistently drive conveyor selection in dairy processing: uptime, product integrity and sanitation, he adds. “An unplanned conveyor stoppage can disrupt downstream production and reduce overall line efficiency. At the same time, delicate or coated dairy products can lose value when handling causes breakage, degradation or coating loss. Sanitation is equally critical, as cleaning time directly reduces available production time.” When purchasing a conveyor, Ted Yeigh, NW region manager at Columbia Machine Inc., Vancouver, Wash., stresses a big consideration is to ensure you have flexibility for all package types to be palletized and capacity. “When proposing a conveyor and palletizing solution for a dairy producer, we always start with the capacity of the filler. We will look at the maximum capacity of the filler and add roughly 15% to ensure the system stays in balance and can withstand the occasional temporary line interruption.” Columbia Machine palletizing equipment is designed to accommodate a variety of dairy package types. Image courtesy of Columbia Machine Inc. Munck asserts that dairy processors should start with the product, as opposed to the equipment.","summary_source":"llm","title_zh":"输送机和托盘装载机保障乳制品加工线高效运转","points":["输送机市场预计超10亿美元","托盘装载机市场预计达2.6亿美元","设备对加工线性能有显著影响","提升产品流转效率"],"points_source":"llm","translated":true},{"title":"从“母婴用纸”到“敏感时刻”，可心柔如何寻找保湿纸赛道新增量？","summary":"可心柔通过推出“敏肌适用”保湿纸系列，从原先专注母婴市场转向泛人群和泛场景。品牌凭借在保湿纸领域的九年销售额第一优势，洞察到保湿纸低摩擦、减少肌肤刺激的特性适用于更广泛人群。此举旨在抓住出生人口变化下母婴市场增长放缓的机遇，通过迁移护肤行业的“低刺激、肤感友好”消费逻辑，降低新品类用户接受难度，拓展市场空间。对从业者而言，这提示了在细分品类中寻找差异化增长路径的重要性，以及借鉴成熟消费心智破圈的可能性。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/6/20261028/1869538.shtml","published_at":"2026-10-28T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T11:46:04+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":6.4,"matched":["母婴"],"id":"ee3c7990d5c9f041","image":"https://img251118.xingkongmt.com/53134_7d5dd747-dcd5-4ca8-9fca-77ce468481a0.png","body":"生活用纸的竞争，正在从层数、抽数和价格，延伸到越来越细的使用场景。厨房纸、湿厕纸、棉柔巾各有用途，消费者不再只看一张纸能否完成清洁，也开始关注它用在哪里、接触肌肤时体验如何。 有公开数据表明，成熟纸品竞争激烈的背景下增速放缓，而细分品类却仍在快速增长，说明“专纸专用”正在打开新的市场空间。以可心柔为例，近期官宣全球品牌代言人檀健次，并带来全新的“敏肌适用”系列新品，走出原先母婴用纸的舒适区，迈向泛人群“敏肌人群”以及泛场景“敏感时刻”，这也为卫品行业提供了一个观察样本。 保湿纸品类最早的沃土在母婴市场。这与婴幼儿娇嫩肌肤对反复擦拭不伤肤的需求有关。对于普通消费者，一张纸够不够柔或许只是体验差异;对母婴家庭而言，柔软、低摩擦更容易成为明确的购买理由。 可心柔敏锐地洞察到了这一点，并由此在保湿纸领域积累起优势。公开资料显示，品牌2011年开始布局保湿纸，2013年投入千万级资金自研核心保湿技术并开发多分子分层锁水技术;2017年首次做到保湿纸全网销售额第一;按2017—2025年全网销售额计，品牌已连续九年位居保湿纸品类销售额第一。 不过，随着出生人口的变化，母婴赛道的增长天花板正在显现。2025年我国出生人口为792万，较上年减少162万，单纯依托新生儿增量的增长模式具备局限性。传统纸企的思路多为继续拓展纸种，母婴品牌多为不断扩充SKU，而可心柔正在尝试另一种差异化路径：不急着卖更多东西，而是先把已经经过母婴市场验证的“柔护能力”带给更多人群和场景。 这并非被动应对市场变化的无奈选择，而是提前布局增量市场的主动转向。事实上，保湿纸低摩擦、减少肌肤刺激的产品特性，不只适配婴儿，同样能解决成年人各类肌肤脆弱场景的擦拭痛点。只是要让成年人也觉得自己需要一张保湿纸，“宝宝娇嫩”这套理由显然不够了。 于是，品牌需要找到一种成年人更易共鸣的消费语言——大众在护肤消费里已经建立起来的「肌肤友好、低刺激」选购思维。 首先，这源自开头提到的行业洞察——大家对纸巾的需求正在朝着细分和升级发展，随着“专纸专用”成为趋势，消费者开始按照使用部位和场景区分纸品。 尤其在洁面后擦脸、花粉季反复擦鼻、运动或暴晒后等肌肤脆弱的“敏感时刻”，大家除了关心“能不能擦干净”，还会多一层考量：反复擦拭以后，皮肤会不会受刺激? 这也正是这套“护肤”评价体系能够进入纸品赛道的底层前提——它并不是品牌凭空创造出的概念，而是消费者需求本身正在向“低刺激、肤感友好”方向升级。 第二个原因与教育成本有关——直接复用护肤行业已经成熟的消费逻辑，可以大幅降低新品类的用户接受难度。消费者买洁面、面霜和防晒时，早已习惯根据自己的肤质和肌肤状态做选择：是不是敏感肌?使用了什么原料?做过哪些检测?是否适合当前的皮肤状态? 这套决策逻辑已经非常成熟。因此，可心柔不需要重新发明一种消费者语言，只需要把这套认知迁移到纸品上：既然护肤产品需要适配肤质，每天接触面部的那张纸，为什么不以同样标准挑选? 于是，“敏肌适用”被直接写上包装正面，食品级甘油、积雪草等原料、第三方敏感肌适用认证、反复擦拭测试等信息，共同构成这套产品表达。 可心柔不用从零教育消费者，而是借护肤行业已经成熟的心智直接完成破圈。理解成本更低、购买理由更直接。","points":["推出“敏肌适用”保湿纸系列","连续九年保湿纸销售额第一","迁移护肤行业消费逻辑","拓展泛人群和泛场景市场"],"points_source":"llm","summary_source":"llm","title_zh":"从“母婴用纸”到“敏感时刻”，可心柔如何寻找保湿纸赛道新增量？","translated":true},{"title":"宝宝有这3个表现，可能是进入厌奶期了","summary":"厌奶期是婴幼儿成长中的常见生理阶段，表现为奶量下降、注意力分散、生长发育不受明显影响。家长需科学应对，避免过度焦虑或强迫喂奶。了解厌奶期的典型表现有助于平稳度过，同时需关注宝宝的健康状况，必要时就医排查潜在问题。这一知识对跨境母婴从业者有参考价值，有助于提供更专业的喂养指导。第一个核心表现，就是奶量出现无诱因的明显下降。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/2/20261028/1869541.shtml","published_at":"2026-10-28T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T15:36:12+08:00","language":"zh","author":"","tags":["质量安全","品牌动态"],"priority":"P1","score":4.8,"matched":["宝宝"],"id":"eb3f669e62d951f8","body":"厌奶是宝宝成长过程中非常普遍的生理阶段，多数情况下不会对健康造成明显影响，家长不需要过度焦虑，先通过几个典型表现初步判断，再用科学的方式平稳过渡，就能帮宝宝顺利度过这段时期。 第一个核心表现，就是奶量出现无诱因的明显下降。原本规律的进食节奏突然被打破，单次摄入的奶量比日常正常水平减少三分之一甚至更多，且这种低进食状态会持续一周左右的时间。宝宝不会出现明显的哭闹、拒食、痛苦反应，只是在吃奶时表现得兴趣不高，不会主动发起强烈的觅食信号，整体进食状态从主动渴求变成被动接受，没有任何病理状态下的抗拒和不适表现。 第二个典型表现，是吃奶时注意力极易被分散。随着宝宝感知能力快速发育，对外界环境的好奇心明显提升，周围的轻微声响、光线变化、人员走动，都会立刻打断宝宝的吸吮动作，转头将注意力投向其他方向，很难再回到进食状态。整个吃奶过程的耗时明显拉长，有效吸吮的时间大幅缩短，以往十几分钟就能完成的进食，现在可能需要半小时以上才能勉强完成，且全程宝宝都处于容易分心、东张西望的状态，没有任何身体不适的哭闹信号。 第三个常见表现，是整体生长发育状态不受明显影响。虽然短期奶量有所下降，但宝宝的精神状态、睡眠质量、日常互动反应都维持在正常水平，没有出现精神萎靡、频繁哭闹、体重骤降、尿量明显减少的异常情况。体重增长曲线只是短暂出现平缓趋势，不会出现明显的下滑断层，身体各项基础指标都处于对应月龄的正常参考范围内，没有出现病理状态下的发育停滞信号。 确认宝宝进入厌奶期后，家长首先要调整自身心态，不要因为短期奶量下降就陷入过度焦虑，更不要采用强迫喂奶的方式硬灌，这样反而会让宝宝对进食产生更强的抵触心理，拉长厌奶的持续时间。日常喂养时要尽量选择光线柔和、环境安静的空间，减少外界多余的干扰因素，帮助宝宝集中注意力完成进食。同时可以适当调整喂养节奏，采用少量多餐的模式，不用严格卡固定的喂奶间隔，在宝宝表现出饥饿信号时再进行喂养，避免在宝宝没有进食意愿时强行安排喂奶。 日常可以适当增加宝宝白天的活动量，通过俯趴、互动、被动操等方式消耗体能，促进胃肠蠕动，自然唤起宝宝的饥饿感。同时定期检查宝宝的口腔状态，排除出牙不适、口腔炎症等可能影响进食的小问题，确认没有其他病理性干扰。 只要宝宝的精神状态、尿量、体重增长都维持在正常区间，短暂的奶量波动不会对健康造成伤害，随着宝宝的自然成长，厌奶期会平稳度过。如果宝宝拒奶超过72小时，或者出现精神萎靡、体重明显下降的情况，要及时前往医院儿科就诊，排除潜在的健康问题。","points":["如果宝宝拒奶超过72小时，或者出现精神萎靡、体重明显下降的情况，要及时前往医院儿科就诊，排除…","第一个核心表现，就是奶量出现无诱因的明显下降","只要宝宝的精神状态、尿量、体重增长都维持在正常区间，短暂的奶量波动不会对健康造成伤害，随着宝…"],"points_source":"extract","summary_source":"llm","title_zh":"宝宝有这3个表现，可能是进入厌奶期了","translated":true},{"title":"制售假冒母婴产品8人判刑！品牌方点赞检察护企，加码布局长沙","summary":"8名制售假冒母婴产品者被判刑，凸显了法律对母婴产品安全的保护力度。品牌方对此表示赞赏，并决定加大对长沙市场的投入。这一事件警示行业从业者，合规经营是市场立足的根本，同时长沙作为重要市场，将吸引更多优质品牌资源，促进市场健康发展。华声在线10月27日讯（全媒体记者 王智芳 通讯员 刘丽佳 赵一声）今日，记者从长沙县人民检察院获悉，该院办理一起假冒母婴产品注册商标案，一个生产、分销假冒纸尿裤、湿纸巾的犯罪团伙受到法律惩处。","source_id":"gnews_cn_baby_category","source_name":"华声在线","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://hunan.voc.com.cn/news/202610/34101233.html","published_at":"2026-10-27T21:07:07+08:00","published_guessed":false,"fetched_at":"2026-10-28T12:06:48+08:00","language":"zh","author":"","tags":["政策法规","品牌动态","跨境电商"],"priority":"P1","score":6.4,"matched":["母婴"],"id":"44fb9a978177ed52","title_zh":"制售假冒母婴产品8人判刑！品牌方点赞检察护企，加码布局长沙","summary_source":"llm","summary_kind":"brief","points":["8人制售假冒母婴产品被判刑","品牌方点赞检察护企","加码布局长沙市场"],"points_source":"llm","translated":true,"link_resolved":true,"body":"华声在线10月27日讯（全媒体记者 王智芳 通讯员 刘丽佳 赵一声）今日，记者从长沙县人民检察院获悉，该院办理一起假冒母婴产品注册商标案，一个生产、分销假冒纸尿裤、湿纸巾的犯罪团伙受到法律惩处。案件办结后，品牌方深受鼓舞，近期在长沙新增设立工作室，对当地知识产权保护环境充满信心。 杭州某实业股份有限公司旗下某品牌纸尿裤、儿童湿纸巾是国内母婴市场热销产品。张某甲、何某曾是该品牌合作经销商的员工，熟悉相关产品经销模式。 2024年2月，二人纠集张某乙等人，在未取得品牌授权的情况下私自生产假冒某品牌纸尿裤，以“尾货”名义向下游姚某等人销售，姚某等人再通过私域社交平台对外销售。 这批“尾货”投放市场后，销售人员陆续收到一些顾客的投诉和质疑。姚某无视反馈上来的消费者意见，明知货品系假冒注册商标的商品，仍继续对外销售，涉案金额23万余元。 2024年7月，该团伙又谋划生产假冒品牌湿纸巾，委托韩某、尹某加工近11万包，涉案金额41万余元。假冒产品流入市场，严重损害正品的品牌声誉。 长沙县检人民察院检察官王欧雯介绍，办案团队明确取证重点，引导公安机关固定商标权属材料、微信聊天记录、资金流水、发货凭证等关键证据，同步督促开展涉案财物审计，夯实案件办理的证据基础。 2026年2月，长沙县检人民察院对张某甲等8人依法提起公诉，8名被告人全部自愿认罪认罚。 最终，法院以假冒注册商标罪判处5名被告人有期徒刑二年六个月至一年不等，部分适用缓刑；以销售假冒注册商标的商品罪分别判处2名被告人有期徒刑十一个月、十个月；以非法制造、销售非法制造的注册商标标识罪判处1名被告人有期徒刑一年六个月，缓刑二年。 近日，检察官进行回访时，涉案品牌工作人员表示：“检察机关的有力举措，让我们看到了长沙鼓励品牌创新、保护知识产权的决心，我们最近又在长沙新设了一家工作室。”","image":"https://vod-benshipin-xhncloud.voc.com.cn/208/2026/10/27/952b42a0901d8a3b73bd9eff9ecf5768ca9ac7ca1793105926047.jpeg?pid=46553608"},{"title":"Bel Group overtakes Danone as top dairy company for methane emissions action","summary":"贝氏集团在甲烷排放行动方面超越达能，成为乳制品行业的领头羊。这一变化表明全球乳业对环境问题的重视程度提升，对从业者意味着需要关注并采取行动减少碳排放，以符合可持续发展要求。乳制品行业作为碳排放的重要领域，其领军企业的环保行动将带动行业整体向绿色低碳转型，从业者需积极应对环保要求，提升企业可持续发展能力。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/27/bel-group-overtakes-danone-as-top-dairy-company-for-methane-emissions-action","published_at":"2026-10-27T20:21:55+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:38:52+08:00","language":"en","author":"","tags":["政策法规","质量安全","海外动态"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/QTKHRSDXF5DO3OZUS6NXMPGYEI.jpg?auth=3c8310c9e14053e367f4d4e428b0ba4588064e779b56d5b66eb830cf1c1b0354&smart=true&width=2121&height=1414","score":9.6,"matched":["danone","dairy"],"id":"d8ffa400518e3b6d","title_zh":"贝氏集团超越达能成为乳制品行业甲烷排放行动的领头羊","summary_source":"llm","summary_kind":"brief","points":["成为甲烷排放行动领先者","环保和可持续发展成为行业议题"],"points_source":"llm","translated":true},{"title":"Bel Group overtakes Danone as top dairy company for methane emissions action","summary":"贝氏集团在甲烷排放行动方面超越达能，成为乳业在环保领域的领头羊。这一举措显示了乳制品行业对环境问题的重视，对从业者意味着需关注环保法规变化，并可能需要投入更多资源进行减排技术研发和实施。这一事件对行业具有警示作用，提示从业者需积极应对环保挑战，加强环保技术研发和投入，以适应日益严格的环保法规要求。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/27/bel-group-overtakes-danone-as-top-dairy-company-for-methane-emissions-action","published_at":"2026-10-27T20:21:55+08:00","published_guessed":false,"fetched_at":"2026-10-29T01:07:20+08:00","language":"en","author":"","tags":["政策法规","质量安全","供应链"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/QTKHRSDXF5DO3OZUS6NXMPGYEI.jpg?auth=3c8310c9e14053e367f4d4e428b0ba4588064e779b56d5b66eb830cf1c1b0354&smart=true&width=2121&height=1414","score":9.6,"matched":["danone","dairy"],"id":"04d152dbdf128e1e","title_zh":"贝氏集团超越达能成为乳业甲烷排放行动领头羊","summary_source":"llm","summary_kind":"brief","points":["贝氏集团超越达能","乳制品行业关注甲烷排放","环保成为行业重要议题","对跨境乳制品行业有影响"],"points_source":"llm","translated":true},{"title":"【深度】君乐宝与蜜雪集团战略合作升级高端鲜奶走进国民奶茶 - 瑞财经","summary":"君乐宝乳业集团与蜜雪集团签署全面深度战略合作协议，君乐宝旗下高端鲜奶悦鲜活将成为蜜雪集团鲜奶品类核心供应方。双方将在供应链共建、品牌联动、海外拓展等方面展开深度合作。这是继2024年12月双方合资建设“雪王牧场”之后，合作关系的进一步升级。君乐宝已搭建起完整奶业全产业链体系，低温液奶市场占有率在2025年登顶全国第一。蜜雪集团凭借规模领先的门店网络，直面数亿消费者，庞大市场催生对高品质乳制品的持续规模化需求。","source_id":"gnews_cn_brand_fin","source_name":"Google News·乳企财报与资本（中文）","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.rccaijing.com/news-7520781559235540038.html","published_at":"2026-10-27T17:40:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T09:20:05+08:00","language":"zh","author":"","tags":["品牌动态","供应链","跨境电商"],"priority":"P1","score":4.8,"matched":["君乐宝"],"id":"c9576373e11cf458","title_zh":"【深度】君乐宝与蜜雪集团战略合作升级高端鲜奶走进国民奶茶","summary_source":"llm","summary_kind":"brief","points":["君乐宝与蜜雪合作"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月27日，君乐宝乳业集团与蜜雪集团在石家庄签署全面深度战略合作协议，君乐宝旗下高端鲜奶悦鲜活将成为蜜雪集团鲜奶品类核心供应方，双方将在供应链共建、品牌联动、海外拓展等方面展开深度合作。这是继2024年12月双方合资建设“雪王牧场”之后，合作关系的进一步升级。 君乐宝乳业集团与蜜雪集团双方核心管理团队出席活动，蜜雪集团一行参观了君乐宝科学营养研究院、优致牧场及生产工厂，复盘过往合作成果，就长期发展开展座谈交流。 双方合作的基础源于产业能力的高度互补。君乐宝已搭建起完整奶业全产业链体系，截至2026年6月，拥有33座自营牧场、20座生产工厂，奶牛存栏19.8万头，约63%的奶源自给率居国内大型乳企首位，实现全链路自主可控；君乐宝低温液奶市场占有率在2025年登顶全国第一。君乐宝悦鲜活鲜奶2025年跻身中国鲜奶第一品牌，并先后落地中国香港、新加坡市场。 蜜雪集团凭借规模领先的门店网络，直面数亿消费者，庞大市场催生对高品质乳制品的持续规模化需求，同时可将终端消费需求反馈至上游，形成供需双向联动的基础。 “君乐宝的全产业链能力与蜜雪高质平价的产品理念高度契合，这是一次上下游的双向奔赴。”蜜雪集团方面表示，供需直连既释放上游鲜奶产业价值，也为大众茶饮市场带来更丰富的产品可能性。 悦鲜活是君乐宝旗下高端鲜奶品牌，通过中国优质乳工程特优级生乳原料认证，采用INF0.09秒超瞬时杀菌技术，最大程度保留鲜奶中的活性营养与自然鲜甜口感。 得益于双方前期奶源共建，安全优质的鲜奶高效直达终端，蜜雪覆盖全国的庞大门店网络，为君乐宝产品带来全新落地场景，打通家庭消费与茶饮商用两大场景，为低温鲜奶品类拓展全新增长空间。 本次战略合作框架下，君乐宝将扩大供应覆盖，规模化供给蜜雪冰城、幸运咖门店，高端鲜奶悦鲜活进一步渗透国民茶饮渠道。 在供应链合作之外，双方将推进多维度深度合作。研发层面，结合市场需求，聚焦高蛋白产品、冰淇淋原料、风味乳、奶盖、酸奶原料升级等开展联合创新，将乳业技术积淀转化为适配大众的消费产品；品牌端，挖掘联合传播机会，释放双向品牌势能。 “升级后的产品在奶味醇厚感和清爽度上均有明显提升，不少消费者反馈‘能喝得出鲜奶味’‘口感浓郁丝滑’。”蜜雪集团方面表示，鲜奶升级是蜜雪集团围绕“真鲜纯”产品理念、系统性推进全品类原料升级的组成部分，未来将依托君乐宝全产业链实力叠加蜜雪渠道网络，持续拓宽国产鲜奶大众消费市场；放眼海外，以东南亚为重点，探索乳品原料出海、本地化研发与冷链协同。 以本次签约为新起点，双方将探索乳业与茶饮产业合作新模式，释放全链条产业合力，推动高品质鲜奶走向更广市场，为广大消费者带来更多优质选择。","image":"https://ess.leju.com/common/photo/16-1-2U5n3TKJfHJwVtPpQp3lZXZAHZrUe9FCzX2JHsFZgBPDlSA9qY63rU0itRtZ7M3oRfb0LZFNYPkLAQ5j.png"},{"title":"Synlait Milk raises forecast milk price by 25c","summary":"Synlait 奶粉宣布将预测牛奶价格上调 0.25 元。这一价格调整反映了当前乳制品市场的成本压力和供需关系变化。对于依赖乳制品原料的母婴行业从业者，这意味着原材料成本可能增加，需要评估成本控制和产品定价策略。","source_id":"gnews_en_nz_dairy","source_name":"BusinessDesk","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.businessdesk.co.nz/primary-sector/synlait-milk-raises-forecast-milk-price-by-25c/HDCYUMSWLFMC3DBTO22GIC3S74/","published_at":"2026-10-27T09:02:41+08:00","published_guessed":false,"fetched_at":"2026-10-29T23:11:39+08:00","language":"en","author":"","tags":["供应链"],"priority":"P0","score":11.2,"matched":["milk price","synlait"],"id":"019ba32acad17d71","title_zh":"Synlait 奶粉提高预测牛奶价格 0.25 元","summary_source":"llm","summary_kind":"brief","points":["Synlait 奶粉上调预测牛奶价格","乳制品市场成本压力","原材料成本可能增加"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Synlait Milk has upped its forecast base milk price for the 2023-24 season to $7.25 per kilogram of milk solids (kgMS) from $7.00/kgMS. In a notice to the New Zealand stock exchange (NZX), Synlait said the key drivers of the revised forecast were the continued strength in the US dollar and dairy commodity prices recovering after “significant declines” in August. The company added that the second half of the season was \"still to come\". “Forecast confidence will improve, particularly through the peak milk months, as the remaining product is contracted,” it told the NZX. “The revised forecast milk price aims to provide reassurance to Synlait farmer suppliers operating under tough economic market conditions.” In August, Synlait shaved $1.00 off its 2023-24 milk price forecast, taking it from $8.00/kgMS to $7.00/kgMS. The company's opening forecast for the 2023-24 season was $8.00/kgMS. The stock was down 2.3% to $1.29 on Monday evening. NZ First's rail plan costs nearly $4b, adding to the billions of dollars already dumped. Several finalists have grown sales in competitive Asian and North American markets. A wearable can help someone recognise they are running on empty. Sponsored Labour, National face off on Super Sponsored Willis, Edmonds clash over debt, tax cuts Sponsored Labour, National face off on Super","image":"https://www.businessdesk.co.nz/resizer/v2/LZW2VVXX7JKCLMS6K37KH6TMZE.png?auth=c7b0b0c7ebff14070b4e154541cbcf56c6522c07d736523243065cb5f9bcdadc&width=1200&height=675&quality=70&smart=true"},{"title":"Fonterra: power outages could threaten New Zealand’s $25 billion dairy exports - Dairynews.today","summary":"新西兰乳企Fonterra警告，因电力中断可能威胁该国价值25亿美元的乳制品出口。这一事件凸显了电力供应对奶业出口的潜在影响，对跨境乳制品行业从业者具有重要警示意义。电力稳定性是保障生产连续性和出口安全的关键因素，从业者需关注能源供应风险，制定应急预案。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://dairynews.today/global/news/fonterra_power_outages_could_threaten_new_zealand_s_25_billion_dairy_exports_6288896.html","published_at":"2026-10-27T08:32:06+08:00","published_guessed":false,"fetched_at":"2026-10-27T09:53:32+08:00","language":"en","author":"","tags":["海外动态","质量安全","供应链"],"priority":"P0","score":9.6,"matched":["dairy","fonterra"],"id":"45b35723d3b00c6d","title_zh":"新西兰 Fonterra：停电可能威胁25亿美元乳制品出口","summary_source":"llm","summary_kind":"brief","points":["电力中断威胁乳制品出口","新西兰乳企Fonterra警告","电力供应对奶业出口影响","能源供应风险与应急预案"],"points_source":"llm","translated":true,"image":"https://lh3.googleusercontent.com/J6_coFbogxhRI9iM864NL_liGXvsQp2AupsKei7z0cNNfDvGUmWUy20nuUhkREQyrpY4bEeIBuc=s0-w300-rw","link_resolved":true,"body":"Matt Bolger, Fonterra’s managing director of co-operative affairs, raised the concerns in the latest Mood of the Boardroom survey and corporate review. He described a change in the company’s energy concerns: attention had moved beyond sharp price increases and pressure on operating margins to whether sufficient energy would be available to keep factories running. Fresh milk cannot wait through an extended shutdown, particularly during the spring production peak. Fonterra warned that interruptions lasting several days would destroy product rather than simply postpone its manufacture. New Zealand’s energy system has experienced substantial price volatility alongside tightening supplies. During earlier dry periods, reduced water levels in hydroelectric reservoirs coincided with declining domestic gas output. Falling production from large offshore fields, including Pohokura, contributed to the gas contraction. Wholesale electricity prices rose above $800–900 per megawatt-hour in those conditions. Fonterra’s warning concerns both electricity transmission and generation constraints, as well as the reliability of commercial gas supplies. The co-operative has spent hundreds of millions of dollars replacing coal boilers at major production facilities with industrial electrode boilers and biomass equipment as part of compliance with national emissions-reduction requirements. Those investments reduced its direct emissions. However, the shift towards electric processing equipment has also increased its dependence on a grid facing capacity limitations when demand peaks. Fonterra identified that dependence as a growing operational exposure as its manufacturing sites move away from coal. Bolger said markets with tariffs below 10% account for only about 14% of worldwide dairy consumption accessible to New Zealand exporters on those terms. Against that restricted market access, he stressed the importance of dependable deliveries and meeting customer contracts in Asia, the Americas and the Middle East. Fonterra warned that factory stoppages prompting declarations of force majeure could lead customers to turn to European or American suppliers. It also warned that such disruption could weaken the premiums associated with New Zealand dairy products, built up over decades. Dairy exports earned approximately $25 billion in the 2026 financial year."},{"title":"Fonterra Warns Energy Outages Could Threaten Dairy Processing - en.edairynews.com","summary":"恒天然公司在新西兰奶源新闻网站上发布警告，称能源中断可能对乳制品加工构成威胁。这一事件凸显了能源供应对乳制品行业的依赖性，对依赖稳定电力进行生产加工的从业者而言，能源安全成为影响生产稳定性的关键因素。乳制品加工需要大量电力支持，如挤奶、发酵、包装等环节，任何能源供应的中断都可能造成生产停滞，影响产品质量和供应稳定性。对于跨境乳制品行业从业者来说，关注能源供应的稳定性，并制定应急预案，是保障供应链安全的重要措施之一。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://en.edairynews.com/fonterra-warns-energy-outages-could-threaten-dairy-processing/","published_at":"2026-10-27T06:31:25+08:00","published_guessed":false,"fetched_at":"2026-10-27T09:53:32+08:00","language":"en","author":"","tags":["质量安全","供应链","海外动态"],"priority":"P0","score":9.6,"matched":["dairy","fonterra"],"id":"bbc7c9ea5199dd6c","title_zh":"恒天然警告能源中断可能威胁乳制品加工","summary_source":"llm","summary_kind":"brief","points":["能源中断威胁乳制品加工","依赖稳定电力生产加工","影响产品质量和供应稳定性","需制定应急预案保障供应链安全"],"points_source":"llm","translated":true,"image":"https://lh3.googleusercontent.com/J6_coFbogxhRI9iM864NL_liGXvsQp2AupsKei7z0cNNfDvGUmWUy20nuUhkREQyrpY4bEeIBuc=s0-w300-rw","link_resolved":true,"body":"The vulnerability comes after years of extreme price swings and structural tightening across New Zealand’s energy complex. In previous dry-year scenarios, when hydro storage lake levels fell and domestic natural gas production contracted—accelerated by the sustained decline of major offshore fields like Pohokura—wholesale power prices spiked past $800 to $900 per megawatt-hour. However, the operational risks have become more acute due to the dairy sector’s rapid progress in decarbonization. In compliance with national emissions reduction mandates, Fonterra has invested hundreds of millions of dollars replacing legacy coal-fired boilers across key manufacturing sites with large-scale industrial electrode boilers and biomass systems. While this capital expenditure significantly lowered the cooperative’s direct emissions profile, it concentrated processing operations into heavy reliance on a national transmission and electrical generation grid that faces capacity constraints during peak demand windows. From an international trade and commercial competitiveness perspective, processing disruptions present severe market risks because New Zealand operates within a narrow global access framework. Bolger noted that New Zealand exporters currently enjoy low-tariff access (below 10 percent) to only approximately 14 percent of total global dairy consumption. When trade barriers and protective tariffs limit market entry, international competitiveness depends on uncompromised supply-chain dependability, just-in-time delivery, and strict adherence to commercial customer contracts across Asia, the Americas, and the Middle East. If processing shutdowns or power cuts force supply force majeure declarations, international buyers will seek alternative suppliers in Europe or the United States, eroding brand premiums that New Zealand dairy has spent decades establishing. From an enterprise finance and macroeconomic perspective, the stakes extend far beyond the cooperative’s immediate corporate balance sheet. In fiscal year 2026, dairy export earnings generated roughly $25 billion, with approximately $19.6 billion flowing directly back into the domestic economy through farmgate milk payments, transport networks, rural services, and regional wages—representing nearly 78 cents of every export dollar earned."},{"title":"韩国大米无机砷含量远低于法定标准确保辅食安全","summary":"韩国大米无机砷含量远低于法定标准，为婴幼儿辅食安全提供了有力保障。这一发现对跨境母婴行业具有重要意义，意味着来自韩国的婴幼儿食品具有更高的安全标准，有助于提升消费者信心，增强市场竞争力。对从业者而言，选择符合高标准的进口原料是保障产品安全、赢得市场信任的关键。","source_id":"gnews_cn_baby_category","source_name":"www.famtimes.co.kr","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.famtimes.co.kr/zh/news/articleView.html?idxno=703480","published_at":"2026-10-27T06:21:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T12:06:48+08:00","language":"zh","author":"","tags":["质量安全","跨境电商","海外动态"],"priority":"P1","score":6.4,"matched":["辅食"],"id":"93922ea95db2cadb","title_zh":"韩国大米无机砷含量远低于法定标准确保辅食安全","summary_source":"llm","summary_kind":"brief","points":["韩国大米无机砷含量低于法定标准","确保婴幼儿辅食安全"],"points_source":"llm","translated":true,"link_resolved":true},{"title":"Technology underpins Dutch dairy farm productivity","summary":"荷兰200公顷家庭牧场通过科技手段提升奶牛生产效率，GPS系统确保草地利用率提高10-15%，SmartTag和SmartSight技术帮助监控牛群健康，减少人工干预。荷兰乳农的实践表明，科技是提高奶牛健康和生产效率的关键，对跨境乳制品行业从业者启示是，技术应用能显著提升生产力和产品质量。","source_id":"farmersweekly_nz","source_name":"Farmers Weekly NZ·乳业","source_url":"https://www.farmersweekly.co.nz/tag/dairy/feed/","original_url":"https://www.farmersweekly.co.nz/meeting-the-markets/europe-tracking-tomorrows-food-trends/technology-underpins-dutch-dairy-farm-productivity","published_at":"2026-10-27T05:24:51+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:39:41+08:00","language":"en","author":"Neal Wallace","tags":["质量安全","海外动态"],"priority":"P0","score":12.7,"matched":["dairy","milk production","dairy farm"],"id":"ab46a35dd90c4154","title_zh":"荷兰牧场应用科技提升效率","summary_source":"llm","summary_kind":"brief","points":["科技提升牧场管理效率","平衡奶牛产量与寿命","智能化管理应用广泛","注重奶牛福利与产量平衡"],"points_source":"llm","translated":true,"body":"It is the finer details that really matter to Mathijs Meiser and his partner Florien Bleijenberg. They, along with Meiser’s parents Bennie and Elly, run a 200 hectare family dairy farm in northwestern Netherlands, milking 350 cows three times a day all year round. Last year the herd produced 4 million litres or 11,500kg/milk/cow with 4.5% fat and 3.5% protein. Their motivation is to be as efficient as possible. “We don’t want any losses, anywhere,” Meiser said. The cows are in milk for 328 days. He is confident production could reach 12,000 to 13,000kg/milk/cow, but that would shorten their lives and require higher replacement rates. Cows first calve at 21 months of age, four months earlier than the national average. In her lifetime, Meiser said, a cow will produce 64,000kg/milk, nearly double the Netherlands average of 36,000kg/milk. Technology is essential to keep cows healthy and production high. For example, a GPS system in the farm’s tractor ensures it follows the same tramlines every time it enters a paddock, harvesting grass or making silage. By following the same wheel tracks, pasture yield is 10-15% higher. Using Nedap’s SmartTag collars and SmartSight camera monitoring for lameness, provides peace of mind with a large herd. “We can’t always be in the barn, so it tells us when there is a sick cow or something we need to look at,” Meiser said. Previously he would trim the feet of his whole herd twice a year, but SmartSight technology means he focuses only on those that need it. He said he can make money at the current milk price of NZ92 cents per litre.","image":"https://www.farmersweekly.co.nz/wp-content/uploads/2026/10/Meiser1-scaled.jpg"},{"title":"Synlait’s Longest-Serving Employee Joins Executive Team - Rural News Group","summary":"新西兰Synlait乳业任命服务近18年的员工David Williams为乳品供应与可持续发展总经理，负责两大商业牧场、近200位奶农供应商及可持续发展工作。Williams自2008年加入时公司尚在起步阶段，如今公司经历财务波动，得益于股东Bright Dairy和A2 Milk的再投资及业务重心转移，已实现盈利。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.ruralnewsgroup.co.nz/dairy-news/dairy-general-news/synlait-david-williams-general-manager-milk-supply-sustainability","published_at":"2026-10-27T04:55:55+08:00","published_guessed":false,"fetched_at":"2026-10-27T05:45:29+08:00","language":"en","author":"","tags":["品牌动态","质量安全","供应链"],"priority":"P0","score":4.8,"matched":["synlait"],"id":"2bebd9b763655375","title_zh":"Synlait公司资深员工加入高管团队","summary_source":"llm","summary_kind":"brief","points":["Synlait任命任职时间最长的员工加入高管团队","乳业企业高管变动可能影响供应链运营策略","新西兰乳企人事调整是行业关注焦点"],"points_source":"llm","translated":true,"link_resolved":true,"body":"David Williams has been appointed general manager of milk supply and sustainability, in charge of the team of 28 people which runs Synlait’s two commercial dairy farms, supports its nearly 200 farmer suppliers and leads its sustainability workstreams. Williams jointed Synlait in March 2008 when the Dunsandel company was primarily a dairy farm owner and its first processing plant was still under construction. At that time, he explains, the company had nine dairy farms, was in the process of converting another six for the following season, and the company’s Dunsandel plant was still being kitted out with the first drier due to come online in August 2008. In the 2008-09 season it began processing milk from 60 farms, its own 15 plus another 45 contracted suppliers. “My role back then was everything to do with milk supply. I was it,” he told Dairy News . “Everything to do with all the relationships with farmers and contracting the milk, and all of the aspects relating to milk quality and RMP [Risk Management Programme] and sustainability, and all of the milk collection. “So, I started in March 2008, and there was quite a lot to do before August.” Williams’ elevation to the executive this year comes as the company is coming out of a difficult period, having reported a net loss after tax of $75.4 million for the year to July 31 2026 – but that includes a sharp turnaround of a net loss of $80.6 million for the first half of the financial year, then a net profit of $5.2 million in the second half. Williams says the company’s recent problems have been met by reinvestment by shareholders Bright Dairy and A2 Milk, and by refocusing operations on the Dunsandel plant, with all suppliers now in Canterbury. Williams says Synlait has had its ups and downs, but he has stayed through the tough times because he likes the company, what it stands for, and that it has always attracted “really good people who just want to get on with things”. He adds he also enjoys working with the farmer suppliers, who have also shown their loyalty to the company. “Most of the ones that started in 2008 are still there as well.”","image":"https://www.ruralnewsgroup.co.nz/media/k2/items/cache/6af28f1687854deb8f43f934973b2845_XL.jpg"},{"title":"蒙牛、东鹏饮料声明：终止与姆巴佩全部合作","summary":"东鹏饮料集团与蒙牛乳业于10月27日联合宣布终止与法国足球运动员姆巴佩的所有合作。此举涉及品牌营销与体育赞助领域，对相关企业的品牌形象及市场策略产生直接影响。对于跨境母婴与婴幼儿奶粉行业的从业者而言，需关注品牌与明星合作的风险管理及合规性，此类事件可能引发消费者对产品安全及品牌价值观的审视。","source_id":"jiemian","source_name":"界面新闻","source_url":"https://www.jiemian.com/","original_url":"https://www.jiemian.com/article/15246149.html","published_at":"2026-10-27T00:00:00+08:00","published_guessed":true,"fetched_at":"2026-10-27T11:28:09+08:00","language":"zh","author":"","tags":["品牌动态","政策法规","质量安全"],"priority":"P1","score":4.8,"matched":["蒙牛"],"id":"4b9e58b63c0ee289","image":"https://img.jiemian.com/101/original/20261027/52e1e8631086f6917de70fb0db952ffe.png","summary_source":"llm","title_zh":"蒙牛、东鹏饮料声明：终止与姆巴佩全部合作","summary_kind":"brief","points":["终止姆巴佩所有合作","涉及品牌营销与体育赞助","影响品牌形象与市场策略"],"points_source":"llm","translated":true},{"title":"蒙牛：终止与基利安·姆巴佩合作","summary":"蒙牛乳业于10月27日发布声明，宣布终止与法国足球运动员姆巴佩的合作关系。该事件反映出企业在品牌代言选择上的谨慎态度，尤其关注代言人可能引发的社会争议。对于行业从业者，需认识到品牌合作需兼顾市场反响与风险控制，避免潜在的品牌危机。体育明星合作虽能提升关注度，但也可能因个人行为影响品牌声誉。","source_id":"jiemian","source_name":"界面新闻","source_url":"https://www.jiemian.com/","original_url":"https://www.jiemian.com/article/15246105.html","published_at":"2026-10-27T00:00:00+08:00","published_guessed":true,"fetched_at":"2026-10-27T11:28:09+08:00","language":"zh","author":"","tags":["品牌动态","政策法规","质量安全"],"priority":"P1","score":4.8,"matched":["蒙牛"],"id":"24e3fc4acd70e3f6","image":"https://img.jiemian.com/101/original/20261027/1284197b057ab4562cd62568c4f5a48d.png","title_zh":"蒙牛：终止与基利安·姆巴佩合作","summary_source":"llm","summary_kind":"brief","points":["关注品牌代言风险","避免潜在品牌危机"],"points_source":"llm","translated":true}]};
